    ["一场碎尸案的受害者，我在尝试还原他完整的样貌。"] = "Жертва дела о расчленении. Я пытаюсь восстановить его полный внешний вид.",
    ["一场谋杀"] = "Убийство",
    ["一夜的辗转，克莱恩第二天早早醒来，前往占卜俱乐部……"] = "После ночи метаний Клейн рано проснулся на следующий день и отправился в Клуб Провидцев…",
    ["一定可以！"] = "Обязательно получится!",
    ["一定是<P_Yellow>赛琳娜</>寄来的，她说过要邀请我们一家人去参加晚宴，还说学习了新占卜要展示给我看。"] = "Это наверняка прислала <P_Yellow>Селена</>. Она говорила, что хочет пригласить всю нашу семью на ужин, а ещё сказала, что выучила новое гадание и хочет мне показать.",
    ["一家以古物寻找、收集和保护为使命的安保公司，他们需要专业的顾问。"] = "Охранное предприятие, задачей которого является поиск, сбор и защита древностей. Им нужны профессиональные консультанты.",
    ["一家俱乐部亮灯，打开门欢迎贵族入场。\n侍者：希望这场雨没有给您带来不便。\n贵族：当然，我淋不到一滴雨。 "] = "Клуб загорается и открывает свои двери, чтобы приветствовать дворян. \nОфициант: Надеюсь, дождь не причинил вам неудобств. \nБлагородный: Конечно, мне не дождётся ни капли дождя.",
    ["一座山峰上的非人类宫殿……对我的无声注视……扭曲而古怪的蠕虫意象……"] = "Нечеловеческий дворец на вершине горы... молчаливый взгляд на меня... извращенные и странные образы червей...",
    ["一张大合照，这是罗珊小姐……那是伦纳德先生？"] = "Большое групповое фото. Это мисс Розанна... а это мистер Леонард?",
    ["一念即命运？"] = "Одна мысль — и есть судьба?",
    ["一把长枪飞来，贯穿了你的身体"] = "Длинное копье пролетает мимо и пронзает твое тело.",
    ["一支羽毛笔书写：\n“子嗣的仪式成功了！尽管克莱恩发现了贫民区的连续死亡，但这并不影响故事的继续。"] = "Перо написало: \n «Ритуал Наследника удался! Хоть Кляйн и обнаружил непрерывные смерти в гетто, на продолжение истории это не повлияло.",
    ["一旦出现这种情况，非凡力量无法正常稳定使用，你将面临严重危险。"] = "Если это произойдёт, вы не сможете нормально и стабильно использовать Потусторонние силы, и вам будет грозить серьёзная опасность.",
    ["一旦失误，就会一步步走向失控。现代值夜者体系的创立者，查尼斯大主教曾经说过——"] = "Сделав ошибку, человек шаг за шагом будет двигаться к потере контроля. Основатель современной системы Ночного Ястреба, архиепископ Чанис, однажды сказал:",
    ["一束绯红月光射在湖面上。\n而“母亲”的部分意志，也随之降生到湖面之上。"] = "Луч малинового лунного света сияет на озере. \n И часть \"материнской\" воли тоже родилась на озере.",
    ["一段时间不见，你脸上迷茫的表情似乎消退了很多。"] = "Прошло много времени, и выражение растерянности на твоем лице, кажется, немного исчезло.",
    ["一段时间后……"] = "Через некоторое время……",
    ["一点点。"] = "Совсем немного.",
    ["一直放置在外面啊……风吹日照的就会折旧，难怪衣角这片有些发白起线。"] = "Он там уже давно... ветер и солнце обесценят, неудивительно, что этот уголок подола немного побелел и потерся.",
    ["一箩大概有130盒，我只能把空余的地方租给别人……"] = "В корзине около 130 коробок, так что свободное место я могу лишь сдать другим...",
    ["一罐灰烬，卡尔·埃文斯……"] = "Банка праха, Карл Эванс...",
    ["一般来说，魔药配方和材料，尤其是主材料，都非常昂贵。"] = "Вообще говоря, формулы и ингредиенты зелий, особенно основные ингредиенты, очень дороги.",
    ["一般般。我叫丽贝卡，是命运咖啡厅的店主。"] = "Просто средний. Меня зовут Ребекка, и я владелица Fate Café.",
    ["一辆马车飞驰而过，俱乐部里点亮了灯，\n门童：“这糟糕的天气，辛苦您了。”\n俱乐部内，奢靡宴会的角落，\n一只苍白的手在酒杯旁留下了一张“节制”牌"] = "Мимо пролетела карета, и в клубе зажглись огни. \n Швейцар сказал: «Спасибо за плохую погоду». \n В углу клуба, в углу экстравагантного банкета, \n Бледная рука оставила рядом с бокалом с вином карточку «воздержанность».",
    ["一边前往队长办公室，一边讲述了刚刚在俱乐部发生的事情。"] = "По дороге в кабинет капитана они рассказали о том, что только что случилось в клубе.",
    ["三天后？好吧……"] = "Через три дня? Ну ладно...",
    ["上午好，阿兹克先生。"] = "Доброе утро, мистер Азик.",
    ["上次坐在这里时，我连廷根什么样都不知道，现在……"] = "В последний раз, когда я сидел здесь, я даже не знал, что такое Тинген, а теперь...",
    ["上次您帮安娜占卜的事情，已经在俱乐部传开了。"] = "То, что вы в прошлый раз погадали для Анны, уже разнеслось по всему клубу.",
    ["上次案件的受害者，我在尝试还原他完整的样貌。"] = "Жертва последнего дела, я пытаюсь восстановить его полный внешний вид.",
    ["上次见黛拉还是半年前，她更美了。"] = "Последний раз я видел Деллу полгода назад, она стала ещё красивее.",
    ["上车吧。"] = "Садитесь в карету.",
    ["下午好，“倒吊人”先生。"] = "Добрый день, господин Повешенный.",
    ["下午好，“愚者”先生。"] = "Добрый день, Мистер Шут.",
    ["下午好，我叫安洁莉卡，占卜家俱乐部的接待员。"] = "Добрый день, меня зовут Анджелика, я администратор Клуба Провидцев.",
    ["下午我碰到了班森，他说你们要搬去水仙花街了，你是忘记了什么回来取吗？"] = "Сегодня днем ​​я встретил Бенсона, и он сказал, что ты переезжаешь на Даффодил-стрит. Вы что-то забыли и вернулись за этим?",
    ["下楼梯"] = "Спуститься вниз",
    ["下次要不要试试新口味的咖啡，黄油拿铁怎么样？"] = "Хотите в следующий раз попробовать новый вкус кофе? Как насчет латте с маслом?",
    ["不……我不能接受迪伦的身份和命运，我会忘记自己是谁，和大厅里那些人一样……"] = "Нет... Я не могу принять личность и судьбу Дилана, я забуду, кто я, как и те люди в зале...",
    ["不……迪伦！"] = "Нет... Дилан!",
    ["不久后，眼前的海洋消散，露出了一个温暖的房间。"] = "Вскоре после этого океан перед ним рассеялся, открыв теплую комнату.",
    ["不仅是我做的，也可能是另一些我，准确地说，是一群“我们”。"] = "Это сделал не только я, а, возможно, и другие «я». Точнее, целая группа «нас».",
    ["不会闪现的咖啡店主不是好学徒！"] = "Владелец кофейни, не умеющий мгновенно перемещаться, — плохой ученик!",
    ["不同的封印物有着不同的作用。例如隐秘一块区域，或者让目标陷入迷雾迷宫的幻觉。"] = "У разных Запечатанных Артефактов разные эффекты. Например, сокрытие определённой области или погружение цели в иллюзию туманного лабиринта.",
    ["不太一样，我们特地为你订购了一辆最新款，就停在公司门口。"] = "Тут немного другое, мы специально для вас заказали последнюю модель, она припаркована у входа в предприятие.",
    ["不好……罗珊在镜中廷根待的时间也到了临界点，她的意识开始混乱了。"] = "Плохо... время, проведённое Розанной в Зеркальном Тингене, также достигло критической точки, её сознание начинает путаться.",
    ["不好的事物？具体要放……"] = "Что-то плохое? Конкретно что поставить...",
    ["不如我们分头行动，总能找到通路！"] = "Давайте разделимся, так мы наверняка отыщем проход!",
    ["不客气，你的荣幸。"] = "Не за что, это для тебя честь.",
    ["不客气，祝你心情愉快，一切顺利。"] = "Пожалуйста. Надеюсь, у тебя хорошее настроение и все пройдет гладко.",
    ["不对，不是发掘，是扮演！"] = "Нет, это не исследование, это игра!",
    ["不属于这个时代的愚者"] = "Шут, не принадлежащий этой эпохе",
    ["不属于这个时代的愚者。"] = "Шут, не принадлежащий этой эпохе",
    ["不属于这个时代的愚者啊"] = "Шут, не принадлежащий этой эпохе",
    ["不属于这个时代的愚者，灰雾之上的神秘主宰，执掌好运的黄黑之王。"] = "Шут, не принадлежащий этой эпохе, таинственный правитель над серым туманом, Король Желтого и Черного, приносящий удачу.",
    ["不开门"] = "Не открывай дверь",
    ["不必再流浪、不必再挨饿、不必再被买卖……"] = "Больше никаких скитаний, никаких голоданий, никаких покупок и продаж...",
    ["不愧是上个纪元就活跃于大陆舞台的魔女教派……"] = "Как и ожидалось от Секты Демониц, которая действовала на сцене континента с предыдущей эпохи...",
    ["不排除这种可能。“教唆者”擅长诱发每个人心中的恶欲，制造冲突。"] = "Эту возможность нельзя исключать. «Зачинщик» хорош в пробуждении злых желаний в сердце каждого и создании конфликтов.",
    ["不排除这种可能。工厂区的怨念……廷根的灾难……"] = "Эту возможность нельзя исключать. Негодование в фабричном районе... катастрофа в Тингене...",
    ["不敢的话，就回去换个人来调查。"] = "Если не осмеливаетесь, вернитесь и пошлите кого-нибудь еще для расследования.",
    ["不是"] = "Нет",
    ["不是……<P_Heart>（糟糕，我忘记搬家的事了！）</>"] = "Нет... <P_Heart>(О нет, я забыл про переезд!) </>",
    ["不是……难不成都交给我？"] = "Подожди... только не говори мне, что все осталось за мной?",
    ["不是我，是我们……"] = "Не я, это были мы...",
    ["不是的，没有这种不公平的命运。"] = "Нет, такой несправедливой судьбы не бывает.",
    ["不是的，这……是我未婚夫的遗物。"] = "Нет, это... память о моем женихе.",
    ["不是！时代英雄拯救廷根，危机之中尽显风采，畅销作家佛尔思全新力作——《时代守护者》！"] = "Нет! Герой эпохи спасает Тингена, проявив настоящий блеск в разгар кризиса — новый шедевр автора бестселлеров Форса: «Хранитель эпохи»!",
    ["不是，你只是暂时忘记了想要做什么，现在，你还可以继续改变自己的命运！"] = "Нет, ты лишь на время забыл, что хотел сделать. Сейчас ты всё ещё можешь продолжать менять свою судьбу!",
    ["不是，有些是阿蒙分身敲的钟。钟声代表偷盗者途径高序列的能力。"] = "Нет, некоторые удары колокола нанёс клон Амона. Звон колокола означает способность высокой Последовательности Пути Мародера.",
    ["不用上交了，手枪配合猎魔子弹后，真遇到什么危险你也能保护自己，或者给你勇气。"] = "Сдавать его не нужно. Если револьвер соединен с пулями охотника на демонов, вы сможете защитить себя, если действительно столкнетесь с какой-либо опасностью, или это может придать вам смелости.",
    ["不用了，我自己能喝，把药给我吧。"] = "Не надо, я могу выпить и сам. Просто отдай это мне.",
    ["不用了，谢谢"] = "Нет необходимости, спасибо",
    ["不用在意。不过你的灵感很高，有些天赋。"] = "Не обращайте на это внимания. Однако ваше Вдохновение высоко; у тебя есть талант.",
    ["不用在意，这个世界上有很多特殊的人，总是能做别人做不到的事情，比如说你……"] = "Не беспокойтесь об этом. В этом мире есть много особенных людей, которые всегда могут сделать то, что другие не могут, как и ты...",
    ["不用害怕，笔记的事件和影响，到这里就结束了。"] = "Не бойтесь. На этом инциденты и влияние блокнота заканчиваются.",
    ["不用急着选择，平静下来，问问自己的内心。"] = "Не спешите выбирать. Успокойся и спроси свое сердце.",
    ["不用担心，任务里的损失都是可以报销的。"] = "Не волнуйтесь, потери в миссиях можно возместить.",
    ["不用着急，班森，我们还有很多时间。我先去公司啦。"] = "Не торопись, Бенсон, у нас полно времени. Сейчас я направляюсь в компанию.",
    ["不用着急，考虑好以后，到佐特兰街36号2楼“<P_Yellow>黑荆棘安保公司</>”找我。"] = "Никакой спешки. Как только вы обдумаете это, найдите меня по адресу Зутланд-стрит, 36, 2-й этаж, «<P_Yellow>Охранная компания «Чёрный Чертополох»</>».",
    ["不用等多久，我们就能一起去贝克兰德了！"] = "Совсем скоро мы сможем вместе поехать в Бэкланд!",
    ["不用紧张，你很快就能见到你父亲和老管家刻利，要不我们来局昆特牌？"] = "Не нервничайте. Скоро ты увидишься со своим отцом и старым дворецким Кели. Как насчет того, чтобы сыграть в Гвинт?",
    ["不用紧张，只要按照我说的做，就不会有危险。另外记住，不要打扰里面的其他女士。"] = "Не нервничайте, пока вы делаете, как я говорю, никакой опасности не будет. И помните, не беспокойте других дам внутри.",
    ["不用谢，这是我该做的。我想问你，有没有见过一个穿绿裙子的女孩。"] = "Пожалуйста, это то, что мне следует сделать. Я хочу тебя спросить, ты видел девушку в зеленом платье?",
    ["不用谦虚，你果然是个特殊的人。"] = "Не нужно скромничать, вы действительно особенный человек.",
    ["不用麻烦了，非常感谢。"] = "Не надо себя утруждать, большое спасибо.",
    ["不用，我有自己的办法。"] = "Нет, у меня свои пути.",
    ["不知为何，木偶对你的兴趣远远超过了对皮特的。\n它飞扑过来扒住了你，并邀请你拥抱“母亲”。"] = "Отчего-то марионетка проявила к вам куда больший интерес, чем к Питу.\nОна бросилась на вас, вцепилась мертвой хваткой и предложила обнять «Матерь».",
    ["不知道"] = "Не знаю",
    ["不知道“正义”小姐和“倒吊人”有没有找到合适的环境，可惜这个世界没有手机和网络，无法即时通信。"] = "Интересно, нашли ли Мисс Справедливость и Повешенный подходящее окружение? Жаль, что в этом мире нет мобильных телефонов и Интернета, что делает невозможным мгновенное общение.",
    ["不知道是不是我的错觉，自从你来了后，周围的非凡事件发生的频率似乎在直线上升。"] = "Не знаю, кажется мне это или нет, но с тех пор, как ты появился(-лась), частота Потусторонних происшествий вокруг, похоже, резко возросла.",
    ["不算周日的话，一周就是12苏勒。"] = "Не считая воскресенья, это 12 суле в неделю.",
    ["不管你是神灵，还是愚者，我的祈求都不改变，我希望白银之城的所有人摆脱宿命的诅咒，希望天空中出现，出现那些书籍里描述的太阳。"] = "Будь вы божеством или Шутом, моя молитва не изменится: я молю, чтобы жители Города Серебра избавились от проклятия рока, и чтобы в небе взошло... взошло то солнце, о котором пишут в древних книгах.",
    ["不管是“占卜家”，还是“小丑”，都能在马戏团里找到。"] = "Будь то «Провидец» или «Клоун» — и того, и другого можно встретить в цирке.",
    ["不管是危机还是末日，大家都会一起面对。"] = "Будь то кризис или апокалипсис, мы встретим его вместе.",
    ["不管有再多的烦恼，明天终究会来临。"] = "Сколько бы ни было проблем, завтра рано или поздно наступит.",
    ["不能让她看到这些！"] = "Я не могу позволить ей увидеть это!",
    ["不行，不行，得等着梅丽莎一块吃。"] = "Нет-нет, мне нужно подождать, пока Мелисса поест вместе.",
    ["不行，这样擦不干净，需要拿东西遮挡一下。"] = "Нет, оно не будет чистым, если я протру его вот так. Мне нужно чем-то прикрыть это.",
    ["不要"] = "Нет",
    ["不要……求求你们，不要抢我的票……"] = "Не... пожалуйста, не берите мой билет...",
    ["不要介意，我只是喜欢这个，但我的占卜和解读有时候真挺准，真的……"] = "Не обращайте внимания, мне просто это нравится. Но мои гадания и толкования порой бывают удивительно точными, честное слово...",
    ["不要介意，我只是喜欢这个，但我的占卜和解读有时候都挺准，真的……"] = "Неважно, мне это просто нравится, но мои предсказания и интерпретации иногда довольно точны, правда...",
    ["不要再问我为什么了。轮到我问你了——"] = "Хватит спрашивать меня «почему». Теперь моя очередь спрашивать:",
    ["不要奇怪，和风暴之主教会的那帮家伙不同，在我们这里，女士也是可以口头调戏别人的。"] = "Не удивляйтесь. В отличие от парней из церкви Повелителя Штормов, здесь дамы тоже могут словесно дразнить других.",
    ["不要总当自己是诗人，事实上，你还是只会吟诵别人的作品。"] = "Не строй вечно из себя поэта. По правде говоря, ты все еще способен лишь декламировать чужие стихи.",
    ["不要自责，激活仪式是逃离这里的必要环节，这次你做得很好。"] = "Не вините себя. Активация ритуала была необходимым шагом, чтобы сбежать отсюда. На этот раз ты справился очень хорошо.",
    ["不要，请叫我丽贝卡，我还没过十八岁生日呢。"] = "Нет, пожалуйста, зови меня Ребекка. Мне еще не исполнилось восемнадцать.",
    ["不要，非凡者很危险，你做文职吧。"] = "Нет, потусторонние опасны, тебе лучше заняться канцелярской работой.",
    ["不过……"] = "Однако...",
    ["不过……灰雾之上会不会有多个主宰，再加一重保险。"] = "Но... будут ли над серым туманом несколько мастеров плюс дополнительный уровень страховки?",
    ["不过他们估计也没想到，作为首领的“愚者”，竟然才刚刚消化完“占卜家”魔药。"] = "Но они, наверное, не ожидали, что их предводитель «Шут» только что закончил усваивать зелье «Провидца».",
    ["不过去贝克兰德的确是个好主意。"] = "Однако поехать в Бэкланд — действительно хорошая идея.",
    ["不过对你来说，这是一件好事。"] = "Но для тебя это хорошо.",
    ["不过对方的实力暂时不清楚。克莱恩，你等会在远处支援，我会尝试将她拉入梦境。"] = "Но сила противника пока неясна. Клейн, поддержи нас издалека, а я попробую затянуть её в сон.",
    ["不过我也得再努力点了，我打算再买几本会计方面的书籍，进行更深入的学习。"] = "Но мне тоже нужно поднажать: я собираюсь купить еще пару книг по бухгалтерскому учету для более глубокого изучения.",
    ["不过我现在才序列9，可能接收不到……或许把我和灰雾之上那片神秘空间捆绑在一起……"] = "Но сейчас я всего лишь Последовательность 9 и, возможно, не смогу принять это… Может, стоит связать меня с тем таинственным пространством над Серым Туманом…",
    ["不过我的占卜告诉我，这些案件没有超凡因素的影响。"] = "Но моё гадание говорит, что на эти дела не влияли сверхъестественные факторы.",
    ["不过我遇到过两次异常……是因为嫁接的力量不稳定？"] = "Но я столкнулся с двумя аномалиями... Это потому, что сила прививки нестабильна?",
    ["不过没关系，有了脚踏车我卖报能快些，很快就能把钱赚回来的！"] = "Но ничего страшного! С велосипедом я смогу развозить газеты быстрее и мигом всё отработаю!",
    ["不过特里斯就像从廷根蒸发了一样，这件事官方还会继续追查。"] = "Однако Трисси словно испарилась из Тингена. Власти продолжат расследование этого дела.",
    ["不过现在只能从其它线索入手了。伦纳德，你先去一趟警察局，看看最近有没有关于工厂区的异常案件。"] = "Но пока придется взяться за другие зацепки. Леонард, сходи в полицейский участок и узнай, не поступало ли в последнее время странных сообщений из фабричного района.",
    ["不过还是要祝贺你，成为一位真正的非凡者。"] = "И всё же поздравляю тебя: ты стал настоящим Потусторонним.",
    ["不过这本笔记目前也在值夜者组织，而且……之前看到值夜者的保密资料中，没有提供占卜家序列8和7的魔药名称，难道里面还藏着什么秘辛？"] = "Однако эта записная книжка сейчас тоже находится у организации «Ночные ястребы», и... в секретных материалах «Ночных ястребов», которые я видел раньше, не были указаны названия зелий для Провидца Последовательности 8 и 7. Неужели там скрыта ещё какая-то тайна?",
    ["不过，不少野生非凡者很忌惮他们，所以记得隐蔽身份。"] = "Однако многие дикие Потусторонние их весьма опасаются, поэтому не забудь скрывать свою личность.",
    ["不过，你是怎么摆脱封印物影响的？你只是个普通人，却在迷雾中找到了正确的方向。"] = "Но как тебе удалось избавиться от влияния Запечатанного Артефакта? Ты всего лишь обычный человек, однако сумел найти верное направление в тумане.",
    ["不过，你现在这样很好，真的很好。"] = "Однако сейчас ты выглядишь великолепно, действительно великолепно.",
    ["不过，关于这个问题，我倒是很好奇邓恩的回答呢……"] = "Однако, что касается этого вопроса, мне очень любопытен ответ Данна...",
    ["不过，刚才天上出现的是一条蛇，而威尔只是……"] = "Но то, что только что появилось в небе, было змеёй, а Уилл всего лишь...",
    ["不过，感觉还不够精确，最好补充一些<P_Yellow>个人特质</>。"] = "Однако это не кажется достаточно точным. Было бы лучше добавить некоторые личные черты <P_Yellow> </>.",
    ["不过，我必须先将这件事情通报给圣堂，等到他们确认了笔记的保密等级，再考虑能不能给你看。"] = "Однако сначала я должен сообщить об этом Святой Церкви и подождать, пока они подтвердят уровень конфиденциальности записей, прежде чем решать, смогут ли они показать их вам.",
    ["不过，既然灾难无法避免，高塔崩塌之后，才会有重建的希望。"] = "Однако, поскольку катастрофы избежать невозможно, только после обрушения башни можно будет надеяться на восстановление.",
    ["不错，不从众，和我当年一样有性格。而且足够幸运，占卜家的魔药材料还剩两份，否则就要等很久了。"] = "Неплохо, не поддаваться толпе — точно как я в своё время, с характером. К тому же тебе повезло: материалов для Зелья Провидца осталось ещё две порции, иначе пришлось бы долго ждать.",
    ["不错，很听劝，我们分头行动。记住，我们在守护廷根。"] = "Хорошо, очень разумно. Давай разделимся. Помните, мы охраняем Тинген.",
    ["不错，很有品味。"] = "Неплохо, очень вкусно.",
    ["不错，看不出这是个昨天刚死过的倒霉蛋。"] = "Неплохо, даже не скажешь, что это бедняга, который умер буквально вчера.",
    ["不错，精彩的比赛，有做拳击手的潜力。"] = "Неплохо, замечательный матч, у тебя есть потенциал стать боксёром.",
    ["不错，那我们开始今天的课程——制作符咒。"] = "Неплохо, тогда начнём сегодняшний урок — изготовление амулетов.",
    ["不！为什么，为什么我们出生就注定要背负这样的诅咒，要亲手终结自己父母的生命？"] = "Нет! Почему, почему нам суждено с рождения нести такое проклятие и собственными руками кончать жизнь своих родителей?",
    ["不，不对。这是罗塞尔大帝日记里的字符。"] = "Нет, это неправильно. Это персонажи из дневника императора Розеллы.",
    ["不，不，我要先学习这些知识，有了知识才不会被时代淘汰。"] = "Нет-нет, сначала я должен усвоить эти знания. Только со знанием меня не устранит эпоха.",
    ["不，他会回来的。我已经报案了，警察会找到他的。"] = "Нет, он вернется. Я уже сообщил об этом в полицию, они его найдут.",
    ["不，他只是一个租客。这个房间每周要3苏勒10便士，我妻子糊制1箩火柴盒才能拿到2.25便士。"] = "Нет, он всего лишь арендатор. Эта комната стоит 3 шиллинга и 10 пенсов в неделю, а моя жена получает всего 2,25 пенсов за обклейку 1 корзины спичечных коробков.",
    ["不，他和他父亲不一样。他是个很体贴、很讨人喜欢的孩子。"] = "Нет, он не похож на своего отца. Он очень внимательный и милый ребенок.",
    ["不，危机正在酝酿，廷根正面临毁灭的危险。"] = "Нет, назревает кризис, и Тингену грозит опасность разрушения.",
    ["不，她非常警惕，也很强大……至少是序列7的非凡者，追她需要花费一些时间。"] = "Нет, она очень бдительна и к тому же очень сильна... по меньшей мере Потусторонний Последовательности 7. Чтобы выследить её, понадобится время.",
    ["不，我一直都是这么年轻。你要买多少面包？"] = "Нет, я всегда был таким молодым. Сколько хлеба вы хотите купить?",
    ["不，我不想"] = "Нет, я не хочу",
    ["不，我的重点，我的意思是，阁下，我该怎样做才能成为非凡者？"] = "Нет, я хотел сказать... то есть, Ваше Превосходительство, что мне нужно сделать, чтобы стать Потусторонним?",
    ["不，维克罗尔先生只是一个普通的商人。而且解救的事情，他相信警察们更加专业。"] = "Нет, господин Виктор – обычный бизнесмен. Кроме того, что касается спасения, он считает, что полиция более профессиональна.",
    ["不，要不是梅丽莎为我即将到来的面试考虑，本来一周才能吃两回肉的……"] = "Нет, если бы Мелисса не обдумывала мое предстоящее интервью, мясо у нас было бы только два раза в неделю...",
    ["不，还是有共同点的。"] = "Нет, общие черты все же есть.",
    ["不，这是必须的。你想想，你还愿意住现在的公寓吗？连盥洗室都要和好几户公用，而且……"] = "Нет, это необходимо. Подумайте, готовы ли вы по-прежнему жить в своей нынешней квартире? Даже уборную приходится делить на несколько домохозяйств, да к тому же...",
    ["不，那是关于斯蒂姆宫的知识洪流……"] = "Нет, это поток знаний о Паровом Дворце...",
    ["与此同时，在廷根的一角。"] = "Тем временем в одном из уголков Тингена.",
    ["与知识皇冠和刺客途径有关……我怀疑它是一片异化的镜中世界。"] = "Относится к Короне Знаний и пути Ассасина... Я подозреваю, что это отчужденный зеркальный мир.",
    ["专家伪装的身份是——阿霍瓦郡最知名的<P_Yellow>通灵者</>。"] = "Замаскированная личность эксперта — самый известный <P_Yellow>Spirit Medium</> в округе Авва.",
    ["专家？"] = "Эксперт?",
    ["丢失一个念头，小丑和演员就会失去反抗的决心，服从于现状。"] = "Стоит потерять одну мысль, и Клоун с актёром лишатся решимости сопротивляться и покорятся действительности.",
    ["两个人之间连接着一条河水般的支流，这也许代表他们互换了身份和命运？"] = "Двух людей соединяет рукав, подобный речному притоку. Возможно, это значит, что они обменялись личностями и судьбами?",
    ["两周八金镑，还包吃住，这些钱够去趟贝克兰德了。"] = "Восемь фунтов за две недели, включая проживание и питание. Этих денег хватит, чтобы поехать в Бэкланд.",
    ["丰收？"] = "Урожай?",
    ["为了我的安全，邓恩先生邀请我加入他们，成为值夜者的一员。"] = "Ради моей безопасности мистер Данн предложил мне присоединиться к ним и стать членом «Ночные Ястребы».",
    ["为了避免被注视，需要在“隐秘”的权柄下谈论它。"] = "Чтобы нас не наблюдали, нам нужно обсуждать это с соблюдением режима «Секретности».",
    ["为了集中献祭？"] = "Для концентрированной жертвы?",
    ["为什么他们都……"] = "Почему они оба...",
    ["为什么要做绑匪，愉快地当文明人不行吗？"] = "Зачем становиться похитителем? Неужели нельзя просто радоваться жизни и быть цивилизованным человеком?",
    ["为什么这么问，是发生什么事了吗？"] = "Почему ты спрашиваешь? Что-то случилось?",
    ["为什么这里看起来很少有人来，是生意不好吗？"] = "Почему кажется, что сюда приходит так мало людей? Бизнес плохой?",
    ["为什么选择“占卜家”？提醒你，一旦服用了魔药，就没有后悔的机会了。"] = "Почему выбрали «Провидца»? Напоминаю, что как только вы примете Зелье, пути назад уже не будет.",
    ["为什么？"] = "Почему?",
    ["为你嫁接未来命运中的能力，一份足以对抗噩梦污染的力量。"] = "Привить тебе способность из твоей будущей судьбы — силу, достаточную для сопротивления порче кошмара.",
    ["为设计他死亡的姿势，我写了很长的人物小传，背下了全部剧本！"] = "Чтобы продумать его позу в момент смерти, я написал огромную биографию персонажа и выучил весь сценарий!",
    ["丽贝卡在调查小铜镜，得到了另一件封印物“绝望魔镜”的线索。镜中廷根由“知识皇冠”构建，并非是真正的镜中世界。"] = "Ребекка расследует маленькое бронзовое зеркало и получила зацепку о ещё одном Запечатанном Артефакте — «Зеркале отчаяния». Тинген в зеркале построен «Короной знания» и не является настоящим зеркальным миром.",
    ["丽贝卡带着侍者送来两杯咖啡。"] = "Ребекка приносит официанту две чашки кофе.",
    ["丽贝卡提供的线索很及时，这枚小铜镜就是突破口，罗珊应该也有一个。"] = "Зацепка Ребекки оказалась очень своевременной. Это маленькое медное зеркальце — наш ключ к разгадке. У Розанны тоже должно быть такое.",
    ["丽贝卡！你回来了！"] = "Ребекка! Ты вернулась!",
    ["丽贝卡？你也在贝克兰德？"] = "Ребекка? Ты тоже в Бэкланде?",
    ["之前他攒了好久的存款，本来是为去贝克兰德准备的。结果花在了我的脚踏车上……"] = "Он долго копил деньги и изначально собирался поехать в Бэкланд. Но все это в конечном итоге было потрачено на мой велосипед...",
    ["之前刚购置过一些食材……"] = "Я только что купила ингредиенты...",
    ["之前听说，只要有对方的相关物品，就可以尝试占卜他的下落？"] = "Я уже слышал, что если у вас есть предмет, связанный с этим человеком, вы можете попытаться угадать его местонахождение?",
    ["之前的隐秘组织所谋划的廷根灾难，还有堕落造物主…… "] = "Катастрофа в Тингене, задуманная прежней тайной организацией, и Падший Создатель... ",
    ["乖，咳咳，听爸爸的话……找个没人的房间躲好，警察会来带你回家的。"] = "Тише, кхе-кхе, послушай папу... найди пустую комнату и спрячься. Полиция придёт и отведёт тебя домой.",
    ["也可以像邓恩队长说的那样，在路上随便逛逛？说不定就碰到笔记相关的线索了。"] = "Или поступить так, как говорил капитан Данн — просто побродить по улицам? Глядишь, и наткнусь на зацепку к записной книжке.",
    ["也可以解读为不顺利和顺利。这块灵摆就送给你了，更细节的你自己去体验吧。"] = "Это можно истолковать и как неудачу, и как удачу. Этот маятник я дарю тебе, а подробности узнаешь сам.",
    ["也够买辆脚踏车了。但看起来很辛苦，哥哥要报名吗？"] = "Также достаточно купить велосипед. Но это выглядит очень сложно, брат собирается зарегистрироваться?",
    ["也好。"] = "Что ж, тоже неплохо.",
    ["也就是说，我不用害怕会诡异自杀，或者被奇怪的人跟踪了？"] = "Другими словами, мне не нужно беспокоиться о странном самоубийстве или о том, что меня преследуют странные люди?",
    ["也是一群 时刻对抗着危险和疯狂的"] = "а также группа тех, кто постоянно противостоит опасности и безумию",
    ["也比如说我。"] = "И как я тоже.",
    ["也许是因为我在祈求着……期待这样的力量来帮我。"] = "Возможно, это потому, что я молюсь... ожидая, что такая сила поможет мне.",
    ["也许是因为有了好的工作和不错的收入，整个人都变得自信了。"] = "Может быть, это потому, что у меня хорошая работа и приличный доход, поэтому я стал более уверенным в себе.",
    ["也许能迎来机遇"] = "Возможно, появится возможность",
    ["也许能通过报纸了解廷根，买一份看看。"] = "Может быть, я смогу узнать о Тингене из газеты, купить экземпляр и посмотреть.",
    ["习惯就好。"] = "Вы привыкнете к этому.",
    ["书页中夹着什么？"] = "Есть ли что-то запрятанное на страницах?",
    ["买下材料"] = "Купить материалы",
    ["买票"] = "Купить билет",
    ["买票吗，{{先生|女士}}？我这有，不用排队。"] = "Билетик не нужен, {{господин|госпожа}}? У меня есть, без всякой очереди.",
    ["了解皮特"] = "Узнайте о Пите",
    ["了解阿蒙"] = "Узнать об Амоне",
    ["事件"] = "Событие",
    ["事实上，我根本没参加面试。我提前找到了其他工作，今天刚入职，周薪三镑。"] = "На самом деле я вообще не присутствовал на собеседовании. Я заранее нашел другую работу и начал ее только сегодня с еженедельной зарплатой в три фунта.",
    ["事情似乎比我想得更为复杂。"] = "Все кажется сложнее, чем я думал.",
    ["事情结束了？刚才发生了什么？"] = "Все кончено? Что произошло только что?",
    ["事情都告一段落了，队长说不用担心后续的影响和危险，我可以好好睡一觉了。"] = "Дело подошло к концу. Капитан сказал, чтобы я не беспокоился о каком-либо последующем влиянии или опасности и что я могу хорошо выспаться ночью.",
    ["二十多年？！好乱……对了，你见过一个邮差吗？"] = "Больше двадцати лет?! Какая путаница... Кстати, ты не видел одного почтальона?",
    ["二十次？那您一定也曾被这位，为反抗命运而弑父的爱德华所打动吧！"] = "Двадцать раз? Тогда вас, должно быть, тоже тронул Эдвард, убивший отца, чтобы восстать против судьбы!",
    ["二是通过占卜寻找其它获取“小丑”魔药的途径。"] = "Второй способ — с помощью гадания найти другие пути получения Зелья «Клоуна».",
    ["于是我们和伊森他们商量，一起去贷了一笔钱，想要租下这家店。"] = "Итак, мы обсудили это с Итаном и остальными, вместе взяли кредит и захотели арендовать этот магазин.",
    ["于是除了要送笔记的你，韦尔奇和娜娅都当场自杀了，但我不知道你为什么能活下来。"] = "В результате Уэлч и Ная покончили жизнь самоубийством на месте, но я не знаю, почему вы выжили.",
    ["五十分钟？你可以坐车去，这太远了。"] = "Пятьдесят минут? Возьми экипаж, это слишком далеко пешком.",
    ["五月庄园高薪短工，想报名的过来排队登记！"] = "Высокооплачиваемая краткосрочная работа в May Manor, кто хочет записаться, приходите и встаньте в очередь на регистрацию!",
    ["交付药剂"] = "Передать зелье",
    ["交易？什么交易？！你说清楚。"] = "Сделка? Какая сделка?! Объясни толком.",
    ["交给伊妮德"] = "Отдай это Энид",
    ["交给我们。"] = "Оставьте это нам.",
    ["交给我，我现在做饭的手艺也很不错，放心！"] = "Оставьте это мне. Мои кулинарные навыки теперь довольно хороши, не волнуйтесь!",
    ["交通和餐饮补贴才3苏勒？那“正义”女士给的2万……零花钱？"] = "Субсидия на транспорт и питание составляет всего 3 суле? Тогда 20 000... карманных денег, подаренных Мисс Джастис?",
    ["人们生活在巨大的差距里，但城市看起来还算平静。"] = "Люди живут в огромных различиях, но город выглядит достаточно спокойным.",
    ["人已经走了？"] = "Человек уже ушел?",
    ["人群中突然冒出一阵黑气，周围人惊恐的退后"] = "В толпе внезапно вспыхивает всплеск черной энергии, и люди вокруг в ужасе отступают.",
    ["人群中，皮特牵着伊妮德一闪而过。"] = "В толпе мелькает Пит, держащий Ислин.",
    ["什么东西在响，真吵。"] = "Что это звенит? Так шумно.",
    ["什么交易？"] = "Что за сделка?",
    ["什么人？轻视我们的人？看不起我们的人？拿了钱就翻脸的人？"] = "Что за человек? Кто-то, кто смотрит на нас свысока? Кто-то, кто презирает нас? Тот, кто отворачивается после того, как взял деньги?",
    ["什么情况？周围的灰雾是什么？无法离开这里！"] = "Что происходит? Что за серый туман вокруг? Не могу уйти отсюда!",
    ["什么猜测？"] = "Какие догадки?",
    ["什么痕迹也没留下，背后一定有非凡力量的影响和干扰。"] = "Не осталось никаких следов — за этим наверняка стоит влияние и вмешательство потусторонней силы.",
    ["什么蛆？！我是善意的天使！"] = "Какой ещё червь?! Я добрый ангел!",
    ["什么？"] = "Что?",
    ["什么？我也变成阿蒙分身了？！"] = "Что? Я тоже превратился в аватар Амона?!",
    ["今天天气不错，在危机之后，城市需要修复，我们也需要休整。"] = "Погода сегодня хорошая. После кризиса город нуждается в ремонте, а нам тоже нужно отдыхать.",
    ["今天奥利安娜太太忙晕了，我来帮弗莱买一些办公用品。"] = "Миссис Орианна сегодня была занята, поэтому я пришел помочь Фраю купить канцелярские товары.",
    ["今天很晚了，你们可以先回家，明天休息半天。"] = "Сегодня очень поздно, ты можешь сначала пойти домой, а завтра взять полдня выходного.",
    ["今天是你第一天入职，可以先熟悉一下。"] = "Сегодня ваш первый день на работе, поэтому сначала вы можете ознакомиться с вещами.",
    ["今天是意外情况，以后应该不会、不经常这样，我挺喜欢这份工作。"] = "Сегодня произошла случайная ситуация; в будущем это не должно случаться часто. Мне очень нравится эта работа.",
    ["今天的面试在<P_Yellow>行政办公室</>，你沿着主路一直走就到了。"] = "Сегодняшнее интервью пройдет в административном офисе <P_Yellow></>. Просто следуйте по главной дороге, и вы будете там.",
    ["今天，我们有会员还带着他的朋友慕名前来。"] = "Сегодня у нас есть участник, который даже привел сюда своего друга, узнав о вашей репутации.",
    ["今晚你不用值班了，去跟科恩黎换一下，现在就回家休息吧。"] = "Сегодня тебе не нужно дежурить. Поменяйся с Кенли и ступай домой отдыхать.",
    ["今晚真开心啊，班森回家了，梅丽莎也很开心的样子。"] = "Сегодняшний вечер был таким счастливым. Бенсон вернулся домой, и Мелисса тоже выглядела очень счастливой.",
    ["从上周，嗯，也许是上上周开始，她常说这里很闷，喘不过气来。"] = "С прошлой недели, ну, может быть, с позапрошлой, она часто говорила, что здесь душно и она не может дышать.",
    ["从各个方面来说，加入值夜者都是现阶段最好的选择。"] = "Во всех аспектах присоединение к «Ночным ястребам» — лучший выбор на данном этапе.",
    ["从文职人员转为值夜者后，薪资应该也会有提升。"] = "После перехода из гражданских служащих в Ночные Ястребы жалованье тоже должно вырасти.",
    ["从现在开始，我就是克莱恩了。"] = "С этого момента я Клейн.",
    ["从现场痕迹看，他们是自杀——以一种恐怖、诡异的方式。"] = "Судя по следам на месте происшествия, они покончили с собой... жутким и зловещим образом.",
    ["仔细回想"] = "Подумайте внимательно",
    ["仔细辨认"] = "Тщательно определите",
    ["他、他是一位和蔼的、客气的、真正的绅士，他是很多会员的精神导师……"] = "Он добрый, вежливый и настоящий джентльмен. Он является духовным наставником многих членов...",
    ["他、他还那么年轻……怎么会……"] = "Он, он был еще так молод... как он мог...",
    ["他也曾是一位普通人，有自己的家人和朋友。"] = "Когда-то он тоже был обычным человеком со своей семьей и друзьями.",
    ["他们……他们都变成了你的分身？！"] = "Они... они все стали твоими копиями?!",
    ["他们叫什么……猎龙帮？"] = "Как их называют... Банда охотников на драконов?",
    ["他们在你眼中毫无价值，只是被寄生的玩具，但他们有自己的人生，他们不想成为你！"] = "В твоих глазах они ничего не стоят, всего лишь паразитируемые игрушки, но у них своя жизнь, и они не хотят становиться тобой!",
    ["他们在叫我？"] = "Они зовут меня?",
    ["他们在这里出现，难道是同伙？"] = "Они появились здесь, могли ли они быть соучастниками?",
    ["他们好像都以代号互称，风信子、蒲公英……"] = "Казалось, они обращались друг к другу по кодовым именам: Гиацинт, Одуванчик...",
    ["他们携带铜镜，路过失踪点，被知识皇冠瓦解消散，旁边的人根本无法察觉。"] = "Они несли бронзовое зеркало, прошли мимо точек исчезновения и были уничтожены Короной Знаний; люди поблизости вообще ничего не заметили.",
    ["他们是贝克兰德教区的同行，护送着封印物“2-049”过来，同时支援我们完成任务。"] = "Они коллеги из епархии Бэкланда, сопровождают сюда Запечатанный Артефакт «2-049» и одновременно помогают нам выполнить задание.",
    ["他们是邪神信徒，有代号的都是月亮仆从的头目或首领。"] = "Они являются последователями злого бога, и все те, кто носит кодовые имена, являются лидерами или главами Лунных Слуг.",
    ["他们的名字会出现在下周的死亡名单上。"] = "Их имена появятся в списке смертников на следующей неделе.",
    ["他们的胳膊，他们的腿，瘦得跟火柴一样。"] = "Их руки, их ноги... тонкие, словно спички.",
    ["他们纷纷看向你、走向你、拥抱你……"] = "Они смотрят на тебя, идут к тебе и обнимают...",
    ["他们绝大部分人的收入，连维持温饱都做不到。"] = "Доход подавляющего большинства из них не позволяет обеспечить даже элементарное питание и одежду.",
    ["他们被偷走了念头，而我却被神明植入自毁的念头——祂们让我乖乖去死。"] = "У них украли мысли, а мне бог внушил мысли о самоуничтожении — Они хотят, чтобы я послушно пошёл и умер.",
    ["他们被彻底瓦解了，已经成为邪神的祭品。"] = "Они полностью распались и стали жертвами злому богу.",
    ["他们说我被卖掉了……我和被牵走的小羊羔一样吗？"] = "Они сказали, что меня продали... Я такой же, как ягнёнок, которого уводят?",
    ["他们还在现实世界中活着，这里是你循环无尽的噩梦。"] = "Они всё еще живы в реальном мире, а здесь — твой бесконечный кошмар.",
    ["他们都和邮差串通好了，一起演戏捉弄我？"] = "Они все сговорились с почтальоном и вместе разыгрывают спектакль, чтобы поиздеваться надо мной?",
    ["他们都属于一个信仰堕落母神的邪神组织——月亮仆从。"] = "Все они принадлежат злой организации, поклоняющейся Матери-богине разврата — Лунной Слуге.",
    ["他们都陆续侧头，望向了站在“世界”座椅旁的你。"] = "Один за другим они повернули головы, посмотрев на тебя, стоявшего рядом с креслом «Мира».",
    ["他会指引你加入<P_Yellow>黑荆棘安保公司</>的。"] = "Он поможет вам присоединиться к <P_Yellow>Охранная компания «Чёрный Чертополох»</>.",
    ["他会统计工作餐的菜品和数量，然后分别在午餐和晚餐时间送餐上门。"] = "Он подсчитывает блюда и количество порций для служебных обедов, а затем развозит их к обеду и ужину.",
    ["他信仰的“伟大母亲”，是名为“堕落母神”的邪神，红月是祂的象征。"] = "«Великая Мать», которой он поклонялся, — это злой бог, называемый «Богиней-матерью разврата», а красная луна — Ее символ.",
    ["他只是拥有小孩子的身体，实际还是愚者教会的“水银天使”。"] = "У него лишь тело ребёнка, а на самом деле он по-прежнему «Ртутный ангел» церкви Шута.",
    ["他在教授<P_Yellow>魔镜占卜</>……"] = "Он обучает <P_Yellow>гаданию на зеркале</>...",
    ["他在笑我替迪伦签了合同。我签了什么？群演合同。我为什么会签合同？"] = "Он смеётся надо мной за то, что я подписал контракт вместо Дилана. Что я подписал? Контракт статиста. Почему я вообще подписал контракт?",
    ["他对我们说了很过分的话，我们吵了一架……不止伊森他们，我也很生气啊！"] = "Он сказал нам что-то очень чрезмерное, и мы поругались... Это был не только Итан и остальные, я тоже очень разозлился!",
    ["他就这么走了？！二缺一！路人倒是还在……"] = "Он вот так просто ушёл?! Не хватает одного! Хотя прохожий всё ещё здесь...",
    ["他已经变成怪物"] = "Он уже стал монстром",
    ["他已经完全失去了理智。"] = "Он полностью потерял рассудок.",
    ["他希望下雨的时候，每个人都能有地方避雨。"] = "Он надеется, что когда пойдёт дождь, у каждого будет где укрыться.",
    ["他年纪是大了，只能清洗列车头，但他还想建造飞艇，还在鼓励有梦想的年轻人！"] = "Он уже стар и может только мыть паровозы, но всё равно мечтает построить дирижабль и продолжает вдохновлять мечтающую молодёжь!",
    ["他应该是在用古老的仪式吸收笔记的力量，就像我们直接服用高序列的魔药一样，这充满危险、也需要时间，他需要呆在一个安全的地方。"] = "Он, должно быть, поглощает силу дневника с помощью древнего ритуала — так же, как мы напрямую принимаем Зелье высокой Последовательности. Это очень опасно и требует времени, поэтому ему нужно оставаться в безопасном месте.",
    ["他报复之后又会有怎样的结果？"] = "Чем обернётся его месть?",
    ["他挑起了内讧，导致船上的人相互厮杀？"] = "Он спровоцировал распри, заставив людей на корабле убивать друг друга?",
    ["他无处不在，除了邮差、小丑们、金玫瑰人员，还有大量分身在贝克兰德传播污染，进行恶作剧和欺诈。"] = "Он повсюду: помимо почтальонов, Клоунов и членов Золотой розы, множество его аватаров распространяют в Бэкланде заразу, устраивают розыгрыши и обманы.",
    ["他早就带着我们的钱跑了！"] = "Он уже сбежал с нашими деньгами!",
    ["他是个勤奋的小伙，你也毕业了。你们很快就能赚到钱，也不应该住现在这样的公寓，至少得有个自己的盥洗室。"] = "Он прилежный молодой человек, и ты тоже закончил учебу. Скоро ты будешь зарабатывать деньги, и тебе не следует жить в такой квартире; у вас должна быть хотя бы собственная ванная комната.",
    ["他是我的未婚夫，我们曾经都是猎龙帮的成员。"] = "Он мой жених, мы оба были членами банды охотников на драконов.",
    ["他是月亮仆从的成员，还在梦里举行过祭祀仪式……我是不是该继续追查下去？"] = "Он является членом Лунного Слуги и даже провел во сне жертвенный ритуал... Стоит ли мне продолжать расследование?",
    ["他是皇家陆军上士，牺牲后的抚恤金让我能有机会读书。母亲前几年也去世了……"] = "Он был сержантом Королевской армии, и пенсия после его жертвы позволила мне иметь возможность учиться. Моя мама тоже умерла несколько лет назад...",
    ["他是迪伦，我不是。我是……我是来找邮差的。他就在楼上，对着我笑。"] = "Он — Дилан, а я нет. Я... Я пришёл искать почтальона. Он наверху и улыбается мне.",
    ["他月初从南大陆回来，就一直留在廷根，等罗塞尔戏剧节开幕。"] = "Он вернулся с Южного континента в начале месяца и с тех пор оставался в Тингене, дожидаясь открытия Театрального фестиваля имени Розелля.",
    ["他有一枚特殊的金币，是两年前“愚者”先生交给他的。"] = "У него есть особая золотая монета, которую Мистер Шут подарил ему два года назад.",
    ["他来自<P_Yellow>密修会</>，一个建立于第四纪的古老组织，安提哥努斯笔记原本被他们掌控。"] = "Он происходит из Секретного Ордена <P_Yellow></>, древней организации, основанной в Четвертой Эпохе. Оригинальная тетрадь Антигона контролировалась ими.",
    ["他死前有什么异常吗？"] = "Было ли в нем что-нибудь необычное перед смертью?",
    ["他每天都会轻轻踢我，告诉我他的心情，还会哼歌、吹口哨，用音乐帮助我入睡……"] = "Он каждый день нежно пинает меня, чтобы сообщить о своем настроении, напевает песни, насвистывает и использует музыку, чтобы помочь мне заснуть...",
    ["他的尸体不见了，行李被弗兰奇扔掉了。我只捡回来几件小东西，烧成了这罐灰烬。"] = "Его тело исчезло, а багаж выбросил Фрэнки. Я смог собрать лишь несколько мелочей и сжёг их в этой банке с пеплом.",
    ["他的智商还不如卷毛狒狒，没办法分辨太复杂的事情。"] = "Его интеллект даже не так хорош, как у кудрявого павиана; он не может различать очень сложные вещи.",
    ["他破产后，似乎早就准备赴死了。"] = "Похоже, разорившись, он давно уже был готов расстаться с жизнью.",
    ["他自己是迪伦，怎么还叫你迪伦？是BUG吧？策划配置错了？"] = "Он сам Дилан, так почему он называет Диланом тебя? Это баг? Разработчики неправильно настроили?",
    ["他让人感到……恐惧……"] = "Он внушает... ужас...",
    ["他说，这样能激励他好好工作，好好攒钱。"] = "Он сказал, что это будет мотивировать его усердно работать и экономить деньги.",
    ["他还喜欢讲冒险故事，即使自己从没离开过廷根。"] = "Он ещё любит рассказывать истории о приключениях, хотя сам ни разу не покидал Тингена.",
    ["他还是你的哥哥"] = "Он все еще твой брат",
    ["他铺设过海底电缆，修建过铁轨、钢铁大桥，甚至飞艇。"] = "Он прокладывал подводные кабели, строил железные дороги, стальные мосты и даже дирижабли.",
    ["付钱"] = "Платить",
    ["代价？我什么代价都不怕！"] = "Цена? Я не боюсь никакой цены!",
    ["以前母亲虔诚地信仰着黑夜女神，莫雷蒂家每天都要向女神祈祷，因此我们学了不少颂歌。"] = "Моя мать была истовой верующей в Богиню Вечной Ночи, и семья Моретти молилась Богине каждый день, поэтому мы выучили немало гимнов.",
    ["以及，指导我们的新鲜血液。"] = "И направлять нашу свежую кровь.",
    ["以后你要是遇到类似的情况，千万不要遗漏，那或许是相当重要的物品。"] = "Если вы столкнетесь с подобными ситуациями в будущем, никогда не упускайте их из виду; они могут быть весьма важными предметами.",
    ["以后有机会的话，我们可以一起坐下来、喝杯咖啡、聊聊天。"] = "Если в будущем будет возможность, мы можем сесть вместе, выпить чашечку кофе и поболтать.",
    ["以后还有很多机会互相了解，队长应该正等着你，去吧。"] = "Позже будет много возможностей узнать друг друга. Вас должен ждать капитан, идите вперед.",
    ["仪式引来邪神注视，周围的一切都被污染了。"] = "Ритуал привлек взор злого бога, и все вокруг было испорчено.",
    ["伊丽莎白"] = "Элизабет",
    ["伊丽莎白，你说有惊喜的礼物在这个房间？"] = "Элизабет, ты сказала, что в этой комнате был подарок-сюрприз?",
    ["伊丽莎白，我先问你个问题。如果你的朋友出事了，你会想要拯救她吗？"] = "Элизабет, позвольте мне сначала задать вам вопрос. Если бы ваша подруга попала в беду, захотели бы вы ее спасти?",
    ["伊丽莎白，我有一些事情想和你交流下，可以随我出来吗？"] = "Элизабет, мне нужно кое-что с тобой обсудить, выйдешь со мной?",
    ["伊妮德"] = "Энид",
    ["伊森他们冲动起来就没有理智，刚才真的谢谢你，请问你是？"] = "Итан и остальные теряют рассудок, когда становятся импульсивными. Спасибо за этот момент, могу я спросить, кто вы?",
    ["伊森，你听我说，我们是真的想做一家属于自己的店……"] = "Итан, послушай меня, мы очень хотим открыть собственный магазин...",
    ["优雅老者：诸位，晚宴还没有开始，怎么能提前离席呢？"] = "Элегантный старик: Все, ужин еще не начался, как вы можете уйти пораньше?",
    ["会不会是知识皇冠造成的，而幕后力量是堕落母神和祂的信徒？"] = "Может ли это быть вызвано Короной Знаний, а за ней стоит Падшая Богиня-Мать и ее последователи?",
    ["会议要开始了，阿兹克，我们不能耽搁了。"] = "Встреча вот-вот начнется, Азик. Мы не можем больше откладывать.",
    ["会长，我们需要对这里进行特别调查，可以请你们离开一下吗？"] = "Господин председатель, нам необходимо провести здесь особое расследование. Не могли бы вы ненадолго выйти?",
    ["伦纳德也来了，也很合理……"] = "Леонард тоже пришел, это имеет смысл...",
    ["伦纳德先生，你怎么来了这里？"] = "Мистер Леонард, почему вы здесь?",
    ["伦纳德向我提起过，如果有您的帮助，成功的希望会更大。"] = "Леонард упомянул мне о тебе; если нам понадобится ваша помощь, надежда на успех будет намного больше.",
    ["伦纳德还得准备一会儿，先换上新衣服，去廷根逛逛，试试自己的新车吧！"] = "Леонарду нужно еще немного времени на подготовку. Переоденься пока в новый наряд, прогуляйся по Тингену и опробуй свой новенький велосипед!",
    ["伦纳德通知了警察处理后续的事情，然后返回了黑荆棘安保公司……"] = "Леонард уведомляет полицию, чтобы она разобралась с последствиями, а затем возвращается в охранную компанию Чёрный Чертополох...",
    ["伦纳德，你的情况还好，就留在这里，别让普通人接近……"] = "Леонард, ты в приличной форме, так что оставайся здесь. Не подпускайте обычных людей близко...",
    ["伦纳德，你还好吗？"] = "Леонард, ты в порядке?",
    ["伦纳德：“下午好，又见面了。还记得我吗？\n伦纳德·米切尔，序列8的午夜诗人。”"] = "Леонард: «Добрый день, мы снова встретились. Помнишь меня?\nЛеонард Митчелл, Полуночный Поэт 8-й Последовательности».",
    ["伦纳德：同样的，我也希望你用类似的态度看待我。\n伦纳德：当然，这种事情最好还是不要告诉上面的人，那些家伙都古板而保守，总认为我们这种特殊的人必然会受到邪神恶魔的引诱而堕落。\n*伦纳德伸出手*"] = "Леонард: И я надеюсь, что вы относитесь ко мне таким же образом. \n Леонард: Конечно, людям выше тебя о таких вещах лучше не рассказывать. Эти ребята старомодны и консервативны. Они всегда думают, что особенные люди, такие как мы, неизбежно будут искушены злыми богами и демонами и падут. \n*Леонард протягивает руку*",
    ["伪装成安保公司的非凡者队伍，隶属于黑夜教会，现在也是我的公司了。"] = "Отряд Потусторонних, замаскированный под охранную компанию и подчиняющийся Церкви Вечной Ночи... а теперь это еще и моя компания.",
    ["伪装无知？"] = "Притвориться невежественным?",
    ["伪装的身份？"] = "Замаскированная личность?",
    ["伪装警官"] = "Замаскированный полицейский",
    ["伴随一阵急促的铃声，邮差在撞到你之前，勉强将脚踏车在你面前刹停。"] = "Под резкий звон почтальон едва успевает затормозить велосипед перед вами, прежде чем сбить вас.",
    ["伴随吟唱，信徒纷纷倒地或振飞，红月消失，天气正常。\n伦纳德缓缓走近，结束施法"] = "Вместе с пением верующие падали на землю или взлетали один за другим, красная луна исчезла, и погода нормализовалась. \n Леонард медленно подошел и закончил накладывать заклинание.",
    ["伴随音乐、喷泉、彩带，观众的掌声和欢呼——\n一群小丑登台，芬奇一直在中间位，是演出主角。\n一段精彩的小丑表演，可有纸牌魔术杂技等内容。"] = "Под музыку, фонтаны и серпантин, под аплодисменты и крики зрителей...\nНа сцену выходит труппа клоунов, Финч всегда в центре — он главная звезда представления.\nОтличное клоунское выступление: карточные фокусы, акробатика и многое другое.",
    ["似乎有严重的危机正在廷根酝酿，这种感觉不是太好。"] = "Похоже, в Тингене назревает серьезный кризис. Это чувство не очень хорошее.",
    ["似乎理清了状况，冰淇淋帮了大忙。"] = "Кажется, ситуация прояснилась. Мороженое очень помогло.",
    ["但<P_Yellow>新生者</>也在努力抗争，这是“愚者”先生看中的<P_Yellow>人性</>，是成功的关键。"] = "Но <P_Yellow>Newborn</> также испытывает трудности. Это <P_Yellow>человечность</>, которую ценит Мистер Шут, и это ключ к успеху.",
    ["但……不要喝下去就好！"] = "Но... только не пейте!",
    ["但一开始有无形的力量密封了房间，在使用仪式魔法时，经常会有类似的操作。"] = "Но вначале невидимая сила запечатала комнату. Это обычная процедура при использовании Ритуальной Магии.",
    ["但也要小心，别让自己陷入危险。"] = "Но также будьте осторожны, не позволяйте себе попасть в опасность.",
    ["但他们很容易感知到隐藏于事物背后的某些存在，必须小心翼翼，对非凡力量充满敬畏。"] = "Но они легко воспринимают определенные существования, скрытые за вещами, и должны быть очень осторожны, оставаясь в восторге от Потусторонних сил.",
    ["但他们都沉浸其中，太真实了，不像演戏……"] = "Но все они были полностью погружены в роль, слишком реалистично, совсем не похоже на игру...",
    ["但你也将直面噩梦中污染的象征，直到彻底战胜它。"] = "Но вы также столкнетесь с символом порчи в кошмаре напрямую, пока не победите его полностью.",
    ["但你也随之从高空落了下去，落在了一段长长的光阶之前。"] = "Но ты тоже упал с неба и приземлился перед длинной легкой ступенькой.",
    ["但别担心，我们有可靠的非凡者组织，正在守护廷根。"] = "Но не волнуйтесь, у нас есть надежная организация Потусторонних, которая охраняет Тингена.",
    ["但加入黑荆棘，意味着你也要和我们一起承担职责。"] = "Но вступление в «Чёрный шип» означает, что тебе придётся разделить с нами эти обязанности.",
    ["但卡尔拖欠整整一周的房租，人现在还不知道在哪里。"] = "Но Карл задолжал за жилье за целую неделю, и где он сейчас бродит — одному богу известно.",
    ["但可以确定的是，短时间内我回不去了。"] = "Но одно можно сказать наверняка: я пока не могу вернуться.",
    ["但因为一位成员的疏忽，笔记进入古物市场、被韦尔奇得到，现在他们不得不派人到处追寻。"] = "Но из-за халатности одного из членов блокнот попал на антикварный рынок и был приобретен Уэлчем. Теперь им приходится повсюду рассылать людей, чтобы выследить его.",
    ["但如果你现在去诊所，你还有机会重新开始，而且这还能帮我们找到兰尔乌斯，拿回被诈骗的钱。"] = "Но если вы сейчас обратитесь в клинику, у вас еще есть шанс начать все сначала, и это может помочь нам найти Инса Зангвилла и вернуть украденные деньги.",
    ["但如果能顺利救出小少爷，他愿意将报酬翻倍，一次性付200镑。"] = "Но если ему удастся благополучно спасти юного господина, он готов удвоить награду и выплатить сразу 200 фунтов.",
    ["但廷根被一百多年前的时代浪潮笼罩，不太对劲。"] = "Но то, что Тинген окутан приливами эпохи столетней давности — это не к добру.",
    ["但愿不会有这么一天"] = "Я надеюсь, что этот день никогда не наступит",
    ["但愿不会有这么一天。"] = "Я надеюсь, что этот день никогда не наступит.",
    ["但成为红手套，我就不能留在黑荆棘了。"] = "Но если я стану Ночным Ястребом, я не смогу остаться в Блэкторне.",
    ["但我也要提醒你……这份守护，未来将面临更大的考验。"] = "Но я также должен напомнить вам... эта обязанность по охране в будущем столкнется с еще более серьезными испытаниями.",
    ["但我们都知道，真实的伤痛依然存在，廷根失去了一些好市民，卡尔、查林……他们的名字值得被记住。"] = "Но мы все знаем, что настоящая боль все еще существует. Тинген потерял нескольких хороших граждан; Карл, Чарльз... их имена заслуживают того, чтобы их помнили.",
    ["但我似乎丢失了一些记忆，包括27号我做过什么、看到了什么，我甚至不记得我去过韦尔奇家！"] = "Но я, кажется, потерял некоторые воспоминания, в том числе о том, что я делал или видел 27-го числа. Я даже не помню, как был в доме Уэлча!",
    ["但我和哥哥还要租房吃饭，每周能攒下的钱非常少。"] = "Но нам с братом по-прежнему приходится платить за квартиру и питаться, поэтому денег, которые мы можем откладывать каждую неделю, очень мало.",
    ["但我好像没戴单片眼镜……"] = "Но, кажется, на мне нет монокля...",
    ["但我已经解读出了其中几个符号，确认那是数字的表达，发现这其实是一本日记！"] = "Но я уже расшифровал из него несколько символов, подтвердил, что это выражения чисел, и обнаружил, что это на самом деле дневник!",
    ["但我得到了一份其他的工作，他们还预支了我四周的薪水。"] = "Но я нашёл другую работу, и мне даже выдали аванс за четыре недели вперёд.",
    ["但我感觉领口有点紧，胸口也闷得难受，还有袖口这里……"] = "Но мне кажется, что воротник тесноват, в груди душно, а вот манжеты...",
    ["但我确实什么都不记得了。"] = "Но я действительно ничего не помню.",
    ["但我要先去<P_Yellow>取消廷根大学的面试</>，毕竟是导师介绍的机会，去打个招呼，这样才礼貌。"] = "Но мне нужно сначала пойти в <P_Yellow>, отменить собеседование в Университете Тинген</>. В конце концов, это была возможность, предоставленная моим наставником, так что было бы вежливо пойти и поздороваться.",
    ["但是……随着时间流逝，周围人开始变得奇怪。"] = "Но... со временем люди вокруг нас начали вести себя странно.",
    ["但是、但是！我的女神啊，你知道那有多么危险吗？队长没告诉你吗？"] = "Но, но! Моя Богиня, ты знаешь, как это опасно? Разве капитан тебе не сказал?",
    ["但是以我的家境，哪有钱和渠道买枪。"] = "Но, учитывая мое семейное прошлое, откуда у меня будут деньги и каналы, чтобы купить оружие?",
    ["但是你晋升的话，就能加入红手套了，我们还可以一起合作。"] = "Но если ты продвинешься, ты сможешь присоединиться к «Красным перчаткам», и мы сможем работать вместе.",
    ["但是坦白讲，我尊敬每一位自愿成为值夜者的人。"] = "Но, честно говоря, я уважаю всех, кто добровольно становится Ночным Ястребом.",
    ["但是我也请大家看看，我们的工厂正在产出最坚固的钢铁，这是工业的基础，是王国的未来！"] = "Но я также хочу, чтобы все увидели, что наш завод производит самую прочную сталь, которая является основой промышленности и будущего королевства!",
    ["但是韦尔奇、娜娅、瑞尔·比伯和他的母亲，却因为笔记事件死去了，爱丽丝也失去了她的爱人……"] = "Но из-за инцидента с блокнотом погибли Уэлч, Найя, Рэй Бибер и его мать, а Алиса тоже потеряла возлюбленного...",
    ["但是，我相信没用。"] = "Однако моя вера бесполезна.",
    ["但是，首先你需要好的枪法，不然你的子弹会先打中队友，或者你自己。"] = "Однако сначала вам нужна хорошая меткость, иначе ваши пули сначала поразят ваших товарищей по команде или вас самих.",
    ["但是？"] = "Но?",
    ["但最近瑞尔不知道怎么了，突然间就对开店不感兴趣了。"] = "Но недавно, не знаю, что случилось с Риэлем, он вдруг потерял интерес к открытию магазина.",
    ["但有人告诉我，如果没有配角，戏剧就无法成立，小角色有小角色的魅力。"] = "Но мне говорили, что без второстепенных ролей пьеса не состоится, и у маленьких ролей есть своё очарование.",
    ["但有她的帮助，成功的概率会大很多。"] = "Но с ее помощью вероятность успеха будет намного выше.",
    ["但根据教会总堂的命令，我要先向你通报0级封印物失踪的情况。"] = "Но согласно приказу штаба церкви, хочу в первую очередь сообщить вам о пропавших запечатанных предметах 0 уровня.",
    ["但没有得到小队的批准，你不能以任何借口离开廷根，并需要尽量向家人保密。"] = "Но без одобрения отряда вы не сможете покинуть Тинген ни под каким предлогом, и вам нужно приложить все усилия, чтобы сохранить это в тайне от своей семьи.",
    ["但现在找上门的线索只有那个在大街上发疯失控的家伙，到底是怎么回事……"] = "Но единственная зацепка, которая сейчас пришла к моей двери, это тот парень, который сошел с ума и потерял контроль на улице. Что именно происходит...",
    ["但现在，你需要的是好好地、安稳地睡一觉。"] = "Но сейчас тебе нужно хорошо выспаться.",
