    ["你好，克莱恩。"] = "Привет, Клейн.",
    ["你好，女士。"] = "Здравствуйте, мадам.",
    ["你好，小朋友……买一份今天的报纸。"] = "Здравствуй, малыш... Я куплю сегодняшнюю газету.",
    ["你好，我们想给他买套正装，有什么推荐吗？"] = "Здравствуйте, мы хотели бы купить ему строгий костюм. Есть ли у вас какие-либо рекомендации?",
    ["你好，我叫克莱恩·莫雷蒂。"] = "Здравствуйте, меня зовут Клейн Моретти.",
    ["你好，我想要占卜一件事情。"] = "Здравствуйте, я бы хотела сделать гадание.",
    ["你好，我是克莱恩·莫雷蒂，是邓恩·史密斯先生邀请我来的。"] = "Здравствуйте, я Клейн Моретти. Мистер Данн Смит пригласил меня сюда.",
    ["你好，我要一张去贝克兰德的……"] = "Здравствуйте, я хотел бы билет до Баклунда...",
    ["你好，有什么事吗？"] = "Здравствуйте, могу ли я вам чем-нибудь помочь?",
    ["你好，请问应该去哪里参加今天大学讲师的面试？"] = "Здравствуйте. Не подскажете, где проходит сегодняшнее собеседование на должность преподавателя университета?",
    ["你如果在现场，也会跟我一样记忆深刻。我回来后画了一张速写想找到他，表达我的感激。"] = "Окажись вы там, увиденное врезалось бы вам в память так же крепко. Вернувшись, я нарисовал набросок, чтобы разыскать его и отблагодарить.",
    ["你妻子死之前有什么异常吗？"] = "Было ли что-нибудь необычное перед смертью вашей жены?",
    ["你家门口是否有一架玩具风车？"] = "Стоит ли у двери твоего дома игрушечная ветряная мельница?",
    ["你尝试占卜特莉丝逃跑的目标位置。"] = "Вы пытаетесь угадать цель побега Трисси.",
    ["你就告诉他——“<P_Yellow>风暴比烈酒更烈</>。”"] = "Просто скажите ему: «<P_Yellow>Шторм сильнее крепкого алкоголя.</>».",
    ["你就是克莱恩·莫雷蒂？刚才小罗珊过来说你很有礼貌。"] = "Вы, должно быть, Клейн Моретти? Маленькая Розанна только что сказала, что ты очень вежливый.",
    ["你就是我。"] = "Ты — это я.",
    ["你已经成为了我们的文职人员，但是否能成为正式的非凡者，还要看之后的际遇。"] = "Вы уже стали нашим секретарем, но сможете ли вы стать официальным Потусторонним, зависит от ваших будущих встреч.",
    ["你希望使用哪种占卜？"] = "Какое гадание вы предпочитаете использовать?",
    ["你希望成为一名非凡者吗？只能从不完整序列里挑选起始的非凡者。"] = "Вы хотите стать Потусторонним? Вы можете выбрать стартового Потустороннего только из неполной последовательности.",
    ["你应该称呼我为邓恩队长了。"] = "Теперь вам следует называть меня капитаном Дэном.",
    ["你应该能听出我的诚恳。<P_Heart>（我说的都是真话，当然，只是真话的一部分！）</>"] = "Вы должны услышать мою искренность. <P_Heart>(Говорю правду, конечно, только часть правды!)</>",
    ["你应该说昨天就来过。对了，忘了提前介绍了……"] = "Тебе следует сказать, что ты был здесь вчера. Кстати, я забыл ее заранее познакомить...",
    ["你很有天赋，但每次过分练习或者使用灵视后，都需要通过睡眠来恢复灵性，你可以回家休息了。"] = "Вы очень талантливы, но после каждой чрезмерной практики или использования духовного видения вам необходимо восстанавливать свою духовность посредством сна. Можешь пойти домой и отдохнуть.",
    ["你得上学了"] = "Тебе нужно идти в школу",
    ["你心中充满治愈的力量，噩梦的阴霾仿佛被暂时驱散。"] = "Ваше сердце наполняется силой исцеления, и дымка кошмара, кажется, временно рассеивается.",
    ["你必须成为真正的非凡者，掌控属于自己的能力，才能让嫁接更稳定。"] = "Вы должны стать настоящим Потусторонним и овладеть своими способностями, чтобы сделать Прививку более стабильной.",
    ["你忍痛站起，身上有着污染的红色。\n坚定地拒绝。"] = "Превозмогая боль, вы поднимаетесь на ноги, пока ваше тело окрашивается багрянцем осквернения.\nВы решительно отказываетесь.",
    ["你怎么会在这里！"] = "Как ты здесь!",
    ["你怎么又在假扮我！给人占卜是我的工作！"] = "Почему ты снова притворяешься мной! Гадать - моя работа!",
    ["你怎么突然开始发呆了？"] = "Что это ты вдруг застыл?",
    ["你想摸摸兔子粉白的耳朵。\n兔子掏出手枪指着你：我讨厌没有礼貌的家伙！\n四周顿时乱作一团。\n“砰！”"] = "Вам захотелось потрогать бело-розовые ушки кролика.\nКролик выхватывает револьвер и наставляет на вас: «Терпеть не могу невеж!»\nВокруг мгновенно воцаряется хаос.\n«Бабах!»",
    ["你想看哪张牌？"] = "Какую карту вы хотите посмотреть?",
    ["你想说，和平时的我完全不一样对吧？"] = "Вы хотите сказать, что я совершенно не похож на себя обычного, да?",
    ["你成为非凡者是基于应对危险和寻找笔记的需要。之后你需要跟随老尼尔额外学习神秘学知识，这个你们自己安排时间，有问题吗？"] = "Ваше становление Потусторонним основано на необходимости справиться с опасностью и найти блокнот. После этого вам нужно следовать за Стариной Нилом, чтобы получить дополнительные оккультные знания. Время для этого вы можете согласовать сами. Есть вопросы?",
    ["你执意选择拥抱“伟大母亲”，心理治疗失败，被污染完全侵蚀。"] = "Вы настаивали на том, чтобы обнять «Великую Мать»; Психотерапия не удалась, и вас полностью разъела Искажение.",
    ["你扭头一看，一只章鱼正在灶台前忙碌。"] = "Вы поворачиваете голову и видите осьминога, возящегося перед плитой.",
    ["你找到了目标所在的位置？"] = "Вы нашли местоположение цели?",
    ["你把手交给了这位女士。片刻后，一股温暖的力量流遍了你的身体。"] = "Вы протягиваете руку этой даме. Мгновение спустя теплая сила разливается по всему вашему телу.",
    ["你拼命敲砸，终于打破了这团绯红的光茧。"] = "Ты отчаянно стучишься и стучишься, наконец, прорываясь сквозь этот малиновый кокон света.",
    ["你拿着这个去找老尼尔，他就明白了。"] = "Отнесите это Старине Нилу, и он поймет.",
    ["你挣扎着清醒过来，发现自己已身处一个奇异的空间内，\n而不远处有个熟悉的人影——“愚者”先生"] = "Изо всех сил вы пытаетесь прийти в себя и обнаруживаете, что находитесь в диковинном пространстве,\nа неподалеку виднеется знакомый силуэт — господин Шут.",
    ["你是……我们的新人？"] = "Ты... наш новичок?",
    ["你是占卜师，你来决定。"] = "Вы прорицатель, вам решать.",
    ["你是否活着都不会再影响到后续的发展，造成的这一切的神秘力量不会再特别重视你了。"] = "Живы вы или нет, уже не повлияет на дальнейшее развитие событий. Таинственная сила, вызвавшая все это, больше не будет обращать на вас особого внимания.",
    ["你是怎么做到的？房租还剩六个月。提前搬家等于违约，要是被告上法庭，我们得赔一大笔钱。"] = "Как вы это сделали? До аренды осталось полгода. Досрочный выезд является нарушением договора. Если бы нас подали в суд, нам пришлось бы заплатить огромную сумму.",
    ["你是执掌好运的黄黑之王"] = "Ты король желтого и черного, приносящий удачу.",
    ["你是来参加面试的？"] = "Вы здесь на собеседовании?",
    ["你是灰雾之上的神秘主宰"] = "Ты таинственный правитель над серым туманом",
    ["你是神明交易的核心，是有可能改变命运的人，我可以花点时间跟你玩玩。"] = "Ты — центр сделки с богом, человек, способный изменить судьбу. Я могу потратить немного времени и поиграть с тобой.",
    ["你是第一次吗？有些紧张？不用担心。"] = "Это твой первый раз? Немного нервничаешь? Не волнуйся.",
    ["你是被“愚者”先生选中的人，一定没问题的！"] = "Ты тот человек, которого выбрал мистер «Шут», с тобой обязательно все будет хорошо!",
    ["你是警察？官方和教会不是不管这里吗？"] = "Ты офицер полиции? Разве чиновники и Церковь не остаются в стороне от этого места?",
    ["你是说这个少年……在船上的厮杀中救了你们？"] = "Ты имеешь в виду, что этот мальчик... спас вас всех во время резни на корабле?",
    ["你是说，他们的死亡被超凡因素人为地提前了？这又是为什么呢？"] = "Ты хочешь сказать, что их смерть была искусственно приближена необыкновенными факторами? И зачем это?",
    ["你是说，他最近都没有出海贸易，所以没有接触过违禁物品？"] = "Вы хотите сказать, что он в последнее время не занимался заграничной торговлей, поэтому с контрабандой не имел дела?",
    ["你是说，有非凡力量在故意制造死亡？"] = "Вы хотите сказать, что существует Чрезвычайная сила, намеренно вызывающая эти смерти?",
    ["你是鲁恩人吧？你可以加入黑夜女神教会、风暴之主教会或蒸汽与机械之神教会，获得成为非凡者的机会。"] = "Вы ленезе, верно? Вы можете присоединиться к Церкви Богини Вечной Ночи, Церкви Повелителя Штормов или Церкви Бога пара и машин, чтобы получить возможность стать Потусторонним.",
    ["你最近一直在用占卜解决事情，但这不意味着你可以依赖占卜，占卜不是万能的。"] = "В последнее время вы используете гадание для решения проблем, но это не значит, что вы можете на него положиться. Гадание не всесильно.",
    ["你有一次选择的机会。"] = "У вас есть один шанс сделать выбор.",
    ["你有种特别的气质。"] = "У вас особый темперамент.",
    ["你来得很准时。"] = "Вы очень пунктуальны.",
    ["你来得比我预想的要快。"] = "Вы прибыли быстрее, чем я ожидал.",
    ["你来洗牌、切牌，要占卜什么？"] = "Перетасуй и сними карты. О чём ты хочешь погадать?",
    ["你没事吧？"] = "Ты в порядке?",
    ["你白天在煤厂推车，天黑去剧院后台搬道具，半夜收工回家对着镜子练演技……有用吗？"] = "Днём ты толкаешь тележки на угольном заводе, с наступлением темноты таскаешь реквизит за кулисами театра, а посреди ночи возвращаешься домой и репетируешь игру перед зеркалом... Есть ли в этом толк?",
    ["你的头突然很痛。\n与此同时，一阵红雾从你身上逸散而出。"] = "Голову пронзила резкая боль.\nВ тот же миг от вашего тела поднялся клуб красного тумана.",
    ["你的想法和戴莉很像啊，她一直说要做个真正的通灵者。"] = "Ваше мышление очень похоже на мышление Дейли; она всегда говорит, что хочет быть настоящим духовным медиумом.",
    ["你的意思是，超凡因素存在于劳维斯太太被拍的那一下，来源于那位有着纤细之手的小姐或者女士。"] = "Вы имеете в виду, что сверхъестественный фактор присутствовал в поглаживании, которое получила миссис Лаувис от той леди или мисс с тонкими руками.",
    ["你的灵性也许在提醒你，这个人有异常，只是你下意识不去怀疑他，所以看不见他的样子。尝试看清这双手的主人。"] = "Возможно, ваша духовность напоминает вам, что этот человек ненормален, но вы подсознательно избегаете его подозрений, из-за чего не можете увидеть его внешний вид. Постарайтесь ясно увидеть владельца этих рук.",
    ["你的眼前突然闪过许多画面，\n绯红的月亮、沾血的笔记……"] = "Перед вашими глазами внезапно мелькает множество образов: \n малиновая луна, окровавленные ноты...",
    ["你的礼物盒里是什么？"] = "Что в твоей подарочной коробке?",
    ["你的脑海中闪过许多画面，被滞涩的人群、脸上涂着油彩的古怪小丑、疯狂的灰白怪物……这些是“他”的历史碎片。"] = "В голове проносится множество образов: застоявшаяся толпа, странный клоун с грилем на лице, обезумевший серо-белый монстр... Это фрагменты «его» истории.",
    ["你的薪水将立刻翻倍，达到每周6镑的程度，而且之后每年都会有一定程度的增长。"] = "Ваша зарплата немедленно увеличится вдвое и составит 6 фунтов в неделю, а затем будет увеличиваться в определенной степени каждый год.",
    ["你的选择称得上出色，不过，“占卜家”的后续竟然是“小丑”，真是奇怪……感觉两者完全没关系。"] = "Ваш выбор превосходен, хотя странно, что продолжение Провидца - Клоун... такое ощущение, что они не имеют ничего общего друг с другом.",
    ["你看出来什么没有……"] = "Вы видели что-нибудь...",
    ["你看，知识！"] = "Смотри, знание!",
    ["你真是一个幸运的小伙，才加入我们多久，就能遇上价值200镑的委托。"] = "Ну ты и везунчик! Без году неделя с нами, а уже отхватил поручение на целых двести фунтов.",
    ["你真是个热心的好人，不过已经很麻烦你了，我想我们可以解决的。"] = "Вы действительно добрый и отзывчивый человек, но проблем у вас уже достаточно, думаю, мы справимся.",
    ["你知道十六年前轰动了整个廷根市的那个连环杀手吗？"] = "Знаете ли вы о серийном убийце, потрясшем весь город Тинген шестнадцать лет назад?",
    ["你知道的，这种生日宴会上会有不少出色的小姐和女士参加。"] = "Знаете, на таком дне рождения будет много выдающихся девушек и женщин.",
    ["你知道赛琳娜的<P_Yellow>神秘物品</>放在哪个房间吗？"] = "Знаете ли вы, в какой комнате находится мистический предмет <P_Yellow> Селены </>?",
    ["你离开咖啡厅。\n展示廷根接头热闹景象。"] = "Вы выходите из кафе. \n показывает оживленную сцену Тинген-Джойнта.",
    ["你窥见了镜中的身影，黑发褐瞳、神情惊恐。\n等等，这不是你！"] = "Вы ловите взглядом отражение в зеркале: темные волосы, карие глаза, застывший в чертах ужас...\nПостойте, но ведь это не вы!",
    ["你经历了一场无法停歇的战斗。"] = "Вы пережили битву, которую невозможно остановить.",
    ["你背后有双眼睛！"] = "За тобой глаза!",
    ["你自己？！"] = "Ты сам?!",
    ["你被神明玩弄，就去玩弄更弱小的普通人……"] = "Бог играет с тобой, а ты идёшь играть с теми, кто слабее, — с обычными людьми...",
    ["你被非凡力量影响了，失去了理智。"] = "На вас повлияли силы Потустороннего, и вы потеряли рассудок.",
    ["你要迟到了"] = "Ты опоздаешь",
    ["你认识<P_Yellow>韦尔奇</>吧？霍伊大学的毕业生，来自间海郡的康斯顿。"] = "Вы знаете <P_Yellow>Уэлч</>, верно? Выпускник Университета Хой в Конистоне в Мидсишире.",
    ["你让我忘了海报上的签名，现在又把迪伦变成你的分身？！该死！"] = "Ты заставил меня забыть подпись на плакате, а теперь превратил Дилана в своего двойника?! Проклятье!",
    ["你说罗珊？"] = "Ты имеешь в виду Розанну?",
    ["你说过你会留下，（递出）这是具体的工作内容。"] = "Ты сказал, что останешься. (Передает) Вот конкретные детали работы.",
    ["你赶紧跳过，我喊一下鸟贼、水贼、海贼、岛贼，等你。"] = "Поскорее пропусти это, а я позову Птичьих воров, Водяных воров, Морских воров и Островных воров, пусть ждут тебя.",
    ["你跪下来，缓缓抬头看向母神，木然地流下眼泪"] = "Вы опускаетесь на колени, медленно смотрите на Богиню-Мать и безучастно плачете.",
    ["你身上有被封印的邪神污染，廷根最近也危机重重。"] = "На вас запечатана порча злого бога, и в Тингене в последнее время тоже случаются кризисы.",
    ["你身上本就有祂的污染，很容易被卷入相关事件。"] = "На вас уже есть Его порочность, поэтому легко вмешаться в связанные с этим события.",
    ["你还卖这些东西？小绅士，我可以先看看吗？"] = "Ты и такое продаешь? Юный джентльмен, могу я сначала взглянуть?",
    ["你还好吗？"] = "Ты в порядке?",
    ["你还有什么想问的吗？"] = "У вас есть еще что-нибудь, что вы хотите спросить?",
    ["你还记得什么？"] = "Что еще ты помнишь?",
    ["你这么确定？但我们的调查样本暂时还只有两个。"] = "Ты так уверен? Но в нашей выборке пока всего два человека.",
    ["你闻到了吗？好像有一股味道。"] = "Ты чувствуешь этот запах? Кажется, есть запах.",
    ["你需要休息，以及一杯咖啡……到了。"] = "Тебе нужен отдых и чашка кофе... Мы пришли.",
    ["你需要借钱吗？"] = "Вам нужно занять деньги?",
    ["你需要半成品的银片吗？"] = "Вам нужны серебряные заготовки?",
    ["你需要天然矿石吗？"] = "Вам нужны природные минералы?",
    ["你需要草药粉末吗？"] = "Вам нужен травяной порошок?",
