    ["关于晋升"] = "О продвижении",
    ["关于皮特……"] = "О Пите...",
    ["关于这点你应该能理解，你母亲是女神虔诚的信徒，你和你哥哥也读过教会的周日学校。"] = "Вы должны быть в состоянии понять этот момент; твоя мать была истовой верующей в Богиню, и ты и твой брат также посещали церковную воскресную школу.",
    ["关于那些失踪了的人……"] = "О пропавших людях...",
    ["关于非凡能力"] = "О Потусторонних способностях",
    ["关心伊妮德"] = "Позаботиться об Энид",
    ["其他"] = "Другой",
    ["其他人有没有什么异常？什么时候出门，什么时候回来？"] = "Есть ли что-нибудь необычное в остальных? Когда они уходят и когда возвращаются?",
    ["其他的谜题，应该也和他的经历有关——"] = "Другие загадки также должны быть связаны с его опытом:",
    ["其实我也一样，只是我比较幸运罢了……"] = "Собственно, я такой же, просто мне повезло больше...",
    ["其实每年处理失控的事件中，有很大部分是我们的队友……"] = "Фактически, большая часть случаев потери контроля, с которыми мы сталкиваемся каждый год, связана с нашими собственными товарищами по команде...",
    ["具体回办公室讨论吧，{{PlayerName}}也一起。"] = "Давайте обсудим детали в офисе, {{PlayerName}} тоже может прийти.",
    ["具体的情况，我也不是太清楚。"] = "Я тоже не очень хорошо знаю конкретные детали.",
    ["内部组织……会是哪个隐秘组织？"] = "Внутренняя организация... какая это могла быть секретная организация?",
    ["再占卜一下周围有没有危险。"] = "Снова гадание, чтобы увидеть, нет ли поблизости какой-либо опасности.",
    ["再好好想想，我到底是怎么穿越的。"] = "Надо хорошенько вспомнить, как именно я сюда переместился.",
    ["再悄悄告诉你一件事，虽然我是这里的店主，但是这家店的实际出资人是奥黛丽小姐哦。"] = "И скажу тебе еще по секрету: хоть я здесь и владелица, настоящая вкладчица этой лавки — мисс Одри.",
    ["再想想？"] = "Подумайте об этом еще раз?",
    ["再抽一张"] = "Нарисуй еще один",
    ["再次感谢您的帮助。可他们怎么都消失了？"] = "Еще раз спасибо за вашу помощь. Но почему они все исчезли?",
    ["再次抬头时，小女孩不见了，只留下一个小羊玩偶。"] = "Когда он снова поднял глаза, маленькая девочка исчезла, осталась только кукла-ягненок.",
    ["再次抬头时，小女孩已经不见了"] = "Когда вы снова посмотрите вверх, маленькой девочки уже нет.",
    ["再次睁眼时，你发现自己被包裹在一团封闭的绯红之中。"] = "Когда вы снова открываете глаза, вы обнаруживаете, что окутаны массой заключенного в них малинового цвета.",
    ["再看看"] = "Взгляните еще раз",
    ["再见，杰克，祝你一切顺利。"] = "До свидания, Джек, желаю тебе всего наилучшего.",
    ["再问问其他导师"] = "Спросите других репетиторов",
    ["冰淇淋在预警……提醒我，我是谁。"] = "Мороженое предупреждает... напоминает мне, кто я.",
    ["决定了，我的称号是——“正义”！"] = "Решено, мое звание – «Справедливость»!",
    ["冷静……邮差想把我困在这里，这是他恶作剧的一环？"] = "Спокойно... Почтальон хочет запереть меня здесь. Это часть его розыгрыша?",
    ["冷静点，迪伦，我们都忘记了很重要的事！"] = "Успокойся, Дилан, мы оба забыли кое-что очень важное!",
    ["冷静，克莱恩。梅丽莎还在里面，不能贸然行动。先敲门了解下房间内的情况。"] = "Успокойся, Клейн. Мелисса все еще внутри, я не могу действовать опрометчиво. Позвольте мне сначала постучать в дверь, чтобы понять ситуацию внутри.",
    ["准备什么？"] = "Готов к чему?",
    ["准备仪式"] = "Подготовительный ритуал",
    ["准备好了"] = "Готовый",
    ["准备好了的话，就拿出那块晶石吧，它记录着主人的部分力量。"] = "Если вы готовы, достаньте этот хрустальный камень; он записывает часть силы хозяина.",
    ["准备好后，就拿出那块晶石吧，它记录着主人的部分力量。"] = "Когда будете готовы, достаньте хрустальный камень; он записывает часть силы хозяина.",
    ["准备？那你先来杯因蒂斯的奥尔米尔葡萄酒，再抽上一根迪西雪茄。"] = "Подготовка? Тогда сначала выпейте бокал вина Интис's Olmier и выкурите сигару Dicy.",
    ["几个月……那时候他应该把钱已经花光了。不行，梅高欧丝，我想你必须做出决定了。"] = "Несколько месяцев... К тому времени он потратит все деньги. Нет, Мегос, я думаю, ты должен принять решение.",
    ["几天后"] = "Несколько дней спустя.",
    ["几根头发，我也不确定算不算“不好的事物”。"] = "Несколько прядей волос, я не уверен, можно ли это считать «чем-то плохим».",
    ["凶手是非凡者？"] = "Убийца был Потусторонним?",
    ["凶手的掩饰？"] = "Сокрытие убийцы?",
    ["出什么事了吗？"] = "Что случилось?",
    ["出发，一切小心。"] = "Давайте выдвигаться. Будь осторожен.",
    ["出现了！队长说过的，似乎见过什么、做过什么的感觉。这应该就是我们想要的，关于笔记的线索！"] = "Оно появилось! Это чувство, о котором упоминал капитан, — ощущения, что он что-то видел или делал раньше. Должно быть, это и есть та подсказка, которую мы искали относительно блокнота!",
    ["出示警徽"] = "Покажите значок полиции",
    ["出示铜镜"] = "Показать медное зеркало",
    ["刚刚的占卜中看到了三个人……除了那个兜帽女子，其它两个人的形象感觉很熟悉，似乎在哪里见过。"] = "Я только что видел троих людей во время гадания... Помимо женщины в капюшоне, две другие фигуры показались мне знакомыми, как будто я видел их где-то раньше.",
    ["刚好，你也可以趁这段时间休息一下。"] = "Кстати, вы также можете потратить это время на отдых.",
    ["刚好，应该是伦纳德找你，快去地下室看看吧！"] = "Так получилось, что Леонард должен искать вас. Сходите в подвал и посмотрите!",
    ["刚才……"] = "Прямо сейчас...",
    ["刚才他们对你的态度可算不上美好。"] = "Их отношение к вам сейчас едва ли можно назвать чудесным.",
    ["刚才我的同伴，替换了那张危险的红月牌，去拿来吧。"] = "Мой компаньон только что заменил опасную карту Красной Луны. Иди и возьми это.",
    ["刚才我的胸口出现了清晰的命运支流，找到真正的迪伦，才能换回我的命运！"] = "У меня в груди только что появился чёткий приток судьбы. Только найдя настоящего Дилана, я смогу вернуть свою судьбу!",
    ["刚才的都是梦境？值夜者？非凡事件？"] = "Все, что сейчас было сном? Ночные ястребы? Потусторонние инциденты?",
    ["刚才街道上突然起了大雾，附近的人全都不见了。"] = "Только что улицу вдруг заволокло густым туманом, и все люди вокруг исчезли.",
    ["刚才那是什么，差点要了我的命……"] = "Что это было только что? Это меня чуть не убило...",
    ["刚才风好大，船晃了半天，我把行李箱拿过来整理，顺便背背主角的台词……"] = "Ветер был такой сильный, что корабль долго качало. Я принёс чемодан, чтобы разобрать вещи и заодно повторить реплики главного героя...",
    ["别乱想，爱丽丝，有消息我会尽快通知你。"] = "Не зацикливайся на этом, Элис. Я сообщу вам, как только будут новости.",
    ["别听那些无谓的嘲笑，一步步向前，总有一天，命运会眷顾你。"] = "Не слушай эти пустые насмешки, иди вперёд шаг за шагом, и однажды судьба будет к тебе благосклонна.",
    ["别忘了我，记得给我留个位置。"] = "Не забывай меня; не забудь оставить для меня место.",
    ["别忘记“我”，记住你是谁。"] = "Не забывай «меня», помни, кто ты.",
    ["别怕，这是{{PlayerName}}……"] = "Не бойтесь, это {{PlayerName}}...",
    ["别急，{{他|她}}刚喝完序列9魔药，还需要适应。"] = "Не спешите, {{ he | she }} только что закончил пить зелье Последовательности 9, и ему еще нужно адаптироваться.",
    ["别担心，两周后我就回来了，带着八个金镑！"] = "Не волнуйтесь, я вернусь через две недели с восемью фунтами золота!",
    ["别担心，我只是了解一些卡尔失踪案的信息。"] = "Не волнуйтесь, я только что узнаю некоторую информацию по делу об исчезновении Карла.",
    ["别担心，我有办法带大家出去。"] = "Не волнуйтесь, у меня есть способ вытащить всех.",
    ["别担心，我还是我，这只是浅层寄生。祂是一位善意的天使，也信仰“愚者”先生。"] = "Не волнуйся, я всё ещё я, это лишь неглубокое паразитирование. Он добрый Ангел и тоже верует в господина «Шута».",
    ["别担心，这件事，你先记在备忘录上，等解决了阿蒙分身再仔细研究。"] = "Не волнуйся, пока запиши это в блокнот, а когда разберёмся с аватаром Амона, изучим подробнее.",
    ["别担心，门后有值夜者和教会人员值守。走吧，跟我去<P_Yellow>炼金室</>。"] = "Не волнуйтесь, за дверью охраняют Ночные Ястребы и служители церкви. Пойдем, следуй за мной в <P_Yellow>Alchemy Room</>.",
    ["别挤，慢慢来，人越多越好，没有名额限制。"] = "Не толпитесь, не торопитесь. Чем больше людей, тем лучше, количество мест не ограничено.",
    ["别这么叫我……怪怪的。"] = "Не называй меня так... Это звучит странно.",
    ["别，先生！我不是你爸爸，我不认识你啊！"] = "Нет, сэр! Я не ваш отец, я вас не знаю!",
    ["到了，就是这里。"] = "Мы здесь, это место.",
    ["到了，黑荆棘安保公司。"] = "Мы здесь, охранная компания Чёрный Чертополох.",
    ["到处看看"] = "Посмотрите вокруг",
    ["到时候我将向主奉献廷根市的全部羔羊。"] = "К тому времени я принесу в жертву Господу всех ягнят города Тинген.",
    ["刻意隐瞒"] = "Намеренно скрывать",
    ["前几年的积累，加上这次的功勋，足够你兑换几个序列的魔药配方和材料了……"] = "Накоплений за последние несколько лет, а также ваших заслуг на этот раз достаточно, чтобы обменять на несколько формул и материалов для зелий последовательности...",
    ["前往济贫院"] = "Иди в богадельню",
    ["前段时间，韦尔奇得到了一本第四纪的笔记，找我一起解读。"] = "Некоторое время назад Уэлч раздобыл дневник Четвертой Эпохи и позвал меня помочь с расшифровкой.",
    ["前进一步"] = "Шаг вперед",
    ["剧情策划在船上写了一堆没用的路人角色……他怎么来金玫瑰了？"] = "Сценарист написал на корабле кучу ненужных прохожих... Как он оказался в «Золотой розе»?",
    ["剩下的调查就交给我们。你在黑荆棘大厅休息下，调查有结果之后，我会通知你。"] = "Оставшуюся часть расследования оставьте нам. Вы отдыхаете в Чёрный Чертополох-холле, и я сообщу вам, как только будут результаты расследования.",
    ["力量必有代价，我们在追求力量的同时，也在累积疯狂、累积失控……"] = "Власть должна иметь цену. В то время как мы гонимся за властью, мы также накапливаем безумие и накапливаем потерю контроля...",
    ["劝说皮特"] = "Уговорить Пита",
    ["劝阻伊妮德"] = "Отговорить Энид",
    ["加入你们？"] = "Присоединиться к вам?",
    ["加入俱乐部"] = "Вступить в клуб",
    ["加入廷根市值夜者小队，成为非凡者？我可以吗？"] = "Вступить в отряд Ночных Ястребов Тингена и стать Потусторонним? У меня получится?",
    ["加入有什么条件吗？"] = "Есть ли какие-либо требования для вступления?",
    ["加入黑荆棘后，我先成为了非凡者，又去调查失踪案，后来还进了镜中廷根……"] = "Присоединившись к Ночным Ястребам, я сначала стал Потусторонним, затем отправился расследовать дела о пропавших без вести, а позже даже вошел в Тинген в Зеркале...",
    ["动画"] = "Анимация",
    ["努力思考"] = "Усердно размышлять",
    ["千钧一发之际，伦纳德出现，暂停了时间，解除了镜雨。\n伦纳德：可以了老头，多谢。"] = "В критический момент появляется Леонард: он останавливает время и рассеивает зеркальный дождь.\nЛеонард: Всё, старик, спасибо.",
    ["半小时后……"] = "Полчаса спустя...",
    ["半年前……"] = "Полгода назад...",
    ["协助？"] = "Помочь?",
    ["单片眼镜？！"] = "Монокль?!",
    ["单片眼镜？！你、你寄生了迪伦？！"] = "Монокль?! Ты... ты паразитировал на Дилане?!",
    ["卖掉。卖家我已经找好了，韦尔奇。"] = "Продайте это. Я уже нашел покупателя, Уэлч.",
    ["占位占位"] = "Заполнитель заполнитель",
    ["占卜不是万能的……"] = "Гадание не всесильно...",
    ["占卜俱乐部混入邪教徒和邪恶组织的成员，你作为值夜者小队标准的非凡者，加入他们，方便进行监控。这完全是工作需要。"] = "В Клубе Гадания смешаны культисты и члены злых организаций. Как стандартному отряду Потустороннего из «Ночных ястребов», присоединение к ним облегчает наблюдение за ними. Это исключительно для рабочих целей.",
    ["占卜俱乐部的海纳斯·凡森特？！他还在私下教授黑占卜……对了，你有听赛琳娜颂念过咒文吗？"] = "Хейнс Винсент из Клуба гадания?! Он до сих пор преподает чёрное гадание наедине... Кстати, вы слышали, как Селена произносила какие-нибудь заклинания?",
    ["占卜其他获取途径"] = "Угадайте другие способы его получения",
    ["占卜家"] = "Провидец",
    ["占卜家途径导师"] = "Наставник Пути Провидца",
    ["占据他身体的“我”，被窃取了追踪邮差的念头？！"] = "Из «меня», занявшего его тело, украли мысль выследить почтальона?!",
    ["卡尔是个很厉害的工人，他年轻时建造过很多艘游轮，却一辈子都没有坐上游轮。"] = "Карл был отличным рабочим: в молодости он построил множество круизных лайнеров, но так ни разу в жизни и не поплыл на лайнере.",
    ["卡尔的愿望实现了，愿他安息。我也该去实现自己的梦想了。"] = "Желание Карла исполнилось, пусть он покоится с миром. Мне тоже пора исполнять свою мечту.",
    ["卡尔肯定是遇到什么事了，我保证，他回来后会补齐的。"] = "Карл, должно быть, с чем-то столкнулся, я гарантирую, что он отплатит, когда вернется.",
    ["卡尔这家伙……真是的……淋个雨还不高兴了……"] = "Этот Карл... ну надо же... даже под дождём ему не угодишь...",
    ["卡尔？！你那位去世的……室友？"] = "Карл?! Твой... покойный сосед по комнате?",
    ["即便我已经为尊贵的先生和女士们服务二十多年了。"] = "Хотя я служу уважаемым господам и дамам уже более двадцати лет.",
    ["历史孔隙"] = "Историческая пустота",
    ["历史投影？"] = "Историческая проекция?",
    ["压下去？说得真体面。我室友卡尔就在失踪名单上，那群废物连他的尸体都没找到。"] = "Замять? Как красиво сказано. Мой сосед Карл в списке пропавших, а эти бездари даже тела его не нашли.",
    ["原来女孩的哥哥也是月亮仆从的成员，他的代号是“蒲公英”先生。"] = "Значит, брат девушки тоже является членом Лунного Слуги, и его кодовое имя — Мистер Одуванчик.",
    ["原来您要去贝克兰德旅行，那的确应该坐这艘船去，毕竟它的名字是“万都之都”号。"] = "А, так вы едете в Бэкланд. В таком случае вам действительно стоит сесть на этот корабль; в конце концов, его имя — «Город городов».",
    ["原来是这样……赞美女神，或许是女神注视着祂虔诚的信徒，在迷雾中引导了你。"] = "Вот так вот... Слава Богине. Возможно, Богиня наблюдала за своим благочестивым верующим и вела вас в тумане.",
    ["去吧。调整好状态，很快就要面对最后的战斗了。"] = "Вперед, продолжать. Отрегулируйте свое состояние; скоро вам придется столкнуться с финальной битвой.",
    ["去吧，新家和退租的事都处理好了。今天我和梅丽莎会把东西全都搬到新家去。"] = "Давай, новый дом и прекращение аренды уже решены. Мы с Мелиссой сегодня перенесем все на новое место.",
    ["去工厂区卖报，工人也需要了解新闻，跟上时代。"] = "Отправляйтесь в фабричный район продавать газеты; работникам также необходимо понимать новости и идти в ногу со временем.",
    ["去帮我拿起那本安提哥努斯家族的笔记。"] = "Помоги мне поднять этот дневник семьи Антигон.",
    ["去案发现场，韦尔奇先生的住所。“专家”在那里等着我们。"] = "Отправляйтесь на место преступления, в резиденцию мистера Уэлча. Там нас ждет «эксперт».",
    ["去香槟街。<P_Heart>（香槟街距离黑夜女神教堂很近，但又属于公共场合，我去那里是合理的。）</>"] = "Идите на улицу Шампани. <P_Heart>(Улица Шампани находится очень близко к церкви Богини Вечной Ночи, но это также общественное место, поэтому мне имеет смысл пойти туда.)</>",
    ["去黑荆棘吗？"] = "В «Тёрн»?",
    ["又不是我过生日，我认为钱还是最好存起来，或者先给班森准备一套。"] = "Это не мой день рождения. Думаю, лучше накопить денег, или сначала подготовить набор для Бенсона.",
    ["又做了个长长的梦，但不再是噩梦了。\n梦里好像见到了一位多年未见的朋友，\n你们一起聊了很久……"] = "Вам снова приснился долгий сон, но на сей раз это уже не был кошмар.\nКазалось, во сне вы встретили старого друга, которого не видели много лет,\nи проговорили с ним до самого утра...",
    ["又是0级……非常危险，不可打听，不可外传，不可描述，不可窥探。"] = "Опять 0 класс... Чрезвычайно опасно, нельзя спрашивать, нельзя распространять, нельзя описывать, нельзя совать нос.",
    ["又是新生……<P_Heart>（压低声音）</>罗珊，你们先进安全屋，我拖住他。"] = "Опять перерождение... <P_Heart>（Понизив голос）</>Розанна, бегите в убежище, я задержу его.",
    ["又是这样……先生，女士，下一个身份会是谁？"] = "Опять так же… Господин, госпожа, кем будет следующая личность?",
    ["发掘"] = "Раскопать",
    ["发现了什么？"] = "Что вы нашли?",
    ["发生了什么！"] = "Что случилось!",
    ["取出"] = "Извлечь",
    ["口水"] = "Слюна",
    ["古怪仪式"] = "Странный ритуал",
    ["古镜中突然爆发出红色光芒，将她吞没。"] = "Красный свет внезапно вырвался из древнего зеркала, поглотив ее.",
    ["另外，你还需要每天出去走一走，尤其是韦尔奇家到你家的各种道路。"] = "Кроме того, вам также необходимо каждый день выходить на прогулку, особенно по различным дорогам от дома Уэлча до вашего дома.",
    ["另外，加入俱乐部后就可以为顾客提供有偿占卜服务，我们只抽取很低比例的费用。最重要的是，您还能找到一群相同爱好的朋友。"] = "Кроме того, вступив в клуб, вы сможете оказывать клиентам платные услуги гадания, а мы берем лишь скромную долю комиссии. И главное — вы найдете круг единомышленников со схожими интересами.",
    ["另外，我会让警察局留意兜帽女子的线索。"] = "Кроме того, я буду держать полицию в поиске улик о женщине в капюшоне.",
    ["只是……这些东西要一会儿才能干了。"] = "Вот только… это будет сохнуть какое-то время.",
    ["只是不知道为什么，我的脑袋还完好，我活到了现在。"] = "Я просто не знаю, почему моя голова до сих пор цела, а я еще жив.",
    ["只是例行的调查。一位马车夫证实，昨天你去过韦尔奇先生的住所，还是他帮你付的车钱。"] = "Это просто обычное расследование. Водитель кареты подтвердил, что вы вчера были у мистера Уэлча, и он даже оплатил ваш проезд.",
    ["只是因为一些意外与巧合，我需要尽快获得自保的能力。"] = "Это просто из-за каких-то случайностей и совпадений; Мне нужно было как можно скорее обрести способность защитить себя.",
    ["只是运气好罢了，需要我喂你喝药吗？"] = "Мне просто повезло. Тебе нужно, чтобы я накормил тебя зельем?",
    ["只是这布料实在太厚，感觉好热，快喘不上气了……"] = "Просто эта ткань слишком толстая, в ней так жарко, что я едва могу дышать...",
    ["只是鞋底的一点污泥，它的颜色和咖啡粉的颜色差不多、差不多。"] = "Просто немного грязи с подошвы моего ботинка. Его цвет примерно такой же, как у кофейного порошка, примерно такой же.",
    ["只要一苏勒，您就能无限次体验，想坐就坐。"] = "Всего за один су вы можете испытать это неограниченное количество раз. Садитесь, когда захотите.",
    ["只要按照配方上的顺序，将材料按分量依次加入，再搅拌一下就可以了。"] = "Просто следуйте порядку рецепта, добавляйте ингредиенты по одному в соответствии с размерами, а затем немного перемешайте.",
    ["叫他老头。"] = "Назвать его стариком.",
    ["叫我安娜就好，你能推荐一位吗？"] = "Зови меня просто Анна. Можете ли вы порекомендовать один?",
    ["可以……帮我喝药吗？我起不来……"] = "Не могли бы вы... помочь мне выпить зелье? Я не могу встать...",
    ["可以。"] = "Очень хорошо.",
    ["可以。接下来两天，你尽量不要跟其它人待在同一个房间。"] = "Очень хорошо. В течение следующих двух дней постарайтесь не оставаться в одной комнате с другими.",
    ["可凭什么……凭什么卡尔就要死？"] = "Но почему... почему Карл должен умереть?",
    ["可如果就这样冒险回去，无法保证安全……万一又被“2-049”控制住了呢？"] = "Но если я рискну вернуться вот так, нет никакой гарантии безопасности... Что, если меня снова возьмет под контроль 2-049?",
    ["可应该怎么找到隐藏空间？为什么是这三个地方？难道是……三个入口？"] = "Но как нам найти скрытое пространство? Почему именно эти три места? Может ли это быть... три входа?",
    ["可当上主角又怎样？无法掌控命运的我们，依然是自己人生的配角。"] = "Ну и что с того, что ты стал главным героем? Не властные над судьбой, мы всё равно остаёмся второстепенными персонажами в собственной жизни.",
    ["可怜虫"] = "Бедняги.",
    ["可恶！已经出不去，只能陪他玩玩了……"] = "Проклятье! Мне уже не выбраться, придётся поиграть с ним...",
    ["可惜，你不是正式队员，大概只能拿到百分之十。"] = "К сожалению, вы не являетесь формальным членом, поэтому, вероятно, получите только десять процентов.",
    ["可我们就是通过镜子进来的，那条路早就毁了……"] = "Но мы вошли через зеркало, и этот путь давно разрушен...",
    ["可是……"] = "Но...",
    ["可是……要怎样才能救他们？"] = "Но... как мы можем их спасти?",
    ["可是，我的票转卖的话，至少价值7个金镑！"] = "Но если перепродать мой билет, он потянет как минимум на 7 золотых фунтов!",
    ["可是，灰雾之上会不会有多个主宰？还是再加一重保险吧。"] = "Однако могут ли над серым туманом быть несколько мастеров? Мне лучше добавить еще один уровень страховки.",
    ["可梦里“愚者”先生说过，我的力量来源于他的一个尝试——嫁接？"] = "Но Мистер Шут сказал во сне, что моя сила возникла в результате одной из его попыток – подкупа?",
    ["可爱的小家伙，你一直在回答不知道、不清楚、想回家呢。"] = "Милый малыш, ты все время отвечал, что не знаешь, не уверен и хочешь домой.",
    ["可瑞尔并不是那样的人啊！"] = "Риэль не такой человек!",
    ["可能因为我十分迅速地又被卷入了一起危险的非凡事件。"] = "Возможно, потому, что меня очень быстро втянули в еще один опасный инцидент с Потусторонним.",
    ["可能因为我很有天赋。"] = "Может быть, это потому, что я очень талантлив.",
