    ["啊？"] = "Хм?",
    ["啊？<P_Heart>（“正义”女士给我2万苏勒，也用这笔钱做点好事吧。）</>"] = "Ах? <P_Heart> (Мисс Справедливость дала мне 20 000 золотых фунтов, мне следует использовать эти деньги и для добрых дел.) </>",
    ["啊？你还做主线啊？怪不得战力还比不过水贼！"] = "А? Ты ещё и основной сюжет проходишь? Неудивительно, что твоя боевая мощь слабее, чем у речного разбойника!",
    ["啊？和阿蒙相同途径的天使？！你也被寄生了？！伦纳德先生！"] = "А? Ангел того же Пути, что и Амон?! Тебя тоже паразитировали?! Господин Леонард!",
    ["啊？我没打算坐上去……马桶怎么会放在这里？"] = "Хм? Я не собиралась на нем сидеть... Почему здесь туалет?",
    ["啊？谁是安娜小姐？你在跟我说话？"] = "А? Кто такая госпожа Анна? Ты со мной разговариваешь?",
    ["啊？！"] = "А? !",
    ["啊？？？"] = "Ах???",
    ["啧，原来是演尸体的，这就是传说中的躺着赚钱？哈哈哈哈。"] = "Цк, так ты изображаешь труп? Это и есть легендарный заработок лёжа? Ха-ха-ха-ха.",
    ["喂……"] = "Привет...",
    ["喝口咖啡压压惊"] = "Выпейте кофе, чтобы успокоиться",
    ["喝咖啡"] = "Пить кофе",
    ["喝杯咖啡休息一下吧。"] = "Выпейте кофе и отдохните.",
    ["嗯……"] = "Хм...",
    ["嗯……克莱恩，其实你不用有太大压力，你肯定能通过大学讲师的面试的。"] = "Хм... Клейн, на самом деле тебе не обязательно находиться под слишком большим давлением. Вы обязательно пройдете собеседование с преподавателем университета.",
    ["嗯……如果你实在慌张，就把所有人想象成卷毛狒狒。当然，其实很多人的智商还不如卷毛狒狒。"] = "Хм... если ты очень нервничаешь, просто представь всех в виде кудрявых бабуинов. Конечно, на самом деле IQ многих людей даже не так высок, как у кудрявого павиана.",
    ["嗯……我们还有些事要聊，顺便叙叙旧。"] = "Хм... Нам еще есть о чем поговорить, и заодно наверстать упущенное в старых временах.",
    ["嗯……日记里有用鲁恩语和其他文字来记录，好在现在的我都能流畅理解，不愧是历史系大学生……"] = "Хм... дневник записан на ленском и других языках. К счастью, теперь я могу их свободно понимать. Как и ожидалось от специалиста по истории...",
    ["嗯……笔记的主人来自“<P_Yellow>安提哥努斯</>”家族，这个家族在第四纪有着显赫的地位，还有一些相关的历史……"] = "Хм... владелец ноутбука принадлежит к семейству <P_Yellow>Антигон</>. Эта семья имела выдающийся статус в Четвертой Эпохе, и с ней связана некоторая история…",
    ["嗯……诡异事件很可能会再次发生，我需要有抗衡危险的能力……"] = "Хм... странные события, скорее всего, произойдут снова. Мне нужна способность противостоять опасности...",
    ["嗯……饿了。"] = "Хм... Я голоден.",
    ["嗯。"] = "Мм.",
    ["嗯。找到他的住处后，我会远程引导他入梦，梦境会呈现出更多相关的线索。"] = "Хм. Найдя его место жительства, я удаленно проведу его в сон. Сон даст более важные подсказки.",
    ["嗯！我相信你们！"] = "Мм! Я верю в тебя!",
    ["嗯，他的新工作就在码头附近，每天都能看到去贝克兰德的船。"] = "Ну, его новая работа находится прямо возле причала, и он каждый день может видеть корабль, идущий в Баклунд.",
    ["嗯，会员可以免费使用占卜房、占卜工具，免费享用我们的咖啡和茶水。"] = "Да, члены клуба могут бесплатно пользоваться комнатами для гаданий, инструментами, а также бесплатно пить наш кофе и чай.",
    ["嗯，你们一定能行！"] = "Да, ребята, вы обязательно справитесь!",
    ["嗯，你闯入了一场向邪神献祭和祈祷的邪恶仪式。"] = "Хм, вы вторглись в злой ритуал, включающий жертвоприношения и молитвы злому богу.",
    ["嗯，可是……外面这层红色是什么？好像很危险……"] = "Да, но... что это за красный слой снаружи? Кажется, это очень опасно...",
    ["嗯，回去休息吧，这里交给我们。"] = "Мм, вернись и отдохни. Оставьте это нам.",
    ["嗯，回去好好享用晚餐。刚才消耗的沉眠符咒，我会找斯维因赔偿的，他可是个有钱人。当然，不是今天，我得考虑他的心情。"] = "Что ж, возвращайтесь и наслаждайтесь ужином. Я попрошу Суэйна компенсировать только что использованное заклинание сна; он богатый человек. Конечно, не сегодня; Я должен учитывать его настроение.",
    ["嗯，大家帮了我很多，我也要尽力承担自己的责任。"] = "Да, все мне так помогли, и я тоже должен приложить все силы, чтобы исполнить свой долг.",
    ["嗯，她和伊丽莎白都是神秘学爱好者。对了，明天晚上你们有空吗？"] = "Да, они с Элизабет оба энтузиасты оккультизма. Кстати, ты свободен завтра вечером?",
    ["嗯，它叫做“知识皇冠”，外形就是个皇冠，能力和窥秘人途径有关。"] = "Да, ее называют «Короной Знаний». Ее внешний вид напоминает корону, а ее способности связаны с путем Тайного Жреца.",
    ["嗯，就这么办。但愿在真正的危机降临之前，完成晋升。先回去吧。"] = "Что ж, это то, что я сделаю. Я надеюсь завершить продвижение до того, как наступит настоящий кризис. Давайте сначала вернемся.",
    ["嗯，希望有一天你们能找到摆脱诅咒的办法。"] = "Что ж, я надеюсь, что однажды ты найдешь способ избавиться от проклятия.",
    ["嗯，希望能从劳维斯太太残留的灵性里获得点什么。"] = "Да, я надеюсь получить что-то от остаточной духовности миссис Лоуис.",
    ["嗯，怎样才能找到其它的隐藏空间？"] = "Хм, а как нам найти другие потайные места?",
    ["嗯，我也从塔罗牌里挑吧。"] = "Хм, я тоже выберу из карт Таро.",
    ["嗯，我会尽快了解和适应这里，让自己帮得上忙的。"] = "Хм, я научусь и адаптируюсь к этому месту как можно скорее, чтобы иметь возможность быть полезным.",
    ["嗯，我去封锁中央广场，避免有人再带着铜镜靠近。"] = "Ладно, пойду блокировать Центральную площадь, чтобы не допустить, чтобы кто-нибудь еще приблизился с медным зеркалом.",
    ["嗯，我试试。"] = "Хм, я попробую.",
    ["嗯，是的。"] = "Хм, да.",
    ["嗯，最近我都会在。这次灾难的危机波及范围很大，也有不少伤亡情况，我会留下来处理相关善后工作。"] = "Да, я буду здесь в последнее время. Масштабы этой катастрофы достаточно велики, есть много жертв. Я останусь, чтобы разобраться с последствиями.",
    ["嗯，这些是从警察厅移交过来的失踪案，有些信息需要核实。"] = "Хм, это дела о пропавших без вести лицах, переданные из полицейского управления; некоторую информацию необходимо проверить.",
    ["嗯，这批失踪案有很多共性，所有献祭仪式都指向堕落母神。"] = "Да, в этой серии дел об исчезновениях есть много общего. Все ритуалы жертвоприношений указывают на Богиню-Матерь Разврата.",
    ["嗯？"] = "Хм?",
    ["嘿嘿，一点点口水，我刷了牙的。"] = "Хе-хе, немного слюны, я почистил зубы.",
    ["嘿嘿，只是“可能”出演。我这次去贝克兰德，就是要见导演和编剧，签演出合同，这对我来说非常重要。"] = "Хе-хе, роль лишь «возможная». В этот раз я еду в Бэкланд, чтобы встретиться с режиссёром и сценаристом и подписать контракт на постановку. Для меня это очень важно.",
    ["嘿，女士们先生们，您可能不认识我，但一定看过我演的剧！锵锵——《命运分岔的宅邸》。"] = "Эй, дамы и господа, вы, может, меня не знаете, но мои спектакли наверняка видели! Та-дам — «Особняк расходящихся судеб».",
    ["噢我在戏剧节做兼职，想邀请你在罗塞尔大帝画像上签名。"] = "О, я подрабатываю на фестивале драмы и хотела бы предложить вам расписаться на портрете императора Розеллы.",
