    ["回想“指引”"] = "Напомним «руководство»",
    ["回来了？但票刚刚卖完了，最近的班次都满了，后面的票还没开售。"] = "Назад? Но билеты только что были распроданы. Последние смены все заполнены, а билеты на последующие еще не поступили в продажу.",
    ["回来了？像是做了一场梦，那灰雾世界是什么玩意……"] = "Назад? Это было похоже на сон. Что же это был за мир серого тумана...",
    ["回溯"] = "Откат",
    ["因为他的事情，我在类似问题上总会有点激动……"] = "Из-за того, что с ним случилось, я всегда немного волнуюсь по поводу подобных вопросов...",
    ["因为在镜中廷根太久，污染太深，已经完全异化成怪物了？"] = "Из-за того, что ты слишком долго оставался в Тингене в Зеркале, а порча была слишком глубокой, ты полностью превратился в монстра?",
    ["因为我是黑荆棘安保公司的老员工，很快就满两年了。"] = "Поскольку я старый сотрудник охранной компании Чёрный Чертополох, скоро исполнится два года.",
    ["因为承受不住力量而发狂，因为听见未知存在的呓语而堕落，因为精神崩溃而人格扭曲。"] = "Сходят с ума, потому что не могут противостоять силе, падают, потому что слышат шепот неизвестных существ, и их личность искажается из-за психического коллапса.",
    ["因为迪伦的身份在我的身上。对，我和迪伦的身份和命运互换了。"] = "Потому что личность Дилана — на мне. Да, мы с Диланом поменялись личностями и судьбами.",
    ["因为那本安提哥努斯家族笔记，我被牵扯进了一件诡异的事件里。"] = "Из-за этой семейной записной книжки Антигонов я стал участником жуткого события.",
    ["在“愚者”先生的启示中，它将来还有更重要的用途。"] = "Согласно откровению Господина Шута, в будущем этому найдется куда более важное применение.",
    ["在他们眼中，我的身份也在不断变化。"] = "В их глазах моя личность тоже постоянно меняется.",
    ["在他的办公室，昨晚是他值夜。"] = "В своем кабинете. Вчера вечером он был на ночном дежурстве.",
    ["在你的梦境中，治愈你。"] = "Во сне исцелю тебя.",
    ["在几轮紧张刺激的“斗邪恶”之后……"] = "После нескольких раундов напряженной и захватывающей «борьбы со злом»…",
    ["在刚才的战斗里，我本来想多帮帮你，可发现你并不需要。"] = "Во время предыдущего боя я хотел помочь тебе больше, но понял, что тебе это не нужно.",
    ["在合适的时机和地点，金币会指引你。“观看”我留下的历史，让历史孔隙更接纳你。"] = "В нужное время и в нужном месте золотая монета приведет вас. «Наблюдайте» за историей, которую я оставил позади, и позвольте пробелам в истории принять вас больше.",
    ["在呢，{{先生|女士}}！还有什么事吗？如果您有空，我也想再和您聊聊，关于剧本，关于表演……"] = "Я здесь, {{господин|госпожа}}! Что-то ещё? Если у вас есть время, мне бы хотелось ещё поговорить с вами о сценарии, об игре…",
    ["在哪里？"] = "Где это?",
    ["在工厂区那日夜累积的怨念滋润下，在那实质般的昏暗和压抑催化下，计划顺利进行。”"] = "Благодаря негодованию, копившемуся днем и ночью на территории фабрики, а также усиленному полной темнотой и депрессией, план прошел гладко. \"",
    ["在您伟岸的身姿和雄厚的财富面前，所有人都是孩子。"] = "Перед вашим величественным обликом и огромным богатством все — лишь дети.",
    ["在旁人艳羡的目光中，你优雅地坐在了黄金马桶上。"] = "Под завистливые взгляды окружающих вы элегантно сидите на золотом унитазе.",
    ["在漫长的实验和摸索中，人类形成了一些逐阶提升、稳定增长的序列链条，也叫做<P_Yellow>非凡途径</>。"] = "В ходе долгих экспериментов и поисков человечество сформировало цепочки последовательностей для постепенного и устойчивого возвышения, также именуемые <P_Yellow>Путями Потусторонних</>.",
    ["在潜意识海洋中，你看到了一条盘旋的巨龙。"] = "В Океане Подсознания вы увидели свернувшегося кольцами гигантского дракона.",
    ["在猎龙帮面前，就别说什么想还是不想的事了。"] = "Перед бандой охотников на драконов не говорите о том, хотите вы этого или нет.",
    ["在这么暗的地方画画？为什么不去娱乐室，至少那里有灯。"] = "Рисуете в таком темном месте? Почему бы не пойти в комнату отдыха? По крайней мере, там есть свет.",
    ["在这场神明的博弈中，你对世界的未来非常重要。"] = "В этой игре богов вы очень важны для будущего мира.",
    ["在那些冒险小说里，这就叫两位主角相遇了，历史的车轮开始滚滚向前。"] = "В приключенческих романах это называется встречей двух главных героев, и колесо истории начинает катиться вперед.",
    ["在那里，你应该称呼他为“伦纳德”先生。"] = "Там вам следует обратиться к нему как к мистеру Леонарду.",
    ["在那里，我遇到了一个海盗打扮的女士，她告诉我进入镜中廷根的方法，也告诉我罗珊在安全屋。"] = "Там я встретил даму, одетую пираткой, которая рассказала мне, как войти в Тинген в Зеркале, а также рассказала, что Розанна находится в Убежище.",
    ["在酒吧内打听到相应线索"] = "Расспросить в баре и найти зацепки",
    ["在酒吧内搜寻所需物品"] = "Поиск необходимых предметов в баре",
    ["在银片正反面雕刻古赫密斯语的“黑夜”作为咒文，再向女神祈祷即可完成。"] = "Выгравируйте заклинание «Ночь» в Древнем Гермесе на обеих сторонах серебряной монеты, а затем помолитесь Богине, чтобы она завершила его.",
    ["在镜中廷根，我们明明很努力了，却还是救不了所有人，只能眼睁睁看着他们变成一道道洪流……"] = "В «Тингене в зеркале» мы явно старались изо всех сил, но спасти всех нам все равно не удалось. Нам оставалось только беспомощно наблюдать, как они превращались в потоки информации...",
    ["在镜中廷根，我又听到噩梦中的那些声音……"] = "В «Тингене в зеркале» я снова услышал голоса из ночных кошмаров...",
    ["在镜中廷根，绝望魔镜破碎时，也是祂用非凡能力让时间暂停，我才能帮你们避开危险。"] = "В Тингене в зеркале, когда Волшебное зеркало отчаяния разбилось, именно Он остановил время своими сверхъестественными силами, и я смог помочь вам избежать опасности.",
    ["在附近寻找<P_Yellow>旅行尖碑</>，那是“魔术师”小姐的杰作。"] = "Поищите поблизости обелиск <P_Yellow>Travel Obelisk</> — шедевр Мисс Волшебница.",
    ["在非凡世界要时刻保持警惕，尤其是在魔药消化和晋升的时候。"] = "Вы всегда должны сохранять бдительность в Необыкновенном мире, особенно во время переваривания зелий и продвижения.",
    ["在非凡世界里，干扰占卜的手段有很多，而且特莉丝应该序列不低，这个等级的非凡者并不那么容易抓到。"] = "В Необыкновенном Мире существует множество способов помешать гаданию, и Трисси должна быть высокой Последовательности. Экстраординара такого уровня поймать непросто.",
    ["在非凡力量的影响下，人的思维是疯狂和混乱的，但他可能潜意识认为，工厂就是安全的地方。"] = "Под воздействием необычайной силы мышление человека становится безумным и хаотичным, но он может подсознательно думать, что фабрика — безопасное место.",
    ["在黑气的剪影中，一个人扭曲地往后翻折，变成了一个巨大的狼人"] = "В силуэте черной энергии человек изогнулся и свернулся назад, превратившись в гигантского оборотня.",
    ["地点"] = "Место",
    ["坐下"] = "Сесть",
    ["坚果"] = "Орех",
    ["坦白地讲，我对自己能活着回来依旧感觉梦幻，依旧不敢相信自己能从<P_Yellow>苜蓿号的惨案</>中幸存下来……"] = "Честно говоря, мне до сих пор снится, что я смог вернуться живым, и до сих пор не могу поверить, что пережил трагедию <P_Yellow> Clover </>...",
    ["坦诚说明"] = "Объясните честно",
    ["坦诚说服"] = "Искреннее убеждение",
    ["垃圾角色！又是只有一句台词的垃圾角色！迪伦，你这个废物！"] = "Бесполезный персонаж! Опять бесполезный персонаж с одной-единственной репликой! Дилан, ты никчёмество!",
    ["城外农庄刚运来的蔬菜，便宜又新鲜！"] = "Овощи только что привезенные с загородных ферм, дешевые и свежие!",
    ["塔罗会"] = "Клуб Таро",
    ["塔罗？<P_Heart>（塔罗牌好像也是那位罗塞尔大帝发明的，不知道跟地球的塔罗占卜有什么不同……）</>"] = "Таро? <P_Heart>(Карты Таро, кажется, тоже были изобретены императором Розеллой. Интересно, чем это отличается от гадания на Таро на Земле...)</>",
    ["墙上、地板上、书桌上，红的白的……呕……"] = "На стене, на полу, на столе, красное и белое... Ух...",
    ["多亏了罗珊小姐。"] = "Спасибо мисс Розанне.",
    ["多少钱?"] = "Сколько?",
    ["多少钱？"] = "Сколько?",
    ["多攒钱，攒了钱就可以去贝克兰德，带汤姆坐火车，看贝克兰德大桥……"] = "Сэкономьте больше денег, и на эти деньги я смогу поехать в Бэкланд, отвезти Тома на поезд и посмотреть мост Бэкланд...",
    ["多谢！这是你的脚踏车？"] = "Спасибо! Это твой велосипед?",
    ["夜里可以把尸体放桌子上，吃东西的时候，就把她抱到床上去……"] = "Вы можете оставить тело на столе на ночь, а когда поедите, просто переместить ее на кровать...",
    ["大剧院？罗塞尔戏剧节？怎么又是罗塞尔……"] = "Большой театр? Розельский драматический фестиваль? Почему это снова Розель...",
    ["大学面试"] = "Интервью в университете",
    ["大家都没事吧？"] = "Все целы?",
    ["大家都站好，该拍照了！"] = "Всем стоять на месте, пора фотографироваться!",
    ["大概情况我已经清楚了，死者是凯蒂·斯蒂芬娜·比伯，55岁到60岁之间，寡妇。"] = "Имею общее представление о ситуации. Погибшая - Кэти Стефана Бибер, 55-60 лет, вдова.",
    ["大概率当场死亡，如果它们撑过去了，应该就能成为超凡生物，甚至还会变聪明。"] = "По всей вероятности, он умрет на месте. Если ему удастся выжить, он станет необыкновенным существом и, возможно, даже станет умнее.",
    ["大部分人只会向正神教会祈求……就算得不到启示，应该也不会有危险。"] = "Большинство людей молятся только Православным Церквям... даже если они не получат откровения, никакой опасности быть не должно.",
    ["天才的思路，对吧？"] = "Гениальная идея, правда?",
    ["太多了，我可以先少领一点。"] = "Это слишком много. Сейчас я могу взять меньше.",
    ["太好了！那我要用什么来交换配方呢？"] = "Большой! Тогда что мне следует использовать для обмена на формулу?",
    ["太阳下山以后，她就不再工作了，蜡烛和煤油可比火柴盒贵多了。"] = "После захода солнца она перестала работать. Свечи и керосин стоят гораздо дороже спичечных коробков.",
    ["失控？"] = "Потеря контроля?",
    ["失踪者路过三个地点，被知识皇冠瓦解消散而失踪，这是失踪案的真相？"] = "Пропавший человек прошел через три локации, был расчленен и исчез Короной Знаний. Это правда о деле об исчезновении?",
    ["头又怎么了，好晕，想吐……"] = "Что опять не так с моей головой? Так кружится голова, что хочется рвоты...",
    ["头发"] = "Волосы",
    ["头发算不算“不好的事物”？试试看……好疼！"] = "Волосы – это «плохо»? Попробуйте... это больно!",
    ["头版头条？不会又是罗塞尔大帝吧……"] = "Заголовок на первой полосе? Это не будет снова император Розель, не так ли...",
    ["奇怪，塔罗里没有这种牌，可能是谁把其他牌混杂进来了，稍后我们可以重新抽一张……"] = "Странно, этой карты нет в колоде Таро. Возможно кто-то подмешал другие карты. Позже нарисуем еще один...",
    ["奥利安娜？她通常只会待在<P_Yellow>楼上</>，你去看看吧。"] = "Орианна? Обычно она остается только <P_Yellow>наверху</>. Иди посмотри.",
    ["奥黛丽自我介绍“正义”，回顾序章内容：\n你被邪神污染，被愚者解救。"] = "Одри представляется как «Справедливость» и напоминает о событиях пролога:\nвы были осквернены злым богом и спасены господином Шутом.",
    ["奥黛丽：伟大的“愚者”先生，也曾在这里生活。\n-小资咖啡\n窗外阳光正好，临街咖啡桌几对、情侣正在交谈。\n佛尔思和休坐一起，盯着眼前一块蛋糕，桌上放红酒。"] = "Одри: Великий господин Шут тоже когда-то жил здесь.\n— Уютная кофейня\nЗа окном ласково светит солнце, за столиками на открытой террасе переговариваются парочки влюбленных.\nФорс и Сио сидят рядышком, разглядывая кусочек торта перед собой; на столе бокалы с красным вином.",
    ["女士，先生，你们是否找到罗塞尔的日记？"] = "Дамы и господа, вы нашли дневник Розеллы?",
    ["女士，先生，记住了。那么，今天就到这里。"] = "Дамы и господа, помните об этом. Это все на сегодня.",
    ["女士，您可以挑选任何一位占卜师。"] = "Мадам, вы можете выбрать любого прорицателя.",
    ["女士，您的脸色不太好，不舒服吗？"] = "Госпожа, вы неважно выглядите. Вам нездоровится?",
    ["女士，这些是珠宝店的顾客？需要帮忙吗？"] = "Мэм, это покупатели ювелирного магазина? Вам нужна помощь?",
    ["女巫？！"] = "Ведьма?!",
    ["女神啊……你找了什么工作！"] = "Богиня... какую работу ты нашла!",
    ["女神啊……这么多活吗？"] = "Богиня... неужели так много работы?",
    ["女神啊！怎么会变成这个样子？"] = "Богиня! Как все закончилось таким образом?",
    ["女神啊，我看见了什么！一个下等人，趴在金玫瑰大厅，弄脏我脚下的地板。"] = "О Богиня, что я вижу! Простолюдин лежит в зале «Золотая роза» и пачкает пол у меня под ногами.",
    ["女神庇佑，希望这种送上门的倒霉蛋再多一点吧。"] = "Благослови меня Богиня, я надеюсь, что таких несчастных людей, приходящих ко мне в дверь, станет больше.",
    ["女神庇佑，愿她早日康复。"] = "Богиня Защиты, пусть она скорее выздоровеет.",
    ["她不忙的时候，就看看书，在纸上写写画画。"] = "Когда она не была занята, она читала книги и писала или рисовала на бумаге.",
    ["她去世后，我跟梅丽莎他们也时不时会来教堂祈祷，我算得上女神真正的信徒。"] = "После ее смерти мы с Мелиссой все равно время от времени ходили в собор помолиться. Меня можно считать истинно верующим в Богиню.",
    ["她可能会昏睡几分钟，但没别的问题。不过她的神秘学老师太不靠谱了，居然没告诉她基本的禁忌事项。"] = "Несколько минут она может чувствовать сонливость, но в остальном все в порядке. Но ее оккультный учитель был настолько ненадежен, что не рассказал ей об основных табу.",
    ["她和儿子一起租住在这里十多年了。据附近的邻居说，已经超过一周没见到他们了。"] = "Она и ее сын снимают здесь квартиру уже более десяти лет. По словам соседей, их не видели уже больше недели.",
    ["她好像很专注……还是过去跟她打个招呼吧。"] = "Кажется, она очень сосредоточена... Пожалуй, подойду и поздороваюсь с ней.",
    ["她应该去寻找咖啡馆去了。"] = "Ей следовало пойти поискать кафе.",
    ["她想赞助你一笔零花钱，又怕你不好意思收。"] = "Она хочет спонсировать тебя на карманные расходы, но боится, что тебе будет слишком неловко их принять.",
    ["她是子爵夫人，是真正的贵族，是为廷根带来新生的使者。"] = "Она виконтесса, настоящая аристократка и посланница, принесшая Тингену новую жизнь.",
    ["她没告诉你们她叫什么吗？感觉她在有意帮助我们，但……不愿意暴露身份？"] = "Разве она не сказала тебе свое имя? Такое ощущение, что она намеренно помогает нам, но... она не хочет раскрывать свою личность?",
    ["她短头发，大概……大概跟你差不多高。"] = "У нее короткие волосы, примерно... примерно такого же роста, как ты.",
    ["她说她很累，让我跟两个孩子说说话，她先休息一下，等我再看她的时候，她已经……已经停止了呼吸。"] = "Она сказала, что устала, и попросила меня поговорить с двумя детьми, а она немного отдохнет. Когда я снова посмотрел на нее, она... перестала дышать.",
    ["好"] = "Хороший",
    ["好、好好好，只要保护好我，你要多少钱都可以！"] = "Хорошо, хорошо, хорошо! Пока ты защищаешь меня, я буду платить тебе все, что ты захочешь!",
    ["好、好的。"] = "Хорошо, хорошо.",
    ["好、好的。其实，我暂时也没钱给她下葬，还得攒几天，攒几天……还好最近天气凉快了。"] = "Х-хорошо. На самом деле у меня пока нет денег на ее похороны, надо подкопить еще пару дней, еще пару дней... Хорошо хоть погода стала прохладнее.",
    ["好。可能还会遇到别的危险，小心！"] = "Хорошо. Мы можем столкнуться с другими опасностями, так что будьте осторожны!",
    ["好。失踪案没有太多信息，不过他们的经历多少都和罗塞尔大帝有关。"] = "Хороший. Информации о делах о пропавших без вести людях не так много, но все их события в некоторой степени связаны с императором Розеллой.",
    ["好。我们通过占卜确定，失踪地点只有三个，五月庄园、中央广场和廷根湖。"] = "Хорошо. Путем гадания мы определили, что мест исчезновений всего три: Мэй-Мэнор, Центральная площадь и озеро Тинген.",
    ["好主意"] = "Хорошая идея",
    ["好了"] = "Хорошо",
    ["好了。"] = "Хорошо.",
    ["好了。从今天起，您就是占卜俱乐部的正式会员，您的名字也已经在占卜师名册上了。"] = "Готово. С сегодняшнего дня вы официальный член Клуба Провидцев, и ваше имя уже внесено в список предсказателей.",
    ["好了好了，梅丽莎，我已经领会到你出色的数学天赋了。"] = "Ладно, ладно, Мелисса, я уже оценил твой выдающийся математический талант.",
    ["好了好了，赶紧开始享用晚餐吧，我真的太饿了。"] = "Ладно, ладно, начнём наслаждаться ужином, я правда слишком голоден.",
    ["好了新人，回去好好睡一觉，你的工作明天才正式开始。"] = "Ладно, новичок, иди выспись хорошенько. Твоя работа официально начнется только завтра.",
    ["好了！"] = "Хорошо!",
    ["好了！“正义”小姐该请我喝咖啡了。"] = "Хорошо! Мисс Джастис должна угостить меня кофе.",
    ["好了，今天就到这里吧。"] = "Хорошо, давайте остановимся здесь на сегодня.",
    ["好了，今天的聚会就到这里吧。"] = "Что ж, на сегодня наше собрание окончено.",
    ["好了，你想先看哪张牌？"] = "Что ж, какую карту ты хочешь посмотреть первой?",
    ["好了，做出你的决定吧，你已经没有多少时间可以浪费了。"] = "Хорошо, принимай решение. У вас не так много времени, чтобы тратить его впустую.",
    ["好了，克莱恩·莫雷蒂先生，祝你今晚依旧有个好梦。"] = "Хорошо, мистер Клейн Моретти, желаю вам сегодня еще хороших снов.",
    ["好了，克莱恩，你可以开始通灵了。"] = "Хорошо, Клейн, ты можешь начать Духовный Медиумизм.",
    ["好了，去吧。死了，也不用挨饿了。"] = "Хорошо, давай. Мертв, больше не нужно голодать.",
    ["好了，去告诉老尼尔吧。"] = "Хорошо, иди скажи Старине Нилу.",
    ["好了，尝尝吧。"] = "Ладно, попробуй.",
    ["好了，我们该出发了。"] = "Ладно, нам пора отправляться.",
    ["好了，结束了。回去吧，回去吧……"] = "Ну вот и всё, конец. Возвращайся, возвращайся...",
    ["好了，还有什么需要我帮忙的吗？"] = "Хорошо, могу ли я чем-нибудь еще помочь?",
    ["好了，这次的历史之旅结束了，回去好好休息吧。期待下次再见。"] = "Что ж, на этом наше историческое путешествие окончено. Возвращайтесь и хорошенько отдохните. Буду ждать новой встречи.",
    ["好了？这颜色和气味……似乎不太好下咽。"] = "Сделанный? Этот цвет и запах... Кажется, его нелегко проглотить.",
    ["好像……好一些了。我还需要做什么？"] = "Кажется... стало лучше. Что мне ещё нужно сделать?",
    ["好可怕……不过曾经涉及非凡的人，是会有更高概率再被非凡事件影响……"] = "Какой ужас... Впрочем, те, кто хоть раз соприкасался с потусторонним, с гораздо большей вероятностью снова столкнутся с подобным...",
    ["好吧"] = "Ладно",
    ["好吧……我们现在要去哪里？ "] = "Хорошо... куда мы сейчас идем?",
    ["好吧……我好像确实没什么钱。"] = "Ну... Наверное, у меня действительно не так уж много денег.",
    ["好吧。"] = "Отлично.",
    ["好吧，听你这么一说……我还真有点想试试了。"] = "Хорошо, раз уж ты об этом упомянул... Я правда хочу попробовать.",
    ["好吧，我去拿纸和笔，我们来签署“中止合约”。"] = "Хорошо, я пойду за бумагой и ручкой, и мы подпишем «Расторжение контракта».",
    ["好吧，我这就回去。奇怪……阿廖莎的病情之前不是一直在好转吗？"] = "Хорошо, я сейчас вернусь. Странно... разве состояние Алеши все это время не улучшалось?",
    ["好吧，抱歉……我的父亲曾经是值夜者正式队员，五年前牺牲在了一次非凡事件里。"] = "Ладно, извини... Мой отец когда-то был формальным членом «Ночных ястребов»; он пожертвовал собой во время инцидента с Потусторонний пять лет назад.",
    ["好吧，查理是个好人，从贫民窟混血儿，到金梧桐区大富翁……"] = "Ладно, Чарли хороший человек, от полукровки из трущоб до магната в районе Золотого Феникса...",
    ["好吧，这么快就走远了……"] = "Ну, они так быстро ушли далеко...",
    ["好吧，那——小绅士，买一份今天的报纸。"] = "Хорошо, тогда маленький джентльмен, я куплю сегодняшнюю газету.",
    ["好吧，那我先去核实失踪案信息，等有更多线索再调查那对兄妹的事。"] = "Хорошо, тогда я сначала проверю информацию о пропавших без вести людях и расследую дело братьев и сестер, когда появятся новые улики.",
    ["好吧，那我是不是应该称呼你……前辈？"] = "Хорошо, тогда мне следует называть тебя... старшим?",
    ["好啊。"] = "Конечно.",
    ["好嘞，您看这块怎么样？新鲜又肥美！"] = "Хорошо! Как насчет этого произведения? Свежий и жирный!",
    ["好在你不一样，我也不一样。"] = "К счастью, ты другой, и я тоже другой.",
    ["好在你们也救出了很多人，廷根的守护者们又一次证明了——黑暗永远无法完全吞噬光明。"] = "К счастью, вы также спасли много людей. Стражи Тингена еще раз доказали, что тьма никогда не сможет полностью поглотить свет.",
    ["好多东西！这是一套新衣服，还有一把……钥匙？"] = "Сколько всего! Это новый комплект одежды, а еще... ключ?",
    ["好多人，邮差会在哪里？"] = "Столько людей, где же может быть почтальон?",
    ["好大的雨……卡尔会喜欢吗？"] = "Какой сильный дождь... Карлу он понравится?",
    ["好孩子。"] = "Хороший ребёнок.",
    ["好孩子，别学他。"] = "Хороший мальчик, не бери с него пример.",
    ["好心安慰"] = "Добрый комфорт",
    ["好暗，得先把灯打开。"] = "Здесь так темно, мне нужно сначала включить свет.",
    ["好痛！头好痛！"] = "Так больно! У меня так болит голова!",
