    ["孩子们，没有永恒的安全。"] = "Дети, вечной безопасности не существует.",
    ["它们被划分为不同的危险等级，需要被严格看管或封印起来。"] = "Они подразделяются на разные уровни опасности и требуют строгой охраны или опечатывания.",
    ["它属于因蒂斯的蒸汽与机械之神教会，近期因污染活化而出逃到鲁恩。"] = "Оно принадлежит Церкви Бога Пара и Машин в Интисе и недавно сбежало в Руэн из-за пробуждения скверны.",
    ["它手忙脚乱地关了灶台，触手又伸向库克。"] = "Он неуклюже выключает плиту и снова тянется к Куку.",
    ["它是人偶。"] = "Это кукла.",
    ["它是从因蒂斯进口、现在最潮流的款式，马甲边缘用了金线点缀，领口也用了真正的宝石来装饰。"] = "Это самый модный стиль, импортированный из Интис. Края жилета декорированы золотой нитью, а воротник украшен настоящими драгоценными камнями.",
    ["它是当年罗塞尔大帝被刺杀后的遗物，其中有堕落母神污染的残留。"] = "Это реликвия, оставшаяся со времен убийства императора Розеллы, и она содержит остатки порчи Матери-Богини Разврата.",
    ["它是能改变生命本质的魔法药剂，喝下吧。"] = "Это волшебное зелье, способное изменить суть жизни. Выпей это.",
    ["它非常独特，是罗塞尔大帝发明的黄金抽水马桶。"] = "Это очень уникально; это унитаз с золотым смывом, изобретенный императором Розелем.",
    ["安保人员呢？没人通知安保人员吗？把这个……不管他是什么，给我拖出去！"] = "Где охрана? Никто не вызвал охрану? Вытащите это... что бы это ни было, прочь отсюда!",
    ["安保公司……您曾是安保？"] = "Охранное предприятие... Вы раньше работали в охране?",
    ["安保公司？"] = "Охранная компания?",
    ["安保公司？幸好不是警察，警察全是饭桶。"] = "Охранная компания? К счастью, не полиция: полицейские все никчёмные бездельники.",
    ["安全屋是其中一个隐藏空间，我解开谜题后得到了这个。"] = "Безопасный дом — одно из таких скрытых пространств. Я получил это после решения головоломки.",
    ["安全屋？你刚刚让丹尼去廷根大剧院，那里是安全屋？你怎么知道的？"] = "Безопасный дом? Ты только что сказал Дэнни пойти в Большой театр Тинген, это убежище? Как вы узнали?",
    ["安娜小姐，你想占卜什么？"] = "Мисс Анна, что бы вы хотели угадать?",
    ["安娜小姐，我两天没吃东西了。发发善心吧，哪怕是一个铜便士。"] = "Мисс Анна, я два дня ничего не ел. Сжальтесь, хотя бы медный пенни.",
    ["安娜小姐，有结果了。"] = "Мисс Анна, у меня есть результат.",
    ["安提哥努斯……"] = "Антигон...",
    ["安提哥努斯家族笔记案件暂告一段落，但穿越的真相、霍纳奇斯山脉这些谜题都还没解开……"] = "Дело о «Семейной записной книжке Антигонов» временно подошло к концу, но правда о моем переселении, горном хребте Хорнацис и других тайнах остается неразгаданной...",
    ["安提哥努斯家族笔记终于找回来了，被队长带走封印起来了。"] = "Дневник семьи Антигон наконец возвращен. Капитан забрал его, чтобы запечатать.",
    ["安洁莉卡小姐，你在为海纳斯·凡森特先生的遭遇难过吗？"] = "Мисс Анжелика, вам грустно из-за того, что случилось с мистером Хейнсом Винсентом?",
    ["完全正确！"] = "Совершенно верно!",
    ["完成沐浴后，确认窗帘全部拉拢，点一根蜡烛摆放在镜子前面，虔诚地向你信仰的神灵祈求……"] = "Приняв ванну, убедитесь, что шторы плотно задернуты, зажгите свечу перед зеркалом и благоговейно вознесите молитву божеству, в которое веруете...",
    ["完整扮演"] = "Полная актерская игра",
    ["官方非凡者的身份能提供不少帮助。"] = "Статус официального Потустороннего дает немало преимуществ.",
    ["实际上它并不贵，因为最初只是半成品，我仿照之前见过的文物，雕刻了祝福的咒语和漂亮的花纹上去。"] = "На самом деле это было не дорого, потому что поначалу это был просто полуфабрикат. Я подражал артефактам, которые видел раньше, и вырезал на них благословляющее заклинание и красивые узоры.",
    ["客舱票"] = "Билет на каюту",
    ["室内宴会，俱乐部室内，贵族举行奢侈的宴会，舞蹈社交等。\n一张桌子上，苍白的手酒杯旁留下“节制”塔罗牌。\n（可以从室内玻璃光照，看出来外面雨停天晴了。）"] = "Банкет в клубе: аристократы устраивают роскошный приём с танцами и светскими беседами.\nНа одном из столиков бледная рука оставляет карту Таро «Умеренность» рядом с бокалом вина.\n(По свету сквозь витражи заметно, что за окном дождь прекратился и небо прояснилось.)",
    ["家里有一个意料之外的人——班森。看见克莱恩后，他笑着打了个招呼。"] = "Дома появился неожиданный человек — Бенсон. Увидев Клейн, он приветствует его с улыбкой.",
    ["家里现在全靠做文员工作的班森维持，要同时养着两个还在读书的弟弟妹妹，真是辛苦啊……"] = "Теперь семья полностью полагается на Бенсона, который работает клерком. Очень сложно содержать двух младших братьев и сестер, которые одновременно учатся в школе...",
    ["宽限？你的时间一便士不值，现在，从我眼前消失！"] = "Отсрочка? Твоё время не стоит и пенни. А теперь исчезни с глаз моих!",
    ["对……我现在该怎么做？"] = "Да... Что мне теперь делать?",
    ["对、对面房间。"] = "Комната через зал.",
    ["对不起！对不起！卡尔！我只能当群演！我……我改变不了命运！"] = "Прости! Прости! Карл! Я могу быть только статистом! Я... я не могу изменить судьбу!",
    ["对不起，我们先过去看看她的情况。如果找到兰尔乌斯的随身物品，我会再来找你。"] = "Извините, сначала мы придем и проверим ее ситуацию. Если я найду какие-нибудь личные вещи Инса Зангвилла, я приду за тобой снова.",
    ["对了！威尔送给我的。呃，怎么回事？！我把自己当成琳达了？"] = "Точно! Это мне подарил Уилл. Ох, что такое?! Я принял себя за Линду?",
    ["对了，{{先生|女士}}， 要不要来份今天的报纸？这次的头版头条可不一般呢。"] = "Кстати, {{sir|madam}}, хочешь сегодняшнюю газету? Заголовок на первой полосе на этот раз весьма необычен.",
    ["对了，三年前有位新任大主教带着一件“0”级封印物失踪。"] = "Кстати, три года назад новоназначенный архиепископ исчез с запечатанным артефактом нулевого уровня.",
    ["对了，丽贝卡，你知道刚才那些人是谁吗？"] = "Кстати, Ребекка, ты знаешь, кто сейчас были эти люди?",
    ["对了，之前罗塞尔大帝的手稿提过消化魔药的关键……"] = "Кстати, в рукописи императора Розеля упоминался ключ к усвоению зелий...",
    ["对了，伊丽莎白、梅丽莎，我最近跟一位老师学了<P_Yellow>新占卜</>，要来我房间试下吗？"] = "Кстати, Элизабет, Мелисса, я недавно узнала <P_Yellow> новое гадание</> от учителя. Хочешь прийти в мою комнату и попробовать?",
    ["对了，伦纳德先生，您出现时似乎都会有钟声？我之前也听到过几次洪亮的钟声，那也来源于您？"] = "Кстати, господин Леонард, при вашем появлении, кажется, всегда раздаётся колокольный звон? Я и раньше несколько раз слышал гулкий звон колокола, он тоже исходил от вас?",
    ["对了，伦纳德说，“蒲公英”带妹妹离开廷根，去了贝克兰德。"] = "Кстати, Леонард рассказал, что «Одуванчик» забрал его сестру и уехал из Тингена в Бэкланд.",
    ["对了，你亲自去调查五月庄园的话，那善后工作怎么办？"] = "Кстати, если вы сами отправитесь исследовать Мэй-Мэнор, как насчет последствий?",
    ["对了，你需要预订工作餐吗？不过……是自费的。"] = "Кстати, тебе нужно заказать рабочий обед? Хотя... это за ваш счет.",
    ["对了，再转动冰淇淋试试，这时候需要一点好运！"] = "Точно, попробуйте ещё раз повернуть мороженое, сейчас нужна немного удачи!",
    ["对了，夫人和管家也都是月亮仆从的成员。弗莱，再说下你查到的线索吧。"] = "Кстати, виконтесса и дворецкий тоже состоят в секте Слуг Луны. Фрай, расскажи подробнее об уликах, которые тебе удалось обнаружить.",
    ["对了，尸体可以再等一天下葬吗？或许还会有一次检查。"] = "Кстати, может ли тело подождать с погребением еще денек? Возможно, потребуется еще один осмотр.",
    ["对了，我是个占卜家啊！"] = "Верно, я Провидец!",
    ["对了，我是演员，他是邮差。{{PlayerName}}，你是做什么的？"] = "Да, я актёр, а он почтальон. {{PlayerName}}, а ты чем занимаешься?",
    ["对了，我还买了张罗塞尔邮票……送给你吧。"] = "Кстати, я ещё купил марку с Розелем... Дарю её тебе.",
    ["对了，我遇到过五月庄园管家，他在招募短工，修剪苹果林。"] = "Кстати, я встретил дворецкого Мэй-Мэнора. Он набирает краткосрочных рабочих для обрезки яблоневого сада.",
    ["对了，明天的神秘学课程别忘了。"] = "Кстати, не забудь завтрашний урок оккультизма.",
    ["对了，有位朋友最近从未来的命运中，窥见你的特殊。"] = "Кстати, друг недавно мельком увидел твою уникальность в судьбе будущего.",
    ["对了，梅丽莎在里间睡觉！"] = "Верно, Мелисса спит во внутренней комнате!",
    ["对了，灵性感知提升后，你就可以尝试开启灵视了。"] = "Кстати, после того, как ваше духовное восприятие улучшится, вы можете попробовать включить духовное зрение.",
    ["对了，还有这些子弹，这是你的入职物资，拿好了。"] = "Кстати, такие пули тоже есть. Это ваши вступительные материалы. Возьмите их.",
    ["对了，这里有非凡战斗的痕迹，还有污染残留。"] = "Кстати, здесь есть следы боя с Потусторонними, а также остаточная Искажение.",
    ["对了，那本笔记上提到过<P_Yellow>霍纳奇斯</>山脉的夜之国！刚才梦境里的宫殿就在山峰上！"] = "Кстати, в той записной книжке упоминалась Страна Ночи в горном массиве <P_Yellow> Hornacis </>! Дворец во сне только что находился на вершине горы!",
    ["对了，那本笔记！"] = "Да, этот блокнот!",
    ["对于占卜家而言，梦属于神明给予的启示，也是灵性对你的提醒。"] = "Для Провидца сны — это откровения, данные богами, и напоминание о вашей духовности.",
    ["对于非聚会人员而言，没有我的允许，不得告知此地的秘密。"] = "Тем, кто не является членом собрания, вы не должны раскрывать тайны этого места без моего разрешения.",
    ["对哦，我不打了，世界上在喊打罗塞尔童话副本。"] = "А, точно, я пас: в мировом чате зовут в подземелье «Сказка Розеля».",
    ["对嘛，别那么紧张。"] = "Правильно, не нервничай так.",
    ["对我们这种需要经常探索隐秘、经常进行练习、尝试仪式的非凡者来说，薪水总是不够。"] = "Для таких Потусторонних, как мы, которым нужно часто исследовать секреты, практиковаться и совершать ритуалы, зарплаты никогда не бывает достаточно.",
    ["对等原则？"] = "Принцип эквивалентности?",
    ["对这种有计划有目的的犯罪者来说，最开始挑选的目标肯定会远离祭台所在的区域，这源于追求安全的本能。"] = "Для преступника, который планирует и действует целенаправленно, цели, выбранные вначале, определенно будут находиться далеко от места, где расположен алтарь, что обусловлено инстинктом поиска безопасности.",
    ["对面端坐优雅的贵族少女奥黛丽，身旁趴一只金毛大狗。\n少女手旁桌上，静静放一张愚者牌。"] = "Одри, элегантная аристократическая девушка, сидела напротив, а рядом с ней лежала большая собака золотистого ретривера. \n На столе рядом с девочкой незаметно лежала карта Шута.",
    ["对面那位明显出身高贵的小姐和我也有各自的资源和人脉。或许有一天，我们也可以帮您处理一些小事。"] = "У сидящей напротив благородной дамы и у меня есть собственные ресурсы и связи. Быть может, однажды мы сумеем помочь вам в каких-то делах.",
    ["对！是哥哥给我买的！"] = "Да! Мой брат купил его для меня!",
    ["对！阁下，请您做我们交易的见证。"] = "Да! Сэр, пожалуйста, засвидетельствуйте нашу сделку.",
    ["对，但你看起来并不惊讶，我之前的当事人哪怕刚做完梦，也不相信会有非凡之力，宁愿认为自己还没醒来。"] = "Да, но ты не выглядишь удивленным. Мои предыдущие клиенты, даже сразу после сна, не верили в существование Потусторонних сил, предпочитая думать, что они еще не проснулись.",
    ["对，你猜的很对，非常准确。"] = "Да, вы правильно угадали, очень точно.",
    ["对，她在引导特莉丝的晋升，以及制造这些惨案。"] = "Да, она руководит продвижением Трисси и организует эти трагедии.",
    ["对，我不是迪伦，我必须让我的意识稳定下来……"] = "Да, я не Дилан, я должен стабилизировать своё сознание...",
    ["对，我担心<P_Yellow>密修会</>不肯放弃，一直在盯着瑞尔·比伯的家，然后跟着我们过来，准备在关键时刻捣乱。"] = "Да, я беспокоюсь, что член Школы мысли <P_Yellow>Rose, </>, не сдастся, наблюдал за домом Рэя Бибера и последовал за нами сюда, готовясь создать проблемы в критический момент.",
    ["对，那是我曾经工作的地方。"] = "Да, там я раньше работал.",
    ["寻欢场所……可你还是个孩子？！"] = "Место для утех… А ты ведь ещё ребёнок?!",
    ["寻租房屋"] = "Поиск жилья в аренду",
    ["导师，你怎么在这里？"] = "Наставник, как вы здесь оказались?",
    ["封印物……是什么意思？"] = "Запечатанный Артефакт... что это значит?",
    ["封印物也会导致非凡者失控？"] = "Могут ли запечатанные артефакты также привести к тому, что Потусторонние потеряют контроль?",
    ["封印物？"] = "Запечатанный артефакт?",
    ["将近一个小时？为什么不乘坐马车？"] = "Почти целый час? Почему бы не взять экипаж?",
    ["尊敬的“愚者”先生，您的力量超越了我的想象，目前我没有其他的乞求。"] = "Уважаемый Мистер Шут, ваша сила превосходит мое воображение. На данный момент других запросов у меня нет.",
    ["尊敬的“愚者”先生，请允许我冒昧恳求，您可以做我们交易的见证吗？"] = "Уважаемый мистер Шут, позвольте мне дерзко просить: не соблаговолите ли вы стать свидетелем нашей сделки?",
    ["小丑"] = "Клоун",
    ["小丑的尸体让弗莱做后续处理，看能不能辨认出他原本的长相，找到有关的线索。"] = "Пусть Фрай займётся телом Клоуна: проверит, удастся ли восстановить его истинный облик и найти зацепки.",
    ["小丑魔药的线索……"] = "Подсказки к зелью Клоуна...",
    ["小克莱恩，你看起来不太，不太开心？"] = "Маленький Кляйн, ты не выглядишь слишком счастливым?",
    ["小女孩：哥哥喊我了！小羊小羊你乖乖在这里睡觉，等我回来再陪你玩。"] = "Маленькая девочка: «Братишка меня позвал! Овечка, овечка, будь хорошей и спи здесь, я снова поиграю с тобой, когда вернусь».",
    ["小女孩：小羊小羊，哥哥说今天要给我过生日，你猜哥哥会给我准备什么礼物？"] = "Маленькая девочка: «Ягненок, ягненок, брат сказал, что собирается отмечать сегодня мой день рождения, угадай, какой подарок брат мне приготовит?»",
    ["小家伙，告诉我，昨晚发生了什么？"] = "Малышка, скажи мне, что произошло прошлой ночью?",
    ["小家伙，还有什么事吗？"] = "Малыш, есть что-нибудь еще?",
    ["小朋友？{{先生|女士}}，这个称呼是对我的贬低。"] = "Маленький ребенок? {{Mr.|Ms.}}, такая форма обращения меня унижает.",
    ["小罗珊，别担心，我们不会死的。"] = "Маленькая Розанна, не волнуйся, мы не умрем.",
    ["小铜镜？我也有一个，为什么我在中央广场时没有消失，还看得见别人消散？"] = "Маленькое медное зеркало? У меня тоже есть. Почему я не исчез, когда был на Центральной площади и видел, как рассеиваются другие?",
    ["小鸟布偶"] = "Кукла-птица",
    ["尝试咒文"] = "Попробуйте заклинание",
    ["尝试表演"] = "Попытаться сыграть",
    ["就像韦尔奇和娜娅那样。"] = "Точно так же, как Уэлч и Найя.",
    ["就在这个时候，她眼前所见霍然破碎，幻觉一样的破碎了。她站在祭坛中，玻璃窗破碎，天空是一轮红月。\n特莉丝瞳孔一缩：我被拖入了梦中？！"] = "В этот момент то, что она увидела, внезапно разбилось, словно иллюзия. Она стояла в алтаре с разбитыми стеклами и красной луной в небе. \nЗрачки Трисс сузились: Меня втянули в сон? !",
    ["就擦破点皮。"] = "Всего несколько царапин.",
    ["就是一切的源头——安提哥努斯家族笔记。"] = "Это первопричина всего — дневник семьи Антигон.",
    ["就算不能，我是说如果，你肯定也能找到更好的工作！"] = "Даже если не сможешь, то есть если, ты обязательно сможешь найти работу получше!",
    ["就这么决定。那么，该先去黑荆棘公司了。"] = "Это решено. Теперь мне следует сначала отправиться в компанию Чёрный Чертополох.",
    ["就这么认为吧。只能从别的途径来寻找<P_Yellow>那本笔记</>了。"] = "Давайте просто предположим это. Мы можем искать <P_Yellow> и ноутбук </> только по другим каналам.",
    ["就这些，还是……你想知道些别的？"] = "Вот и все, или... ты хочешь знать что-то еще?",
    ["就这几张，或许圣堂还有一些，另外就是那些黑市和隐秘组织里可能会有。你以为这很容易搞到？"] = "Только эти несколько страниц. Возможно, в соборе еще есть. Кроме того, их можно найти на черных рынках и в секретных организациях. Вы думаете, это было легко получить?",
    ["就这样吧……"] = "Давайте оставим это...",
    ["就这样喝下去吗？不需要另外的准备？比如仪式或者祈祷？"] = "Стоит ли мне просто пить это так? Никаких других приготовлений не требуется? Как ритуал или молитва?",
    ["就这样喝下去？有什么风险吗？"] = "Просто пить вот так? Есть ли какие-либо риски?",
    ["就这样，先休息吧。等睡醒了我就去……找邓恩先生……"] = "Всё, давай сначала отдохнем. Когда я проснусь, я пойду... к мистеру Данну...",
    ["尼尔先生，你也需要钱吗？"] = "Мистер Нил, вам тоже нужны деньги?",
    ["尼尔先生，你今天的行动很敏捷，而且比我想象的更为冷静。"] = "Мистер Нил, сегодня вы действовали очень проворно и сохраняли куда большее хладнокровие, чем я ожидал.",
    ["尼尔先生，我记得材料可以申请，对吧？"] = "Мистер Нил, я помню, мы можем подать заявку на материалы, верно?",
    ["尼尔先生，那你需要借钱吗？"] = "Мистер Нил, тогда вам нужно одолжить денег?",
    ["尽快消化占卜家魔药、获得晋升，才能应对后续的危机。"] = "Только переварив волшебное зелье прорицателя и как можно скорее получив повышение по службе, вы сможете справиться с последующим кризисом.",
    ["工人们，我知道，大家都很累。机器轰隆响了一天，你们的胳膊早就酸了、麻了。"] = "Рабочие, я знаю, что все очень устали. Машины ревели весь день, а руки уже болят и немеют.",
    ["工作可不能迟到，快去吧。"] = "Не опаздывайте на работу, идите дальше.",
    ["工作的事情总算搞定了。"] = "Рабочий вопрос наконец решен.",
    ["工厂区"] = "Заводской район",
    ["工厂区\n买肉的女佣抬头望向远处的黑烟囱：“这雨下起来没完。”\n黑烟囱下，工人们抹了抹脸上的雨，继续劳作。\n街上的行人纷纷打起了伞。"] = "Заводской район\nГорничная, покупавшая мясо, подняла взгляд на далекие черные трубы: «И когда только прекратится этот проклятый дождь...»\nПод черными заводскими трубами рабочие утирали с лиц капли дождя и продолжали гнуть спины.\nПрохожие на улицах один за другим раскрывали зонты.",
    ["工厂区，女佣抬头望向远处黑烟，骂骂咧咧。\n女佣：糟糕的天气总是没完没了。\n镜头从黑烟冲下移，是许多劳作的工人。"] = "На территории фабрики горничная посмотрела на черный дым вдалеке и выругалась. \nГорничная: Плохая погода никогда не кончается. \nКамера показывает черный дым, показывая, как много рабочих усердно работают.",
    ["左边……才是我的一部分自我意识？"] = "Левая сторона… и есть часть моего самосознания?",
    ["左边那杯"] = "Чашка слева",
    ["巨额债务"] = "Огромный долг",
    ["差一点，但幸好没事。"] = "Почти, но, к счастью, все в порядке.",
    ["差点忘了！"] = "Чуть не забыл!",
    ["差点忘了，之前艾略特绑架案的酬金已经送来，你可以找奥利安娜太太领取10镑。"] = "Чуть не забыл, прибыло вознаграждение за предыдущее дело о похищении Эллиота; вы можете пойти к миссис Орианне и забрать 10 фунтов.",
    ["已经是个合格的值夜者了。看来状态还不错，比我想象得好。"] = "Ты уже квалифицированный Ночной Ястреб. Кажется, твое состояние неплохое, лучше, чем я себе представлял.",
    ["已经没有了"] = "Ничего не осталось",
    ["希望如此"] = "Будем надеяться",
    ["帮大忙了……我刚才手抖了一下……我自己的药……全撒了……"] = "Это огромная помощь... Раньше у меня тряслись руки... Все мое собственное зелье... пролилось...",
    ["帮忙外送"] = "Помощь с доставкой",
    ["常常长短"] = "Длинный-длинный-длинный-короткий",
    ["年轻人，不要犹豫，越犹豫就越紧张，越紧张就越影响魔药的吸收。"] = "Молодой человек, не стесняйтесь. Чем больше вы будете колебаться, тем больше вы будете нервничать, а чем больше вы будете нервничать, тем больше это повлияет на усвоение зелья.",
    ["年轻人，恭喜你，摆脱了过去的阴影，即将迎来充满阳光的新旅程！"] = "Молодой человек, поздравляю с избавлением от теней прошлого и началом нового путешествия, полного солнечного света!",
    ["幸亏{{PlayerName}}你及时赶到才对！一开始，没有这么多怪物，我们聚在一起寻找逃出去的办法。"] = "Это благодаря вовремя пришедшему {{PlayerName}}! Поначалу монстров было не так много; мы собрались вместе, чтобы найти способ сбежать.",
    ["幸好冰淇淋一直在预警！我身份的错位也是邮差恶作剧的一部分？！"] = "К счастью, Мороженое всё время предупреждало! Подмена моей личности — тоже часть шутки почтальона?!",
    ["幸好有这位先生，帮我抢救行李。"] = "К счастью, этот господин помог мне спасти багаж.",
    ["幸运儿会重获新生——"] = "Счастливчики возродятся —",
    ["幸运儿？我？"] = "Счастливчик? Мне?",
    ["床硬邦邦的，有点不太习惯。"] = "Кровать твердая, как камень; Я не совсем к этому привык.",
    ["库克无意识地跌落在地。"] = "Кук без сознания падает на землю.",
    ["应当通过值夜者组织获得“小丑”魔药。【接占卜玩法】"] = "Зелье «Джокер» следует получить через Ночных ястребов. 【Как играть в гадание】",
    ["应该又是邮差的恶作剧，我必须赶紧找到——"] = "Наверняка снова шутки почтальона, нужно скорее найти...",
    ["应该就这几天了，真是一次漫长又辛苦的出差。"] = "Это должны быть эти несколько дней, какая долгая и тяжелая командировка.",
    ["应该是……"] = "Это должно быть...",
    ["应该经历了很多事吧？"] = "Ты, наверное, через многое прошел, да?",
    ["废弃"] = "Заброшенный",
    ["废弃可用"] = "Заброшенный, но пригодный для использования",
    ["廷根全景\n镜头拉升，展示廷根全景。\n场景特效字：鲁恩王国 廷根市"] = "Панорама Тингена\nКамера поднимается, открывая панорамный вид на Тинген.\nТитр на сцене: Королевство Лоэн, город Тинген",
    ["廷根前段时间那批失踪案，你们知道吗？"] = "Вы знаете о той череде пропаж людей в Тингене некоторое время назад?",
    ["廷根大学的讲师面试就在今天，虽然已经决定加入值夜者，但还是要去一趟学校，取消面试。"] = "Сегодня состоится собеседование с преподавателем Университета Тинген. Хоть я и решил присоединиться к «Ночным ястребам», мне все равно нужно пойти в университет, чтобы отменить собеседование.",
    ["廷根对你来说还太陌生，黑荆棘是你暂时的避风港。"] = "Тинген все еще слишком чужой для тебя, Чёрный Чертополох — твое временное убежище.",
    ["廷根市全景\n雨沥沥落下，报时的钟声回荡着。"] = "Панорама города Тинген\nНепрерывно моросит дождь, разносится гулкий бой городских часов.",
    ["廷根正在酝酿危机，这种感觉很不好。"] = "В Тингене назревает кризис, и это ощущение очень плохое.",
    ["廷根的失踪和献祭等离奇案件，或许和失踪的知识皇冠有关？"] = "Могут ли загадочные исчезновения и жертвоприношения в Тингене быть связаны с пропавшей Короной Знаний?",
    ["廷根近期出现大量的异常案件，到底与哪件事情有关呢？"] = "В последнее время у Тингена зарегистрировано большое количество аномальных случаев. С каким из них это связано?",
    ["廷根近期的献祭和邪神案件，都和这个组织的活动有关。"] = "Недавние жертвоприношения и дела злых богов в Тингене связаны с деятельностью этой организации.",
    ["开启窥秘"] = "Активировать секретный просмотр",
    ["开始下雨，工人们抹了抹脸上的雨，继续工作。\n监工：还有几批货，搬不完都别停工！\n镜头快移，另一个场景，街上许多行人撑起伞。一辆马车飞驰而过，溅起许多污水。"] = "Начинается дождь. Рабочие стирают капли с лиц и продолжают трудиться.\nНадсмотрщик: Осталось еще несколько партий товара, пока всё не перетаскаете — никакой передышки!\nКамера быстро смещается: другая сцена, многие прохожие на улице раскрывают зонты. Мимо проносится экипаж, поднимая фонтан грязной жижи.",
    ["开始的梦境是占卜结果，后面的算什么？好像是针对我的？"] = "Первоначальный сон был результатом гадания, а что насчет второй части? Кажется, оно направлено на меня?",
    ["开门"] = "Открытие двери",
    ["异变程度不明，贸然行动的话很危险，先让我们去探一探摸清情况。"] = "Степень мутации неизвестна. Было бы опасно действовать опрометчиво. Давайте сначала пойдем и разведаем это, чтобы получить четкую картину.",
    ["异常情况……警方能帮忙垫付卡尔的房租吗？2苏勒。"] = "Необычные обстоятельства... Сможет ли полиция помочь Карлу оплатить аренду? 8 суле.",
    ["弄好了？"] = "Готово?",
    ["弄清真相"] = "Узнайте правду",
    ["弗兰奇"] = "Фрэнки",
    ["弗兰奇先生很容易被说服，毕竟——"] = "В конце концов, мистера Фрэнки легко убедить…",
    ["弗兰奇先生的智商还是要比卷毛狒狒高一点的，如果他状态良好的话。"] = "Интеллект мистера Фрэнки все еще немного выше, чем у кудрявого павиана, если он в хорошей форме.",
    ["弗兰奇公寓"] = "Квартира Фрэнки",
    ["弗兰奇公寓每周的租金才5苏勒6便士，而班森的周薪才1镑10苏勒，我们需要节省！"] = "Недельная арендная плата за квартиру Фрэнки составляет всего 5 суле и 6 пенсов, а еженедельная зарплата Бенсона — всего 1 фунт 10 суле. Нам нужно спасти!",
    ["弗兰奇敲墙骂你那么多次，只有卡尔帮你说话……他说你站在煤气灯下演戏，像主角一样发着光……"] = "Фрэнки столько раз стучал в стену и ругал тебя, и только Карл заступился... Он сказал, что ты играл под газовым фонарём и сиял, как главный герой...",
    ["弗莱应该回来了。作为新员工，该去见见你的队长了。"] = "Фрай должен вернуться. Как новому сотруднику, вам следует пойти к своему капитану.",
    ["弗莱队长，你呢？也是调查五月庄园吗？"] = "Капитан Фрай, а вы? Тоже расследуете дело поместья Мэй?",
    ["弗莱，你好像不像以前那么沉默了。"] = "Фрай, ты не выглядишь таким молчаливым, как раньше.",
    ["弗莱，我们做好随时进入镜中世界的准备，一定要救出罗珊。"] = "Фрай, мы должны быть готовы войти в зеркальный мир в любой момент, мы должны спасти Розанну.",
    ["弗莱：看来都结束了，绝望魔镜被毁，献祭仪式也被打断……\n弗莱：我们又一次拯救了廷根。\n伦纳德：但这次……我们都活着。"] = "Фрай: Кажется, все позади. Зеркало Отчаяния разбито, кровавый ритуал сорван...\nФрай: Мы вновь спасли Тинген.\nЛеонард: Но на этот раз... мы все выжили.",
    ["弯曲舒展手臂"] = "Сгибать и вытягивать руки",
    ["强装神秘？"] = "Притворяешься загадочным?",
    ["当时他认为我被2-049控制，于是用解救我并给予“占卜家”途径对应的序列8“小丑”来引诱我，让我去拿安提哥努斯笔记。"] = "Тогда он посчитал, что я нахожусь под контролем 2-049, поэтому попытался заманить меня обещанием спасти и передать формулу Последовательности 8 пути «Провидца» — «Клоуна», чтобы я принёс ему дневник семьи Антигон.",
    ["当时没来得及对她进行调查！"] = "Тогда у меня не было времени исследовать ее!",
    ["当海纳斯在占卜俱乐部中初次登场，一切似乎已有预兆。\n这一片历史的迷雾背后，会是什么？"] = "Когда Хейнс дебютировал в Клубе Гадания, казалось, все было предрешено. \nЧто может скрываться за этим туманом истории?",
    ["当然。"] = "Конечно.",
    ["当然不是！公司规定只能在娱乐室里打牌。我们在聊——你这个幸运儿！"] = "Конечно нет! По правилам компании играть в карты разрешено только в комнате отдыха. Мы говорили о тебе — везунчик!",
    ["当然可以，但有点远，而且我一般都步行过去。"] = "Конечно, но это далековато, и я обычно гуляю там.",
    ["当然有，你从楼梯上滚了下来。"] = "Конечно есть, вы скатились по лестнице.",
    ["当然，不是说你服下魔药，就会立即了解并掌握力量，魔药只是让你具备学习这些能力的资格。"] = "Конечно, это не значит, что, выпив зелье, вы сразу поймете и овладеете его силой. Зелье дает вам только возможность изучить эти способности.",
    ["当然，不过我需要观察下你的学习情况，再决定是否引荐你加入我们的内部组织。"] = "Конечно, но мне нужно наблюдать за вашим прогрессом в обучении, прежде чем решить, рекомендовать ли вам присоединиться к нашей внутренней организации.",
    ["当然，也要记得偶尔放松一下。休息好了，才能走得更远。"] = "Конечно, не забывайте время от времени расслабляться. Только хорошо отдохнув, вы сможете идти дальше.",
    ["当然，你也可以选择一直做文职人员，毕竟你已经见到了非凡世界有多危险。"] = "Конечно, вы также можете остаться клерком. Ведь вы уже видели, насколько опасен необыкновенный мир.",
    ["当然，你也可以选择继续积攒功劳，等到它足以让你成为“不眠者”，黑夜教会掌握着它的完整序列。"] = "Конечно, вы также можете продолжать накапливать заслуги, пока их не станет достаточно, чтобы стать «Ночным ястребом». Вечная Церковь сохраняет свою полную последовательность.",
    ["当然，如果你有空，随时可以回来看看。"] = "Конечно, если у вас есть время, вы можете вернуться в гости в любое время.",
    ["当然，如果你正式提出，我现在就能让你回去。"] = "Конечно, если вы официально попросите об этом, я могу отпустить вас прямо сейчас.",
    ["当然，希望下次不要在凶案现场了。"] = "Конечно. Надеюсь только, что в следующий раз мы встретимся не на месте убийства.",
    ["当然，得在我们的能力范围内。"] = "Конечно, это должно быть в пределах наших возможностей.",
    ["当然，晋升的下个序列是——女巫。"] = "Конечно, следующий шаг — ведьма.",
    ["当然，本能的直觉。"] = "Конечно, это инстинктивная интуиция.",
    ["当然，这么多年，我们多少有点默契，但是……"] = "Конечно, на протяжении стольких лет у нас было некое молчаливое взаимопонимание, но...",
    ["当然，这种事情最好还是不要告诉上面的人，那些家伙都古板而保守，总认为我们这种特殊的人必然会受到邪神恶魔的引诱而堕落。"] = "Разумеется, об этом лучше не докладывать начальству: те типы упрямы и консервативны, они свято уверены, что такие особенные люди, как мы, непременно поддадутся искушению злых богов или демонов и падут.",
    ["当绯红降临，这里的所有人都会成为生命的养料。"] = "Когда наступит багрянец, каждый здесь станет пищей для жизни.",
    ["待会儿你先去找<P_Yellow>老尼尔</>，让他给你安排文献阅读的工作，毕竟你是历史方面的专业人士。"] = "Позже сходи к <P_Yellow>старому Нилу</>, пусть он подберёт для тебя материалы для чтения — в конце концов, ты специалист по истории.",
    ["很厉害啊，我的呢？"] = "Это потрясающе. Где мой?",
    ["很可能是邮差在暗中操纵这一切。怎样才能找到他，让一切恢复正常？"] = "Скорее всего, всем этим тайно управляет почтальон. Как найти его и всё вернуть в норму?",
    ["很吓人"] = "Очень страшно",
    ["很多人生活很艰难，我想试试能不能争取一点补偿。"] = "Многим людям приходится нелегко, и я хочу посмотреть, смогу ли я побороться за какую-то компенсацию.",
    ["很好。如果战斗需要用到符咒，只要诵念咒文，灌注灵性后在三秒内丢向目标就可以了。"] = "Очень хороший. Если вам нужно использовать заклинание в бою, просто произнесите заклинание, наполните его духовностью и бросьте в цель в течение трех секунд.",
    ["很好。时间差不多了，该前往灰雾之上了。"] = "Очень хорошо. Пришло время; Я должен подняться над серым туманом.",
    ["很好！看来你已经成功开启旅行尖碑。"] = "Отлично! Похоже, вам удалось активировать обелиск странствий.",
    ["很好，等圣堂批复下来，你就是我们的一员了，咳咳。"] = "Очень хороший. Как только Святой Собор одобрит, ты станешь одним из нас. *Кашель, кашель.*",
    ["很好，除了老实人报，其他都快卖完了。"] = "Ну, кроме «Честной газеты», все остальное почти распродано.",
    ["很对劲，这是罗塞尔大帝最著名的诗歌！"] = "Это очень правильно; это самое знаменитое стихотворение императора Розеллы!",
    ["很想和你再聊一会，但我要去替换队长值班了，再见。"] = "Я бы с удовольствием пообщался с вами еще, но мне пора заменить дежурного капитана. До свидания.",
    ["很抱歉，市场不接待陌生人。"] = "Прошу прощения, на рынок не пускают чужаков.",
    ["很抱歉，韦尔奇昨天过世了，娜娅女士也是。"] = "Мне очень жаль, Уэлч скончался вчера, как и г-жа Найя.",
    ["很有趣"] = "Очень интересно",
    ["很简单，我教你，握紧这把银质匕首。"] = "Это очень просто, я тебя научу, крепко держи этот серебряный кинжал.",
    ["很精神，来，转两圈给我看看。"] = "Очень энергичный. Давай, повернись и дай мне посмотреть.",
    ["很聪明。他在跟踪你的过程中突然失控，精神发狂，身体也异变成了怪物。"] = "Очень умный. Он внезапно потерял контроль, выслеживая вас, его разум сошёл с ума, а тело превратилось в монстра.",
    ["很赚对不对？我们也想赚，所以才要买你的票。"] = "Очень выгодно, правда? Мы тоже хотим заработать денег, поэтому нам придется купить вам билеты.",
    ["很高兴我们达成共识。"] = "Я рад, что мы пришли к консенсусу.",
    ["得再试试那个仪式，说不定就能回去了，我记得……需要食物作为仪式的媒介。"] = "Мне придется повторить этот ритуал еще раз. Может быть, я смогу вернуться. Я помню... для ритуала ему нужна еда как средство.",
    ["得到了肯定的答案。回去先在队长那里做一些铺垫，比如说每次去占卜俱乐部后都感受灵性活泼，再随意描述从占卜中总结出来的守则……"] = "Я получил положительный ответ. Я вернусь и заложу кое-какую основу вместе с Капитаном, например, опишу, как моя духовность оживает после каждого посещения Клуба Гадания, а затем вскользь опишу правила, обобщенные из гадания...",
    ["必须快点找到罗珊。"] = "Нужно быстро найти Розанну.",
    ["忍痛回忆"] = "Вспомнить больно",
    ["快两年了，终于成功了，“愚者”先生允诺的奇迹终于实现了！"] = "Прошло почти два года, и наконец-то успех. Чудо, обещанное господином Шутом, наконец-то свершилось!",
    ["快五年了，伦纳德，我们多少都有些改变。"] = "Прошло почти пять лет, Леонард. Мы все немного изменились.",
    ["快回去！你只是一个驯兽师！"] = "Возвращайся скорее! Вы просто тренер!",
    ["快来，来品尝你哥哥我的厨艺。"] = "Приходите, приходите попробовать стряпню вашего брата.",
    ["快速前往"] = "Иди быстро",
    ["快！你们先进去。"] = "Быстрый! Ты зайди первым.",
    ["忽然一道道深红光芒落下，在不同座位上腾起，变成了一个个面目模糊的人。"] = "Внезапно спускаются лучи малинового света, поднимаясь с разных мест и превращаясь в людей с размытыми лицами.",
    ["怀表坏了"] = "Карманные часы сломаны",
    ["怀表？还是坏的，好像……这是父亲留下的最值钱的东西。"] = "_\n\nКарманные часы? Он, кажется, до сих пор сломан... Это самое ценное, что осталось от отца.",
    ["怎、怎么样？"] = "Х-как дела?",
    ["怎么了"] = "В чем дело?",
    ["怎么了，克莱恩？"] = "Что случилось, Кляйн?",
    ["怎么了，安洁莉卡。"] = "Что случилось, Анжелика?",
    ["怎么了？"] = "В чем дело?",
    ["怎么了？担心即将到来的工作？"] = "В чем дело? Беспокоитесь о предстоящей работе?",
    ["怎么会……阿廖莎……里奇呢？"] = "Как мог... Алеша... где Ричи?",
    ["怎么会这样？"] = "Как это могло произойти?",
    ["怎么办？我总不能一直待在这里吧，队长他们还在现实，不知道那个小丑还会做什么。"] = "Что я должен делать? Я не могу оставаться здесь навсегда. Капитан и остальные все еще в реальности, и я не знаю, что этот Клоун будет делать дальше.",
    ["怎么感觉……还不如邮差骑的那辆新呢？"] = "Почему он кажется... даже не таким новым, как тот, на котором ездит почтальон?",
    ["怎么有这么好的工作……对了，您要买报纸吗？"] = "Как может быть такая хорошая работа... Кстати, не хочешь купить газету?",
    ["怎么样了？"] = "Как это?",
    ["怎么样？"] = "Как это?",
    ["怎么样？刚才看起来很危险？"] = "Как это? Только что это выглядело очень опасно?",
    ["怎么样？没问题就在合同上签字吧。"] = "Как насчет этого? Если проблем нет, подпишите договор.",
    ["怎么样？看了这么久，有兴趣吗？"] = "Как это? После столь долгого просмотра вам интересно?",
    ["怎么看都是一只乌龟啊……"] = "С какой стороны ни посмотри, оно похоже на черепаху...",
    ["怎么进来个路人？这也是策划的小巧思？"] = "Откуда тут взялся прохожий? Это тоже хитрая задумка разработчиков?",
    ["怎么，警察得罪你了？"] = "Что, полиция тебя чем-то обидела?",
    ["怎样扮演"] = "Как действовать",
    ["思考"] = "Думать",
    ["思考办法"] = "Подумайте о способе",
    ["总之，我们只窃取了芬奇和迪伦一瞬间的念头，命运是由他们自己践行的。"] = "Как бы то ни было, мы лишь украли у Финча и Дилана мимолётную мысль, а судьбу они прошли сами.",
    ["总感觉你很害怕，为什么？"] = "У меня такое ощущение, что ты очень напуган, почему?",
    ["恐怖的威胁，绯红的希冀！起码一事是真：此生飞逝。一事是真啊，其余皆谎，花开一度后将与世长辞……"] = "Ужасающие угрозы, багряные надежды! По крайней мере одно верно: эта жизнь пролетает незаметно. Одно правда, остальное ложь, цветок, однажды распустившийся, навсегда умирает...",
    ["恐怖的方式？"] = "Каким-то жутким способом?",
    ["恐惧"] = "Ужас",
    ["恭喜你，“正义”小姐，你是一位非凡者了。"] = "Поздравляю, мисс Справедливость. Теперь ты Потусторонний.",
    ["恭喜你，安娜小姐，乔伊斯·迈尔先生正在你家做客，如果你立刻赶回去，应该还能遇上他。"] = "Поздравляю, мисс Анна, мистер Джойс Мейер посещает ваш дом. Если вы сейчас броситесь назад, вы все равно сможете его поймать.",
    ["恭喜你，成功重历了一次我的历史，感觉怎么样？"] = "Поздравляю, тебе удалось заново пережить фрагмент моей истории. Каковы ощущения?",
    ["恭喜你，新的非凡者，我们的占卜家。"] = "Поздравляю, новый Потусторонний, наш Провидец.",
    ["恭喜你，真是个有礼貌的年轻人，我会通知教授先生和资深副教授们的。"] = "Поздравляю, вы на редкость вежливый молодой человек. Я извещу господина профессора и старших доцентов.",
    ["恭喜，你刚才已经加入阿蒙家族了。"] = "Поздравляю, вы только что вступили в семью Амона.",
    ["悄悄开启灵视"] = "Тихо активируйте духовное зрение",
    ["您之前说的非凡者和非凡能力是什么？"] = "Каковы были Потусторонние и Потусторонние силы, о которых вы упоминали ранее?",
    ["您今天来是要占卜，还是加入俱乐部？"] = "Вы сегодня пришли погадать или вступить в клуб?",
    ["您再看看这剪裁和布料，看看这位先生穿上后多有风度。这样吧，我再给您一个折扣，8镑！"] = "Посмотрите на пошив и ткань, посмотрите, как изящно выглядит в этом джентльмен. Как насчет этого, я дам тебе скидку, 8 фунтов!",
    ["您刚才的善举，守护了一位罗塞尔大帝的崇拜者。"] = "Ваш недавний добрый поступок уберег почитателя Императора Розеля.",
    ["您刚才说……“愚者”先生也曾生活在廷根市？"] = "Ты только что сказал... Мистер Шут тоже жил в Тингене?",
    ["您可以在大厅休息，等待下一位需要占卜的顾客。我会为您准备一杯锡伯红茶。"] = "Вы можете отдохнуть в зале и дождаться следующего клиента, которому необходимо гадание. Я приготовлю для вас чашку черного чая Сибе.",
    ["您听说过这本笔记吗？"] = "Слышали ли вы об этом блокноте?",
    ["您好，我是克莱恩·莫雷蒂，霍伊大学科恩资深副教授的学生。"] = "Здравствуйте, я Клейн Моретти, студент старшего доцента Коэна из Университета Хой.",
    ["您好，斯林太太，我来调查珍妮失踪案。"] = "Здравствуйте, миссис Слин, я расследую исчезновение Дженни.",
    ["您好，请问您是……"] = "Здравствуйте, могу ли я спросить, кто вы...",
    ["您好？抱歉，打断一下，你找我是有什么事吗？"] = "Здравствуйте? Прошу прощения, что отвлекаю, но у вас ко мне какое-то дело?",
    ["您守护了我们。"] = "Ты защитил нас.",
    ["您是“愚者”先生，来自塔罗牌。那作为一个定期的、长期的、隐秘的“聚会”，称号得尽量一致……"] = "Вы Мистер Шут, с карт Таро. Поскольку это регулярное, долгосрочное и секретное «сборище», названия должны быть последовательными...",
    ["您是一位序列1的天使？！"] = "Вы Ангел Последовательности 1?!",
    ["您是神灵？"] = "Ты бог?",
    ["您是第二个找我签名的人，谢谢！祝我好运！"] = "Вы второй, кто просит у меня автограф, спасибо! Пожелайте мне удачи!",
    ["您是说，让我上台去打一场拳击赛？"] = "Вы хотите сказать, что хотите, чтобы я вышел на сцену и провел боксерский поединок?",
    ["您是金玫瑰最芬芳的鲜花，罗塞尔大帝也会拜倒在您的裙摆下，求您行行好吧！"] = "Вы самый благоуханный цветок Золотой розы, даже великий Руасель склонился бы к подолу вашего платья. Умоляю, сжальтесь!",
    ["您最奇怪"] = "Ты самый странный",
    ["您的占卜结果很准确，凡森特先生因突发心脏病，永远离开了我们。"] = "Результат вашего гадания очень точен. Мистер Винсент навсегда покинул нас из-за внезапного сердечного приступа.",
    ["您的父亲……是罗塞尔大帝？难道您就是……"] = "Твой отец... император Розель? Может быть, ты...",
    ["您的眼光真不错，这件衣服裁剪利落大方，设计低调沉稳，适合各种场合。"] = "У тебя отличный глаз. Этот наряд аккуратно скроен, имеет сдержанный и строгий дизайн и подойдет для любого случая.",
    ["您真是一位严谨的绅士，期待我们下次见面。"] = "Вы действительно благоразумный джентльмен. Я с нетерпением жду нашей следующей встречи.",
    ["您真的是一位慷慨的先生、尊贵的存在。"] = "Вы действительно щедрый джентльмен и ведете благородную жизнь.",
    ["您知道如何唤醒大帝在这里的意志吗？"] = "Знаешь ли ты, как пробудить здесь волю Императора?",
    ["您知道如何摧毁这面屏障吗？我们想摧毁镜子，阻止献祭。"] = "Знаете ли вы, как разрушить этот барьер? Мы хотим уничтожить зеркало и остановить жертвоприношение.",
    ["您知道的，我喜欢探索历史，而不是总结历史。"] = "Знаете, мне нравится исследовать историю, а не обобщать ее.",
    ["您需要填写详细资料，缴纳会员年费。初次需要缴纳5镑，之后每年1镑。"] = "Вам необходимо заполнить анкету и внести ежегодный членский взнос. Первый взнос составляет 5 фунтов, а затем — по 1 фунту в год.",
    ["惨案之后，我一直在做同样的噩梦，梦到苜蓿号前一秒还是正常的，突然爆发了冲突，就像恶魔附身一般。莫雷蒂先生，您可以解梦吗？"] = "После трагедии меня мучает один и тот же кошмар. Мне снится, что Клевер одну секунду был нормальным, а потом внезапно вспыхнул конфликт, как будто им овладели демоны. Господин Моретти, можете ли вы истолковать этот сон?",
    ["想想办法"] = "Подумайте о способе",
    ["想找我吗？快来大厅，恶作剧快落幕了。"] = "Ищешь меня? Скорее в зал, шутка вот-вот закончится.",
    ["想更换菜品随时找我，不打扰你执行任务啦。"] = "Если захочешь сменить посуду, найди меня в любое время. Я не буду мешать вам выполнять вашу миссию.",
    ["想清楚了"] = "Продумал это",
    ["想被唤醒吗？只要你答应我一件事情，你就可以得到解放。"] = "Хочешь пробудиться? Если согласишься выполнить для меня одну вещь, ты обретешь свободу.",
    ["想起记忆"] = "Вспомнить воспоминания",
    ["想，我很想"] = "Да, я действительно хочу",
    ["意外？怎样的意外？！"] = "Несчастный случай? Какой ещё несчастный случай?!",
    ["愚者……<P_Heart>（从未听说过的名号，但似乎隐含着可怕的隐秘与力量……不能再试探了，这太危险！）</>"] = "Шут... <P_Heart>(Название, о котором я никогда не слышал, но, кажется, оно подразумевает ужасающие секреты и силу... Я не могу исследовать дальше, это слишком опасно!) </>",
    ["愚者……所有可能的开始，所有未知的集合，所有旅程的起点。"] = "Шут... начало всех возможностей, совокупность всего неизвестного, отправная точка всех путешествий.",
    ["愚者。"] = "Шут.",
    ["愚者牌……您的称呼就来源于这张塔罗牌吗？"] = "Карта «Шут»… ваш титул происходит от этой карты Таро?",
    ["愚者金币"] = "Золотая монета Шута",
    ["愚者，太棒了……我的意思是，或许我们也该给自己取个代号，方便称呼？"] = "Шут, это здорово... В смысле, может, нам тоже для удобства кодовые имена дать?",
    ["愚者，所有可能的开始，所有未知的集合，所有旅程的起点。"] = "Шут, начало всех возможностей, совокупность всего неизвестного, отправная точка всех путешествий.",
    ["感觉今天发生了很多事情……"] = "Такое ощущение, что сегодня многое произошло...",
    ["感觉好多了，谢谢你，弗莱。"] = "Я чувствую себя намного лучше. Спасибо, Фрай.",
    ["感觉好多了，谢谢队长。"] = "Чувствую себя гораздо лучше, спасибо, капитан.",
    ["感觉怎么样？平静下来了吗？"] = "Как вы себя чувствуете? Вы успокоились?",
    ["感觉最近发生了很多事情……"] = "Кажется, в последнее время столько всего произошло...",
    ["感谢“正义”小姐的馈赠，也谢谢你，苏茜。"] = "Благодарю за щедрый дар мисс Справедливость, и спасибо тебе, Сьюзи.",
    ["感谢你的帮助。对了，你为什么称呼我新同事？"] = "Спасибо за помощь. Кстати, почему ты назвал меня новым коллегой?",
    ["感谢对我客人的照顾。她给了我小费，我也理应给你小费。"] = "Спасибо за заботу о моих гостях. Она дала мне чаевые, значит, я должен дать чаевые и тебе.",
    ["感谢您对安娜的指点，她一直都在称赞您的神奇，几乎停不了嘴。"] = "Спасибо за помощь Анне, она восхваляет ваше волшебство и почти не может перестать говорить.",
    ["感谢您的帮助，{{先生|女士}}。您没有受伤吧？"] = "Спасибо за помощь, {{Mr.|Ms.}}. Ты не ранен, не так ли?",
    ["感谢您的惠顾，祝您度过愉快的一天。"] = "Спасибо за ваше покровительство и приятного дня.",
    ["感谢您，弗兰奇先生。<P_Heart>（班森是怎么说服这抠门房东的？）</>"] = "Спасибо, мистер Фрэнки. <P_Heart>(Как Бенсону удалось убедить этого скупого домовладельца?)</>",
    ["感谢惠顾，本店设计高端、用料讲究、价格实惠，欢迎下次再来。"] = "Спасибо за ваше покровительство. В нашем магазине представлены качественные модели, качественные материалы и доступные цены. Мы с нетерпением ждем встречи с вами снова.",
    ["愿女神护佑他的灵魂得到安宁……你画得真好。"] = "Пусть Богиня защитит его душу и дарует ему мир... Ты очень хорошо рисуешь.",
    ["慈善医疗虽然是免费的……但要花费一天时间……算了，今天不干活，明天就没饭吃了……"] = "Хотя благотворительная медицинская помощь бесплатна... она занимает целый день... забудь, если я не буду работать сегодня, завтра мне не будет еды...",
    ["慢慢欣赏"] = "Наслаждаться не спеша",
    ["戏剧节散发铜镜，幕后有人操纵，我让洛耀和西迦去搜集和销毁这批铜镜了。"] = "Медные зеркала раздавали на театральном фестивале под чьим-то тайным управлением. Я поручил Лояо и Сике собрать и уничтожить эту партию зеркал.",
    ["成为非凡者？"] = "Стать Потусторонним?",
    ["成功了！谢谢，请问……"] = "Успех! Спасибо, можно спросить...",
    ["我"] = "Мне",
    ["我……"] = "Я...",
    ["我……也是守护者？"] = "Я... тоже Страж?",
    ["我……我刚才……阿蒙他？！"] = "Я... я только что... Амон, он?!",
    ["我……我怎么在这？"] = "Я... почему я здесь?",
    ["我……我打算找什么？肚子好饿……"] = "Я... что я собирался искать? Как же я голоден...",
    ["我……我看见了。他是——<P_Yellow>特里斯</>。"] = "Я... я видел это. Это — <P_Yellow> Трисс </>.",
    ["我、我不想卖，我真的想看罗塞尔大帝的戏剧。"] = "Я, я не хочу его продавать. Я очень хочу посмотреть пьесу императора Розеллы.",
    ["我、我不确定，我想先跟警官确认一下。"] = "Я, я не уверен, я хочу сначала уточнить у офицера.",
    ["我、我再去收集一些材料，这是之前为了克莱恩的面试……"] = "Я, я пойду собирать еще материалы. Это было для интервью Клейн ранее...",
    ["我、我就没必要了……我想先升职加薪，让我们过上更好的生活。"] = "Мне… мне не нужно… Я хочу сначала получить повышение и повышение, чтобы мы могли жить лучше.",
    ["我、我居然还活着……"] = "Я, я вообще-то еще жив...",
    ["我、我是谁？"] = "Я, кто я?",
    ["我、我看到一双手救了我，但最后又突然笑着松开，我看不清他的样子，然后整个人开始急速坠落。"] = "Я видел, как меня спасли пары рук, но, наконец, они внезапно отпустили меня с улыбкой. Я не мог ясно видеть его лицо, а затем все мое тело начало быстро падать.",
    ["我、我等他回家！"] = "Я, я буду ждать, пока он придет домой!",
    ["我、我能做点什么吗？要不要把他们移到隐蔽些的地方……"] = "М-могу я чем-нибудь помочь? Может, перенести их в более укромное место?..",
    ["我、我还有个问题。如果，我是说如果，一只普通动物喝了序列9的魔药，会发生什么事？"] = "Я, у меня есть еще один вопрос. Если (я имею в виду, если бы) обычное животное выпило зелье Последовательности 9, что бы произошло?",
    ["我一定能签下主角合同！"] = "Я обязательно подпишу контракт на главную роль!",
    ["我一直在这里，我只是进入了你的<P_Yellow>梦</>，然后做了必要的引导。"] = "Я всегда был здесь. Я только что ввел ваш <P_Yellow>dream</> и предоставил необходимые рекомендации.",
    ["我不会粗暴地对待你，毕竟你不是敌人，那会让你不太舒服、感觉疼痛，甚至留下后遗症。"] = "Я не буду обращаться с тобой грубо. Ведь ты не враг. Это причинит вам дискомфорт, боль и даже оставит последствия.",
    ["我不希望再过五年，我的周薪还在2镑以下，家里经济支出全靠我的弟弟妹妹。"] = "Я не хочу через пять лет по-прежнему зарабатывать менее 2 фунтов в неделю, а расходы семьи будут полностью зависеть от моих младших брата и сестры.",
    ["我不明白，为什么我的梦里会反复出现他们？"] = "Я не понимаю, почему они постоянно появляются во сне?",
    ["我不是神灵，我只是一个对漫长历史感兴趣的愚者。"] = "Я не бог; Я просто Шут, который интересуется долгой историей.",
    ["我不是迪伦，我不是迪伦，我不是迪伦……"] = "Я не Дилан, я не Дилан, я не Дилан...",
    ["我不相信你们这些穷老鼠，更何况是只酗酒的老年鼠。"] = "Я не верю вам, нищим крысам, а уж тем более старому пьяному крысюку.",
    ["我不知道"] = "Я не знаю",
    ["我不知道……不知道……"] = "Я не знаю... Я не знаю...",
    ["我不记得在韦尔奇家做过什么，也不记得有没有直接造成他和娜娅的死亡。"] = "Я не помню, что я делал в доме Уэлча, и не помню, был ли я непосредственно причиной смерти его и Найи.",
    ["我为什么要帮助你？"] = "Почему я должен вам помогать?",
    ["我也不知道……为什么一定要把笔记给瑞尔·比伯？"] = "Я тоже не знаю... почему его нужно было отдать Рэю Биберу?",
    ["我也做好进入的准备，这样才有机会救出罗珊小姐和失踪者。"] = "Я тоже готов войти: только так у нас будет шанс спасти мисс Розанну и остальных пропавших.",
    ["我也去！"] = "Я тоже пойду!",
    ["我也在尝试。月亮仆从为了更好地控制镜中廷根，利用绝望魔镜封印了我父亲残留的意志，其中最强烈的部分被分割成许多块，封在不同的隐藏空间中。"] = "Я тоже пытаюсь. Чтобы лучше контролировать Тинген в зеркале, Слуги Луны с помощью Зеркала Отчаяния запечатали остаточную волю моего отца, а самые сильные её части разделили на множество осколков и заперли в разных тайных пространствах.",
    ["我也在想这种可能性，但关于“镜中国度”，我们还一无所知。"] = "Я тоже думаю об этой возможности, но мы до сих пор ничего не знаем о «Зеркальном Царстве».",
    ["我也得去完成自己的任务，调查一个和刺客途径有关的封印物。"] = "Мне также нужно выполнить свою собственную задачу — исследовать Запечатанный Артефакт, связанный с путём Ассасина.",
    ["我也想去大剧院看看，你方便带我一起去吗？"] = "Еще я хочу сходить в Большой театр посмотреть. Вам удобно взять меня с собой?",
    ["我也想学习魔镜占卜。"] = "Еще я хочу научиться магическому зеркальному гаданию.",
    ["我也是这样的。"] = "Я такой же.",
    ["我也是这样的态度。"] = "Я разделяю такое же отношение.",
    ["我也是！"] = "Я тоже!",
    ["我也觉得我足够幸运。"] = "Я тоже считаю, что мне повезло.",
    ["我也许能从他身上发现点什么，准备好了吗？"] = "Возможно, мне удастся что-то разузнать у него. Ты готов?",
    ["我今天轮休，先回房间休息一会。"] = "У меня сегодня выходной, пойду к себе в комнату и немного отдохну.",
    ["我以前就是“占卜家”。"] = "Раньше я был Провидцем.",
    ["我以后也在这里上班了，请多多指教。"] = "С этого момента я буду работать здесь. Пожалуйста, позаботьтесь обо мне.",
    ["我们一周都未必遇上一次委托，而大部分委托的价值在20镑以下。"] = "Мы не получаем комиссионных даже раз в неделю, а большинство комиссионных стоят менее 20 фунтов.",
    ["我们不仅仅是在做一份工作，更是在缔造一个时代！"] = "Мы не просто делаем работу — мы созидаем новую эпоху!",
    ["我们之前在工厂里遇到了危险，是她让我们往外逃的。但我走出来没多久，就遇到了怪物……"] = "Раньше мы сталкивались с опасностью на фабрике, и она позволила нам сбежать. Но вскоре после того, как я вышел, я столкнулся с монстром...",
    ["我们也必须遵从“愚者”先生的意志，反复与之对抗，才有成功的机会。"] = "Мы также должны следовать воле господина Шута и неоднократно противостоять ему, чтобы иметь шанс на успех.",
    ["我们值夜者属于<P_Yellow>黑夜女神教会</>，负责调查和解决廷根市的非凡事件。比如说，这件诡异的自杀案。"] = "Мы, «Ночные ястребы», принадлежим к Церкви <P_Yellow>Богини Вечной Ночи</>, отвечающей за расследование и разрешение чрезвычайных происшествий в Тингене. Например, этот странный случай самоубийства.",
    ["我们再去旁边的济贫院看看，看看两起案件有没有共同之处。"] = "Давайте проверим соседний работный дом и посмотрим, есть ли между этими двумя делами что-то общее.",
    ["我们几个立刻带着遗留物、封印物和安提哥努斯家族笔记返回，并让弗莱、洛耀和警察过来。"] = "Мы немедленно заберем останки, запечатанные артефакты и блокнот семьи Антигона обратно и пригласим Фрая, Ло Яо и полицию.",
    ["我们出发吧，尽快结束，然后将2-049重新封印起来。"] = "Пошли, закончим это как можно скорее, а потом снова запечатаем 2-049.",
    ["我们刚准备继续追查，他就死了？"] = "Он умер как раз в тот момент, когда мы собирались продолжить расследование?",
    ["我们只是让他们的念头变成一枚硬币——正面是“我要反抗”，反面是“放弃幻想”。"] = "Мы лишь превращаем их мысли в монету: на орле — «я хочу сопротивляться», на решке — «оставь иллюзии».",
    ["我们只能从模糊的象征中，引导事情向着好的方向发展，你先想想……"] = "Мы можем направить вещи в правильном направлении только с помощью расплывчатых символов. Ты сначала подумай об этом...",
    ["我们可以去找警察！"] = "Мы можем пойти и найти полицию!",
    ["我们可以去火车站，坐火车离开这里。"] = "Мы можем пойти на вокзал и сесть на поезд, чтобы уехать отсюда.",
    ["我们可以现在就开始，你把材料拿过来吧，就在那边的柜子里。"] = "Мы можем начать прямо сейчас. Принесите ингредиенты; они вон в шкафу.",
    ["我们在咖啡厅见过？你竟然是位厉害的非凡者！"] = "Мы встретились в кафе? На самом деле вы могущественный Потусторонний!",
    ["我们在玩魔镜占卜，赛琳娜懂得很多。"] = "Мы играем в Зеркальное Гадание, Селена знает толк.",
    ["我们工厂成立了夜校，我报名了。明年……也许后年，我就可以去谋求一份打字员的工作。"] = "На нашем заводе открылась вечерняя школа, и я записался. В следующем году... может быть, через год я смогу найти работу машинисткой.",
    ["我们已经知道失踪原因，救出罗珊和失踪者很重要，阻止其他市民失踪也很重要。"] = "Мы уже знаем причину исчезновений. Важно спасти Розанну и пропавших без вести людей, а также предотвратить пропажу других граждан.",
    ["我们得尽快清理下现场。你会布置灵性之墙吗？"] = "Нам нужно как можно скорее очистить место происшествия. Знаете ли вы, как установить Стену Духовности?",
    ["我们必须“扮演”成邀请函上描述的样子，才能潜入城堡内，解决敌人，成为城堡的主人。"] = "Мы должны «действовать» так, как описано в приглашении, чтобы проникнуть в замок, уничтожить врагов и стать хозяином замка.",
    ["我们怀疑你当时带着它离开，但在回家途中将笔记隐藏，所以我们才没能在你身上找到线索。"] = "Мы подозреваем, что вы ушли с ним, но спрятали блокнот по дороге домой, поэтому нам не удалось найти никаких улик на вас.",
    ["我们想进一步了解情况，请你配合。"] = "Мы хотим подробнее разобраться в ситуации, прошу вас посодействовать.",
    ["我们成功地破坏了仪式，但是特莉丝逃走了。"] = "Мы успешно сорвали ритуал, но Трисси сбежала.",
    ["我们挤在破公寓里想过无数次，攒够钱就坐游轮去贝克兰德，看看塔索克河的风景。"] = "Ютясь в убогой квартирке, мы бесчисленное число раз мечтали: накопим денег, сядем на круизный пароход до Бэкланда и посмотрим на пейзажи реки Таскок.",
    ["我们是从廷根市值夜者小队成长起来的同伴……这是一个很长的故事。"] = "Мы товарищи, выросшие в отряде «Тинген Найтхокс»… Это долгая история.",
    ["我们是你父亲请的安保人员，是来救你的，没事了。"] = "Мы сотрудники службы безопасности, нанятые вашим отцом, мы здесь, чтобы спасти вас, теперь все в порядке.",
    ["我们是大学同学，一起跟随科恩资深副教授学习，都是历史系的学生。"] = "Мы были однокурсниками в университете, оба учились у старшего доцента Коэна на историческом факультете.",
    ["我们是守护者"] = "Мы Хранители",
    ["我们是守护者\n也是一群 时刻对抗着危险和疯狂的\n可怜虫"] = "Мы — стражи,\nно в то же время кучка\nжалких глупцов, непрестанно борющихся с опасностью и безумием.",
    ["我们有一些误会，呜呜……"] = "У нас были некоторые недопонимания, рыдание...",
    ["我们本来可以直接抢，但却愿意付你一便士。"] = "Мы могли бы просто ограбить вас, но были готовы заплатить вам копейку.",
    ["我们正在帮助你抵抗污染，终结噩梦，在现实中醒来。"] = "Мы помогаем вам противостоять Искажения, положить конец кошмару и проснуться в реальности.",
    ["我们消灭了失控的安提哥努斯家族后裔，也挫败了密修会的阴谋。在这个过程中，你表现得非常出色。"] = "Мы уничтожили потерявшего контроль потомка семьи Антигон и сорвали заговор Тайного Ордена. В ходе этой операции ты показал себя с наилучшей стороны.",
    ["我们现在只交了定金，需要尽快把钱补上，难得老店主给了我们一个很不错的价格。"] = "Мы только внесли залог, нам нужно как можно скорее внести деньги. Редко когда владелец старого магазина предлагал нам такую ​​хорошую цену.",
    ["我们申请调用了<P_Yellow>封印物2-049</>，这是曾经属于安提哥努斯家族的一件危险物品，能帮助我们定位瑞尔·比伯的位置，只要他是这个家族的后裔。"] = "Мы подали заявку на использование <P_Yellow>Запечатанный артефакт 2-049</>, опасного предмета, который когда-то принадлежал семье Антигона. Это может помочь нам найти Рэя Бибера, при условии, что он потомок этой семьи.",
    ["我们调查发现，失踪的人除了进入镜中世界，还去了五月庄园。"] = "Наше расследование установило, что пропавшие люди не только проникли в зеркальный мир, но и попали в Мэй-Мэнор.",
    ["我们遭遇了海盗后，又突然发生了内讧，所有人像野兽一样，在船上互相厮杀，我的视野里全是血……幸好船上还有一位英雄——"] = "После встречи с пиратами среди нас внезапно вспыхнула междоусобица. Все словно дикие звери бросились резать друг друга прямо на палубе, все вокруг залило кровью... К счастью, на корабле оказался герой —",
    ["我们需要仔细擦拭镜子，必须是镀银的镜子，将它摆在家里象征月亮的位置……"] = "Нужно тщательно протереть зеркало, обязательно посеребрённое, и поставить его в доме на место, символизирующее Луну...",
    ["我们需要先进入房间，阻止献祭仪式。"] = "Сначала нам нужно проникнуть в комнату и остановить ритуал жертвоприношения.",
    ["我们需要其他能力的介入帮忙，我会向贝克兰德申请协助，这需要一些时间。"] = "Нам потребуется помощь иных способностей. Я запрошу содействие из Бэкланда, на это уйдет некоторое время.",
    ["我们需要对尸体做检查，麻烦你先出去等待几分钟。我们会对尸体做一个深入的检查，我想你不会希望看到接下来的画面。"] = "Нам нужно осмотреть тело, поэтому, пожалуйста, подождите несколько минут снаружи. Мы проведем тщательное исследование трупа, и я не думаю, что вам захочется увидеть то, что будет дальше.",
    ["我会反抗"] = "Я буду сопротивляться",
    ["我会听到的。"] = "Я это услышу.",
    ["我会奉献我的灵魂，我会用鲜血取悦您。"] = "Я предложу свою душу и кровью, чтобы доставить тебе удовольствие.",
    ["我会好好保存的。再见，斯林太太。"] = "Я сохраню их в безопасности. До свидания, миссис Слин.",
    ["我会如实描述的。"] = "Я опишу это правдиво.",
    ["我会将今天的事情报告给圣堂，对特莉丝进行通缉，至少她后续无法再光明正大进行祭祀仪式。"] = "Я сообщу о сегодняшних событиях Святому собору и выдам ордер на арест Трисси. По крайней мере, она больше не сможет открыто проводить ритуалы жертвоприношения.",
    ["我会尽快带他们去安全屋避难的，我熟悉廷根的每一条路，不用担心我们。"] = "Я отвезу их в безопасное место в качестве убежища как можно скорее. Я знаю все дороги в Тингене, так что не беспокойся о нас.",
    ["我会抓住机会的！非常感谢您！"] = "Я не упущу шанс! Огромное вам спасибо!",
    ["我会教你的，准备好了吗？"] = "Я научу тебя. Вы готовы?",
    ["我会注意的。"] = "Я буду иметь это в виду.",
    ["我会给你一个地址。至于保证，我想如果有这位神秘阁下的见证，你和我都会足够放心。"] = "Я дам вам адрес. Что касается гарантии, то я думаю, что если мы получим свидетельство этого таинственного Превосходительства, то и вы, и я будем достаточно успокоены.",
    ["我会给你一些香味、足够的温柔和引导，让你一点点放开自己，真正沉浸入那种感受。"] = "Я дам вам немного аромата, достаточно нежности и руководства, чтобы вы могли постепенно раскрыться и по-настоящему погрузиться в это чувство.",
    ["我会进一步调查失踪案，并留意它们是否和知识皇冠有关系。"] = "Я буду и дальше расследовать дела о пропавших без вести людях и следить за тем, имеют ли они отношение к Короне Знаний.",
    ["我假装答应他，并抓住机会把他逼近2-049的影响范围内，然后开枪把他击杀。"] = "Я сделал вид, что согласен, воспользовался возможностью, чтобы заставить его попасть в зону влияния 2-049, а затем застрелил его.",
    ["我做主线的时候在“万都之都”号上见过他，设定是个群演。"] = "Когда я проходил основной сюжет, я видел его на борту «Города чудес», он был задуман как статист.",
    ["我先上去了，前台不能太久没人。"] = "Я сейчас поднимусь; Стойку регистрации нельзя оставлять без присмотра слишком долго.",
    ["我先回去了，前台不能太久没人。"] = "Я возвращаюсь сейчас. Стойку регистрации нельзя оставлять надолго без присмотра.",
    ["我全都清楚了"] = "теперь я все понимаю",
    ["我准备了十年！这是我离主角最近的一次，我要让所有人记住，有个来自廷根，名叫迪伦的演员！"] = "Я готовился десять лет! Это самый близкий к главной роли шанс, и я хочу, чтобы все запомнили: был актер из Тингена по имени Дилан!",
    ["我准备在你身上尝试一个新的仪式魔法了，你这个恶心的小家伙！"] = "Я готовлюсь испробовать на тебе новую Ритуальную Магию, отвратительный маленький парень!",
    ["我准备好了。不错，梅丽莎，这条裙子很适合你。"] = "Я готов. Замечательно, Мелисса, это платье тебе очень идет.",
    ["我准备好了，再次进入历史迷雾。"] = "Я готов снова войти в туман истории.",
    ["我刚从霍伊大学历史系毕业，在努力准备廷根大学讲师的面试，想尽快工作缓解家里拮据的生活。"] = "Я только что окончил исторический факультет Университета Хой и усердно работаю над подготовкой к собеседованию на должность преподавателя в Университете Тинген, надеясь вскоре начать работать, чтобы облегчить финансовое бремя нашей семьи.",
    ["我刚刚补了些提示，你看完就知道如何调查了。"] = "Я просто добавил несколько подсказок; вы узнаете, как провести расследование, как только закончите их читать.",
    ["我刚失业，总不能闲着，不如去五月庄园打份短工。"] = "Я только что потерял работу и не могу просто сидеть сложа руки. С тем же успехом я мог бы поехать в Мэй-Мэнор на краткосрочную работу.",
    ["我刚才追踪管家，拿回了这个。"] = "Раньше я выслеживал Дворецкого и нашел это.",
    ["我刚进门看到海纳斯不在，顺手占卜了下他的情况，没想到得到了遗憾的结果。"] = "Войдя, я увидел, что Хайнаса нет на месте, и мимоходом погадал о нем — никак не ожидал столь прискорбного исхода.",
    ["我去了几次后忙着工作的事就没再去了，昨天警察也来找我调查过。"] = "Я ходил несколько раз, но потом был занят работой и перестал ходить. Вчера полиция также пришла меня расследовать.",
    ["我去看看残留的情况。克莱恩，你把这些药剂带给大家。"] = "Я пойду проверю остатки. Клейн, разнеси всем эти зелья.",
    ["我去过了，警局里没有人……"] = "Я уже был там. В отделении полиции никого нет...",
    ["我发现了两页罗塞尔大帝的日记。"] = "Я нашел две страницы дневника императора Розеля.",
    ["我只是个孩子，但同时也是序列1的水银之蛇，掌握命运和重启的能力。"] = "Я всего лишь ребенок, но также и Ртутная змея Последовательности 1, владеющая силой судьбы и перезапуска.",
    ["我只是在思考你刚刚说的话，似乎得到了一些感悟。"] = "Я просто подумал о том, что вы сказали ранее, и, кажется, у меня появились некоторые идеи.",
    ["我只是将看到的命运告诉她。"] = "Я просто рассказываю ей судьбу, которую видел.",
    ["我只能引导大家先逃去安全屋。"] = "Я могу только помочь всем сначала сбежать в Убежище.",
    ["我叫{{PlayerName}}！能给我在海报上签个名吗？以后你成了大明星，我就能炫耀自己有个明星朋友了。"] = "Меня зовут {{PlayerName}}! Можете расписаться на моём постере? Когда вы станете звездой, я смогу хвастаться, что у меня есть знаменитый друг.",
    ["我叫……克莱恩·莫雷蒂，生活在北大陆鲁恩王国廷根市，我真的穿越了……"] = "Меня зовут... Клейн Моретти, живу в Тингене, Королевство Лоен, Северный континент. Я действительно переселился...",
    ["我叫佛尔思，你也可以称呼我的代号——“魔术师”。"] = "Меня зовут Форс, вы также можете звать меня по кодовому имени — «Маг».",
    ["我叫刻利，是烟草商维克罗尔先生的管家。"] = "Меня зовут Кели, я дворецкий торговца табаком мистера Викрола.",
    ["我叫苏茜，是“正义”小姐的助手。"] = "Меня зовут Сьюзи, я помощница мисс Справедливость.",
    ["我可不是猜的，这是占卜里的<P_Yellow>灵摆法</>，依靠本身星灵体与灵界、星空的联系，借助自然材质与灵性的沟通，来占卜事物的好坏。"] = "Я не угадал, это метод маятника <P_Yellow></> в гадании, основанный на связи между собственным астральным телом, духовным миром и звездным небом и использующий связь между природными материалами и духовностью, чтобы предугадать хорошие или плохие вещи.",
    ["我可以给你一个机会。你想要什么？"] = "Я могу дать тебе шанс. Что ты хочешь?",
    ["我可是资深的值夜者，以前也处理过很多非凡事件，只是现在老了。"] = "Я ветеран Ночной Ястреб; В прошлом я разбирался со многими инцидентами, связанными с Потусторонним, но теперь я просто стар.",
    ["我听伦纳德先生提到过，但还没有尝试。"] = "Я слышал, как мистер Леонард упоминал об этом, но еще не пробовал.",
    ["我听伦纳德先生说过，你在集体潜意识中稳定了所有人的状态。"] = "Я слышал от мистера Леонарда, что вы стабилизировали состояние всех людей в коллективном подсознании.",
    ["我和同事们已经着手调查处置了，但线索还很少。"] = "Мои коллеги и я уже начали расследование и рассмотрение этого вопроса, но улик все еще очень мало.",
    ["我和我的未婚夫曾经梦想着去开一家自己的珠宝店。你看，我做到了，我的店是不是很漂亮？"] = "Мы с женихом когда-то мечтали открыть собственный ювелирный магазин. Смотри, я сделал это. Разве мой магазин не прекрасен?",
    ["我和梅丽莎都不着急，但你正需要这些。"] = "Мы с Мелиссой никуда не торопимся, но это тебе очень нужно.",
    ["我和班森身材差不多，他可以穿我的燕尾服。梅丽莎，你应该买一套新衣服，如果不追求布料和最新的设计并不会太贵。"] = "Мы с Бенсоном примерно одного размера, он может носить мой смокинг. Мелисса, тебе стоит купить новое платье. Если вы не ищете дорогие ткани или новейшие модели, это не будет слишком дорого.",
    ["我和阿兹克来参加一个会议，你找到了什么工作？"] = "Мы с Азиком пришли на одно собрание. А ты какую работу нашел?",
    ["我喊你半天，你头也不回。怎么？以为签了合同，《夜色金玫瑰》的角色就稳了？"] = "Я столько тебя звал, а ты даже не обернулся. Что? Думаешь, раз подписал контракт, роль в «Золотой розе ночи» у тебя в кармане?",
    ["我回家了，班森和梅丽莎还在等我。"] = "Я возвращаюсь домой, меня еще ждут Бенсон и Мелисса.",
    ["我回来啦！"] = "Я вернулся!",
    ["我在一家安保公司工作。"] = "Я работаю в охранной компании.",
    ["我在五月庄园时，见过管家对铜镜念出咒语后消失——以时代的洪流，叩开镜中的国度。"] = "Когда я был в Мэй-Мэноре, я видел, как дворецкий исчез после того, как пропел перед зеркалом заклинание: «Потоком эпохи распахни королевство в зеркале».",
    ["我在调查“五月庄园”的过程中，发现庄园的主人子爵夫人有问题。追踪夫人和她的管家，来到了这里。"] = "В ходе расследования дела «Майского поместья» я заподозрил неладное в отношении его владелицы, госпожи виконтессы. Выслеживая виконтессу и её дворецкого, я и пришёл сюда.",
    ["我在这里听过迪伦的名字？"] = "Я где-то здесь слышал имя Дилана?",
    ["我在雾中听见了女神的颂歌，而我曾看到唱诗班们在教堂附近练习这首歌。"] = "Я слышал гимн Богини в тумане и видел, как хор исполнял эту песню возле церкви.",
    ["我好像来过这里……"] = "Такое ощущение, будто я был здесь раньше...",
    ["我好像穿越了？"] = "Я переселился?",
    ["我完全相信“愚者”先生的公正与强大，我会去寻找鬼鲨的血的。"] = "Я полностью доверяю справедливости и силе  Шута. Я пойду искать кровь Призрачной Акулы.",
    ["我对你的唯一期望，就是别乱加戏。被揍了赶紧倒，别抽搐，别惨叫。观众不关心一个挨揍的混混！"] = "От тебя мне нужно только одно: не импровизируй. Тебя бьют — сразу падай, не дёргайся и не кричи. Зрителю нет дела до избиваемого бандита!",
    ["我对凡人的鲜血和灵魂没有兴趣。不过——"] = "Меня не интересуют кровь и души смертных. Однако-",
    ["我对最近失踪的人进行通灵，都没有成功。我怀疑，近期失踪的人都还活着。"] = "Я пытался применить духовный медиумизм к людям, которые недавно пропали без вести, но никому из них это не удалось. Я подозреваю, что люди, которые недавно пропали без вести, еще живы.",
    ["我对韦尔奇他们的事感到悲痛和遗憾……"] = "Я чувствую печаль и сожаление по поводу того, что случилось с Уэлчем и остальными...",
    ["我就知道你会来接我的，我等了好久好久……"] = "Я знал, что ты придёшь за мной. Я так долго, так долго ждал...",
    ["我尽量避开了怪物……不、他们其实是失踪的市民……但怪物越来越多……"] = "Я изо всех сил старался избегать монстров... Нет, на самом деле им не хватает граждан... но монстров становится все больше и больше...",
    ["我工作后，家里的经济情况也会变好，可以考虑搬家的事情了。"] = "После того, как я начну работать, финансовое положение семьи улучшится, и я смогу подумать о переезде.",
    ["我差点忘记了一件很重要的事情。"] = "Я чуть не забыл кое-что очень важное.",
    ["我已经决定好了，我选……"] = "Я уже решил. Я выбираю...",
    ["我已经卖报一年了，对廷根大事小事都很熟悉！"] = "Я продаю газеты уже год и прекрасно знаком со всеми большими и маленькими событиями в Тингене!",
    ["我已经完成任务，你答应过我，会给我晋升的材料。"] = "Я выполнил задание. Ты обещал дать мне ингредиенты для продвижения.",
    ["我已经将接下来要做的事，在潜意识中告诉你了。"] = "Я уже сказал вам, что делать дальше в вашем подсознании.",
    ["我已经引导一些人去安全屋了，应该没有问题。"] = "Я уже привел некоторых людей в Убежище, проблем быть не должно.",
    ["我已经得到了其他的工作，所以来取消今天的面试。"] = "Я уже нашел другую работу, поэтому пришел отменить сегодняшнее собеседование.",
    ["我已经找到了一份工作，所以来取消今天的面试。"] = "Я уже нашел работу, поэтому хочу отменить сегодняшнее собеседование.",
    ["我已经纠正了她魔镜占卜的错误，事情解决了。"] = "Я исправил ошибку в ее зеркальном гадании, вопрос решен.",
    ["我希望用当时历史事件的日期，与对应日期的日记做对比，从而解读出更多的符号。"] = "Я надеюсь сравнить даты исторических событий того времени с дневниковыми записями соответствующих дат, чтобы расшифровать больше символов.",
    ["我希望能成为一位正式的值夜者。"] = "Я надеюсь стать официальным Ночным Ястребом.",
    ["我并不觉得"] = "Я не думаю",
    ["我并不认为藏着秘密的非凡者就一定是坏蛋，只要你的行为没有危害到我和值夜者，那你就还是我的队友。"] = "Я вовсе не считаю, что Потусторонний, хранящий тайны, обязательно злодей. Пока твои поступки не вредят мне и Ночным Ястребам, ты остаешься моим товарищем по команде.",
    ["我应该怎么再次进入历史迷雾？"] = "Как мне снова войти в туман истории?",
    ["我待会去趟廷根市改善住房公司，新家的事情就交给我和梅丽莎吧。"] = "Я пойду в жилищную компанию Тинген позже. Я оставлю дела нового дома мне и Мелиссе.",
    ["我很好，不用担心，很多人死了，但活着的人还要继续活着。"] = "Я в порядке, не волнуйся. Многие люди погибли, но те, кто жив, должны продолжать жить.",
    ["我得去公司了，工作上有些急事。"] = "Мне нужно идти в компанию, на работе что-то срочное.",
    ["我得去大剧院了。罗塞尔戏剧节正在售票，一定很热闹。"] = "Мне нужно пойти в Большой театр. На фестиваль драмы Розель продаются билеты; это должно быть очень оживленно.",
    ["我必须去追踪“知识皇冠”，防止他进一步活化。摧毁“绝望魔镜”的任务，我想交给你和弗莱。"] = "Я должен выследить «Корону знаний», чтобы предотвратить ее дальнейшее оживление. Я хотел бы поручить задачу уничтожения «Волшебного зеркала отчаяния» вам и Фраю.",
    ["我必须记住自己是谁，记住自己该做什么，不能被迪伦取代……"] = "Я должен помнить, кто я и что должен делать, и не дать Дилану занять моё место...",
    ["我忘记了……"] = "Я забыл...",
    ["我忘记了什么？梦在提醒我什么？"] = "Что я забыл? О чем меня пытается предупредить этот сон?",
    ["我怀疑他来自异世界，就像通俗小说里写的那样！"] = "Подозреваю, что он пришел из другого мира, совсем как в популярных романах!",
    ["我怀疑他达到了序列7，你是怎么办到的？我简直无法相信。"] = "Я подозреваю, что он дошел до седьмой последовательности. Как вам это удалось? Я просто не могу в это поверить.",
    ["我怀疑这本笔记是具备一定生命和智慧的邪恶物品，留在我们手上太危险了。"] = "Я подозреваю, что этот блокнот — злой предмет, обладающий определенной степенью жизни и интеллекта. Слишком опасно держать это в своих руках.",
    ["我怎么忘记了！我怎么能忘记？忘记我的主角梦，又签了这种垃圾合同？！"] = "Как я мог забыть! Как я мог забыть свою мечту о главной роли и подписать такой мусорный контракт?!",
    ["我怎么有个冰淇淋？还是个儿童玩具？"] = "Откуда у меня мороженое? Да ещё и детская игрушка?",
    ["我怕真的与我有关，我不敢赌这个，不如逃跑、去开始新的人生。"] = "Боюсь, это действительно как-то связано со мной. Я не смею делать на это ставку. Лучше сбежать и начать новую жизнь.",
    ["我想了解关于占卜家俱乐部的情况。"] = "Я хотел бы узнать о Клубе Прорицателей.",
    ["我想占卜我未婚夫的状况，他为了一桩生意出海了，至今没有回来。"] = "Я хочу предугадать ситуацию моего жениха. Он уехал в море по деловой сделке и до сих пор не вернулся.",
    ["我想好了，我愿意加入黑荆棘安保公司。"] = "Я решил, что хочу присоединиться к компании Охранная компания «Чёрный Чертополох».",
    ["我想想……"] = "Дай мне подумать...",
    ["我想想……好像有<P_Yellow>“徘徊”、“英灵”、“造物主”、“眷属”</>这几个单词。"] = "Дайте мне подумать... кажется, есть такие слова, как <P_Yellow> «Странствие», «Дух», «Создатель», «Служитель» </>.",
    ["我想成为“太阳”，想从您这里得到初始序列的魔药配方。"] = "Я хочу стать «Солнцем» и получить от тебя начальную формулу зелья последовательности.",
    ["我想知道……"] = "Я хочу знать...",
    ["我想知道，查理最近有没有接触过神秘学物品？"] = "Я хочу знать, контактировал ли Чарли в последнее время с какими-либо оккультными предметами?",
    ["我想起来了！刚才的敌人，是特里斯案件期间、在黑荆棘门口遇见过的少女。"] = "Я вспомнил! Враг, который только что был здесь, — та девушка, которую я встретил у ворот Блэкторна во время дела Трисси.",
    ["我感受到一些熟悉气息的异动，就过来看看。这是对命运的干涉太多了吗……"] = "Я почувствовал колебания знакомых аур и решил взглянуть. Не слишком ли это сильное вмешательство в судьбу...",
    ["我感觉很不错，而且脑袋里似乎多了一些“占卜家”的知识。接下来应该做什么？"] = "Я чувствую себя довольно хорошо, и кажется, в моей голове появилось какое-то «Провидческое» знание. Что мне делать дальше?",
    ["我感觉现在状态不错，我还想学得更多些！"] = "Сейчас я чувствую себя в хорошей форме, хочу учиться дальше!",
    ["我感觉自己睡了一觉……"] = "Такое ощущение, что я вздремнул...",
    ["我感觉还好，我现在就去。"] = "Я чувствую себя хорошо, сейчас пойду.",
    ["我愿意"] = "я готов",
    ["我懂了。"] = "Я понимаю.",
    ["我成为了“占卜家”，也拥有了一些神奇的能力，能在任务中起到一定作用。"] = "Я стал Провидцем, а также обладаю некоторыми магическими способностями, которые могут сыграть определённую роль в миссиях.",
    ["我成为了“占卜家”，也拥有了一些神奇的能力，能在任务中起到一定作用了。"] = "Я стал Провидцем, а также обладаю некоторыми магическими способностями, которые теперь могут сыграть определённую роль в миссиях.",
    ["我打算让{{他|她}}再去廷根逛逛，多了解一下这里。"] = "Я планирую позволить {{him|her}} снова исследовать Тинген и узнать больше об этом месте.",
    ["我把它们都做了标记，放在了这缕信息中。"] = "Я отметил их все и поместил в эту информацию.",
    ["我把它带到卡尔最想乘坐的游轮上，也算和卡尔一起见到了船外的风景吧。"] = "Я взял его на круизный лайнер, на котором Карл мечтал прокатиться больше всего. Считай, мы вместе с Карлом увидели пейзажи за бортом.",
    ["我拿错牌了？这张牌是怎么回事？"] = "Я взял не ту карту? Что происходит с этой картой?",
    ["我早上查了你这个月的材料额度，很遗憾，已经用完了。"] = "Сегодня утром я проверил вашу норму материалов на этот месяц; к сожалению, он уже израсходован.",
    ["我早就不怕了……这里真的很不错，克莱恩，欢迎你的加入。"] = "Давно я не боялся... Здесь действительно хорошо, Клейн. Добро пожаловать в команду.",
    ["我明白。我这次回廷根，就是要和你一起查清真相，守护廷根。"] = "Я понимаю. На этот раз я вернусь в Тинген, чтобы вместе с вами раскрыть правду и охранять Тинген.",
    ["我明白了"] = "Я понимаю",
    ["我明白了。"] = "Я понимаю.",
    ["我明白了。“星星”先生……我该去哪里找他呢？"] = "Я понимаю. Мистер Стар... куда мне идти, чтобы его найти?",
    ["我明白了。谢谢您的朋友，也赞美“愚者”先生。"] = "Я понимаю. Передайте благодарность вашему другу, и да будет славен Господин Шут.",
    ["我明白了。都有什么可以点的？我想试试看。"] = "Я понимаю. Есть ли что-нибудь, что я могу заказать? Я хочу попробовать.",
    ["我明白了，你继续去询问附近的住户，要详细询问。"] = "Я понимаю. Продолжайте допрашивать местных жителей и будьте тщательны.",
    ["我明白了，怪不得刚才这扇门看起来很危险……"] = "Я понимаю, неудивительно, что эта дверь сейчас выглядела такой опасной...",
    ["我明白了，是邮差骑的那种脚踏车吗？"] = "Я понял, это такой велосипед, на котором почтальоны ездят?",
    ["我明白了，那唤醒大帝残存意志的事就让我们来试试吧。"] = "Я понимаю. Что ж, давайте попробуем пробудить остаточную волю императора.",
    ["我明白了，那您可以试试这一套。"] = "Я понимаю, тогда можно попробовать этот набор.",
    ["我明白的，克莱恩，不用给自己太大压力。"] = "Я понимаю, Клейн, не дави на себя слишком сильно.",
    ["我明白的，我只是有些……不知道该怎么办了。"] = "Я понимаю, я просто... Я не знаю, что делать.",
    ["我明白，只要我保守秘密，就不会有其他问题了，对吧？"] = "Я понимаю. Пока я храню секрет, других проблем не будет, верно?",
    ["我明白，可“正义”女士说，您会指引我加入非凡者组织？"] = "Я понимаю, но мисс Джастис сказала, что вы поможете мне присоединиться к организации Потусторонний?",
    ["我明白，弗莱队长，我会小心处理的。"] = "Я понимаю, капитан Фрай, и буду обращаться с этим осторожно.",
    ["我明白，总有一天会攒够的。接下来你要去哪里？"] = "Я понимаю, однажды ты накопишь достаточно. Куда ты собираешься дальше?",
    ["我明白，迎接完新人，我也加入调查。"] = "Я понимаю. Поприветствовав новичка, я присоединяюсь к расследованию.",
    ["我是{{PlayerName}}。我在金玫瑰追捕阿蒙分身，他制造了这场命运乱流……"] = "Я {{PlayerName}}. Я преследую в «Золотой Розе» аватар Амона. Это он устроил этот шторм судьбы...",
    ["我是“通灵者”戴莉，住在恩马特港，这次来协助邓恩的工作。"] = "Я Дэйли, «Медиум». Живу в порту Энмат, а сюда прибыла помочь Дунну в работе.",
    ["我是一个喜欢等价交换的人，不会让你们无条件帮忙。"] = "Я человек, который любит эквивалентный обмен и не позволит вам помочь безоговорочно.",
    ["我是克莱恩·莫雷蒂，就住在附近。"] = "Я Клейн Моретти, я живу неподалеку.",
    ["我是克莱恩·莫雷蒂，来找邓恩先生入职的。"] = "Я Клейн Моретти, я здесь, чтобы найти мистера Данна, чтобы он мог приступить к своей работе.",
    ["我是克莱恩，今天来入职成为文职人员，罗珊小姐让我下楼去找邓恩先生。"] = "Я Клейн. Я пришел сегодня, чтобы приступить к работе в качестве канцелярского сотрудника. Мисс Розанна сказала мне спуститься вниз и найти мистера Данна.",
    ["我是怎么穿越的？我只是个生活在21世纪的普通人，最近除了倒霉点，也没什么特殊啊。"] = "Как я переселился? Я обычный человек, живущий в 21 веке. В последнее время, кроме того, что немного не везет, ничего особенного.",
    ["我是激动，对，激动。"] = "Я взволнован, правда, взволнован.",
    ["我是科恩黎，她是西迦，欢迎你加入我们。"] = "Я Коэн, она Сига, добро пожаловать к нам.",
    ["我是西比尔，您是今天第一位来占卜的人，免费。"] = "Я Сибилла. Вы сегодня первый посетитель на гадание, так что бесплатно.",
    ["我是费伊，我是贝尼？错了！我是科尔顿伯爵！"] = "Я Фэй, я Бенни? Неверно! Я граф Колтон!",
    ["我曾经对你说过，这个世界上有很多特殊的人，比如说你，也比如说我。"] = "Я когда-то говорил тебе, что в этом мире много особенных людей, таких как ты, а также таких, как я.",
    ["我最近在考虑申请一把费内波特琴，吟唱怎么能没有伴奏呢？"] = "Недавно я подумывал о покупке лютни Фейнапоттер. Как может быть чтение без сопровождения?",
    ["我有一个猜测。"] = "У меня есть догадка.",
    ["我有一页。"] = "У меня есть одна страница.",
    ["我有两个名字，一个这具身体的名字。"] = "У меня два имени, одно из них — имя этого тела.",
    ["我有个大胆的想法。"] = "У меня есть смелая мысль.",
    ["我有件事，需要你们的配合。"] = "У меня есть дело, в котором мне потребуется ваша помощь.",
    ["我有携带小艾略特少爷的画像，还有他经常佩戴的风暴护符，可以吗？"] = "У меня есть портрет Молодого Мастера Эллиота и Амулет Шторма, который он часто носит. Хорошо?",
    ["我本想用占卜定位她逃跑的位置，但是占卜受到了干扰。"] = "Я хотел с помощью гадания определить, куда она сбежала, но предсказанию помешали.",
    ["我来帮你"] = "я помогу тебе",
    ["我来猜猜看……死亡的气息浓郁，以祭坛为中心，周围气温比正常要低至少5摄氏度，有阴冷的风……"] = "Дайте угадаю... запах смерти густой, сосредоточен вокруг алтаря, температура вокруг как минимум на 5 градусов ниже обычной, и дует холодный, пронизывающий ветер...",
    ["我没事，刚刚这是？"] = "Я в порядке. Что это было только что?",
    ["我没多想"] = "Я не особо об этом думал",
    ["我没有印象，或许……"] = "У меня нет впечатления, возможно...",
    ["我没问题。不过我们应该给梅丽莎准备一件新衣服。"] = "Меня это устраивает. Но нам следует подготовить новое платье для Мелиссы.",
    ["我演出过很多剧目了，但还是会紧张。尽管演的都是没有台词的小配角……"] = "Я сыграл во многих постановках, но всё равно волнуюсь. Хотя играю лишь маленькие роли без слов...",
    ["我猜测，你跟你的朋友们一样，也经历了一次诡异的自杀。只是因为一些特殊原因，你活了下来。"] = "Полагаю, как и твои друзья, ты тоже совершил загадочное самоубийство. Вот только по какой-то особой причине тебе удалось выжить.",
    ["我现在就过去。"] = "Я перейду прямо сейчас.",
    ["我现在教你冥想，按我说的做。"] = "Сейчас я научу тебя медитации. Делай то, что я скажу.",
    ["我现在有钱了，坐马车去！"] = "У меня теперь есть деньги, я возьму карету!",
    ["我现在能从哪些“序列9”里挑选？"] = "Какую «Sequence 9» я могу выбрать сейчас?",
    ["我用一个形象的事例来说明吧。序列魔药的核心力量是一座城堡，而我们有一张城堡主人给予的邀请函。"] = "Позвольте мне объяснить это на ярком примере. Основная сила зелья последовательности подобна замку, и у нас есть приглашение от владельца замка.",
    ["我用了一些小技巧，来获得我们想知道的答案。但因为一些无聊又严肃的保密协议，我不能告诉你更多。"] = "Я использовал несколько маленьких хитростей, чтобы получить ответы, которые мы хотели. Но из-за каких-то скучных и серьезных соглашений о неразглашении я не могу вам больше рассказать.",
    ["我用学校不要的材料和路上捡到的东西做的，前两天才做好。"] = "Я смастерил это из ненужных материалов из школы и того, что подобрал на улице. Закончил только пару дней назад.",
    ["我的代号是——“正义”！"] = "Моё кодовое имя — Справедливость!",
    ["我的名字"] = "Мое имя",
    ["我的名字是……"] = "Меня зовут...",
    ["我的图纸呢？我的图纸！"] = "Где мои чертежи? Мои чертежи!",
    ["我的想法没有变过，也没有继续晋升序列的打算。"] = "Мои мысли не изменились, и я не собираюсь продолжать продвигаться в Последовательности.",
    ["我的意思是，这个任务由我和你一起完成。我的序列并不擅长找人，但这是“占卜家”的专长。"] = "Я имею в виду, что мы выполним этот квест вместе. Моя Последовательность не очень хороша в поиске людей, но это особенность Провидца.",
    ["我的梦境？"] = "Мой сон?",
    ["我的穿越很可能是因为那个转运仪式……不管怎么样，我都要试一试！"] = "Моё переселение, скорее всего, произошло благодаря этому Ритуалу Обращения Судьбы... в любом случае, я должен попробовать!",
    ["我相信你。"] = "Я верю в тебя.",
    ["我看到了一双纤细白嫩的手，似乎属于一位女士。"] = "Я увидел пару тонких, светлых рук, которые, кажется, принадлежали даме.",
    ["我看到了一条河流，西北面有一个二层的灰蓝色房屋，前面有一个破败的花园……"] = "Я увидел реку, двухэтажный серо-голубой дом на северо-западе и полуразрушенный сад впереди...",
    ["我看过这出戏的演员招募海报，很感兴趣，没想到能见到演员。"] = "Я видел афишу с набором актёров на этот спектакль, она меня заинтересовала. Не думал, что встречу самих актёров.",
    ["我真的没有多想，真的。只是听起来怎么这么、这么……"] = "Я действительно не слишком много думал, правда. Просто это звучит так, так...",
    ["我真的要迟到了，晚上见，克莱恩！"] = "Я правда опоздаю! Увидимся сегодня вечером, Клейн!",
    ["我睡前做了个<P_Yellow>转运仪式</>，从一本地摊上淘来的书里学来的，或许就是因为这个！"] = "Я выполнил ритуал <P_Yellow>, приносящий удачу.</> перед сном, чему научился из книги, которую купил в уличном ларьке. Может быть, поэтому!",
    ["我瞧瞧……来些豌豆、卷心菜、洋葱……再来几个土豆！"] = "Дай-ка посмотреть... Дай мне горошка, капусты, лука... и картошки!",
    ["我瞧瞧……齐了，低序列魔药的配置很简单，不需要特别的火焰或咒语。至少序列7以下是这样的。"] = "Дай-ка гляну... Все на месте. Приготовление зелий низких Последовательностей весьма несложное, оно не требует особого пламени или заклинаний. По крайней мере, для тех, что ниже 7-й Последовательности.",
    ["我知道了。"] = "Я понимаю.",
    ["我知道单纯的语言很难让你相信，你等下进去看到赛琳娜的魔镜就明白了。如果你想拯救你的朋友，需要帮我做一件事。"] = "Я знаю, в это трудно поверить на словах, ты поймешь, как только войдёшь и увидишь волшебное зеркало Селины. Если ты хочешь спасти своего друга, тебе нужно сделать для меня одну вещь.",
    ["我知道她想读机械专业，我先看看她的手稿。"] = "Я знаю, что она хочет изучать машиностроение, позвольте мне сначала просмотреть ее рукописи.",
    ["我知道阿蒙擅长窃取、寄生、欺诈，追求冒险与刺激，身上还带有那位“伟大母亲”的污染和神子命运。"] = "Я знаю, что Амон искусен в краже, паразитизме и обмане, жаждет приключений и острых ощущений, а на нём ещё лежат скверна той «Великой Матери» и судьба дитя бога.",
    ["我知道，但成为值夜者、代罚者或机械之心就会失去自由……没有别的办法了吗？"] = "Я знаю, но стать Ночным Ястребом, Назначенным Карателем или Машинным Коллективным Разумом означает потерять свободу... Неужели нет другого пути?",
    ["我知道，但成为官方非凡者就会失去自由……没有别的办法了吗？"] = "Я знаю, но стать официальным Потусторонним - значит потерять свободу... Неужели нет другого пути?",
    ["我知道，但我尊重内心的声音。"] = "Я знаю, но я уважаю внутренний голос.",
    ["我确实什么都不记得了，戴莉女士的能力也没发现什么。"] = "Я правда ничего не помню, и способности мисс Дейли тоже ничего не открыли.",
    ["我祈求女神的眷顾；"] = "Я молюсь о благосклонности Богини;",
    ["我祈求您的眷顾，祈求您赐予我，进入历史迷雾的许可与祝福……"] = "Я молюсь о твоей милости, я молю тебя, чтобы ты даровал мне разрешение и благословение войти в туман истории...",
    ["我祈求隐秘的力量；"] = "Я молюсь силе Тайны;",
    ["我祈求黑夜的力量；"] = "Я молюсь силе Ночи;",
    ["我突然想起来，为了庆祝，我们还需要梅丽莎喜欢的柠檬蛋糕，当然也少不了姜汁啤酒！"] = "Я вдруг вспомнил, что для праздника нам также понадобится лимонный пирог, который любит Мелисса, и, конечно же, имбирное пиво!",
    ["我累了，你也回去休息吧。"] = "Я устал, ты тоже иди и отдохни.",
    ["我给你带了特制宁静药剂，先喝一口。"] = "Я принёс тебе особое успокаивающее зелье. Сначала сделай глоток.",
    ["我缴完年费后就立刻申请报销。"] = "Я подам заявку на возмещение сразу после оплаты годового взноса.",
    ["我能分多少？"] = "Сколько я получу?",
    ["我能理解。"] = "Я могу понять.",
    ["我能确定莫雷蒂先生是出色的占卜师，他刚刚占卜了一位先生的情况，结果非常准确。"] = "Я могу подтвердить, что мистер Моретти превосходный прорицатель. Он только что прогадал для джентльмена, и результат оказался очень точным.",
    ["我脑子里有迪伦的念头，有迪伦的记忆。但我不是迪伦，我是——"] = "В моей голове мысли Дилана и воспоминания Дилана. Но я не Дилан, я...",
    ["我被卷入一起诡异的事件里，相关的人都离奇自杀，我却死而复活了……真是恐怖。"] = "Я был вовлечен в странный инцидент, в котором все участники странным образом покончили жизнь самоубийством, но я умер и воскрес... Это действительно ужасно.",
    ["我要办点事，想进入地下市场。"] = "У меня есть дела, я хочу выйти на подпольный рынок.",
    ["我要加入你们"] = "Я хочу присоединиться к тебе",
    ["我要去上学了，走去学校要五十分钟。克莱恩，今天只买八磅面包就好。天气热，买太多容易坏掉。"] = "Я иду в школу; прогулка туда займет пятьдесят минут. Клейн, купи сегодня восемь фунтов хлеба. Он горячий и легко портится, если мы купим слишком много.",
    ["我要晋升为女巫？开什么玩笑？"] = "Мне предстоит стать Ведьмой? Ты шутишь?",
    ["我要迟到了！"] = "Я опоздаю!",
    ["我要迟到了！记得买面包，再买一些羔羊肉和豌豆。"] = "Я опоздаю! Не забудьте купить хлеб, а также баранину и горох.",
    ["我认为有必要对海纳斯展开调查。"] = "Я считаю необходимым провести расследование в отношении Хайнса.",
    ["我认为留下这个孩子，会让你以后的人生变得艰难，毕竟他父亲是个诈骗犯。"] = "Я считаю, что сохранение этого ребенка усложнит вашу будущую жизнь; ведь его отец — мошенник.",
    ["我认识他！他是那个赞助商的管家！"] = "Я знаю его! Он дворецкий этого спонсора!",
    ["我认识这个代罚者，他跟随斯维因多年，曾经清理过水鬼、也抓捕过逃走的邪恶非凡者……可如今……"] = "Я знаю этого Карателя. Он следовал за Суэйном много лет, уничтожал водных призраков и ловил сбежавших злых Потусторонних... но теперь...",
    ["我记得……这是一百多年前因蒂斯共和国执政官罗塞尔·古斯塔夫发明的。"] = "Я помню... это придумала Розель Густав, консул Республики Интис, более ста лет назад.",
    ["我记得。其他报纸呢，《塔索克报》《故事评论》？"] = "Я помню. А как насчет других газет, таких как Тасок Times или Story Reviews?",
    ["我记得你，我看过你的推荐信。但有什么事吗？我并不负责面试。"] = "Я помню тебя, я видел твое рекомендательное письмо. Но есть ли что-то не так? Я не отвечаю за собеседования.",
    ["我记得，之前在瑞尔·比伯案件中，燕尾服小丑曾经提过“占卜家”对应的序列8是“小丑”。"] = "Я помню, что в случае с Рэем Бибером Клоун в смокинге упомянул, что Последовательность 8, соответствующая «Провидцу», — это «Клоун».",
    ["我记得，这可不是什么安全的占卜方法，请求未知的存在直接给予答案，占卜者很容易被邪恶力量侵蚀。"] = "Я помню, это не безопасный метод гадания. Попросив неизвестное существо дать ответ напрямую, прорицатель легко подвергается эрозии со стороны злых сил.",
    ["我试试。"] = "Я постараюсь.",
    ["我该回家了……也许他的父亲还会回来，给他留下一笔财富。"] = "Мне пора домой... Быть может, его отец еще вернется и оставит ему целое состояние.",
    ["我说了我们现在只要钱！"] = "Я сказал, что нам нужны только деньги сейчас!",
    ["我负责调查查理失踪案，今天不查违禁物品交易。"] = "Я отвечаю за расследование дела об исчезновении Чарли, я не проверяю сегодня контрабанду.",
    ["我赢了，斯维因先生，是不是可以……"] = "Я выиграл, мистер Суэйн, могу ли я...",
    ["我跟同学韦尔奇、娜娅在一起研究一本第四纪的古老笔记，这很有趣。"] = "Я изучаю древнюю тетрадь Четвертой Эпохи со своими одноклассниками Уэлчем и Найей. Это очень интересно.",
    ["我跟哥哥班森、妹妹梅丽莎一起租住在这间公寓里，这里……是我们的家。"] = "Я снимаю эту квартиру вместе со старшим братом Бенсоном и младшей сестрой Мелиссой. Это... наш дом.",
    ["我身上延伸出的支流不断闪烁，就是他们眼中的我，身份不断变化的原因？"] = "Ответвления, отходящие от меня, непрерывно мерцают. Не в этом ли причина, что в их глазах моя личность постоянно меняется?",
    ["我输了，斯维因先生，但是……"] = "Я проиграл, мистер Суэйн, но...",
    ["我还从迪伦手里得到了一张签名海报……签名海报？刚才那份传单——"] = "Я ещё получил от Дилана плакат с автографом… Плакат с автографом? Тот листок только что…",
    ["我还带了这次拍的新合照，看。"] = "Еще я принес новое групповое фото, которое мы сделали на этот раз, посмотрите.",
    ["我还是不明白……"] = "Я до сих пор не понимаю...",
    ["我还是去五月庄园，调查更多线索，救出那批工人。"] = "Я все равно поеду в Мэй-Мэнор, чтобы найти новые улики и спасти группу рабочих.",
    ["我还是苏茜的好朋友，是……还有些暂时不便透露。"] = "Еще я хороший друг Сьюзи, и... есть некоторые вещи, которые пока неудобно раскрывать.",
    ["我还遇到梦中的皮特兄妹。皮特是月亮仆从的成员，可能在准备仪式。"] = "Я также встретил братьев и сестер Пита из своего сна. Пит — член Лунного Слуги и, возможно, готовится к ритуалу.",
    ["我这有张示意图，随手画的，你看看吧。"] = "У меня тут есть схемка, набросал от руки, взгляните.",
    ["我进来以后，遇到的每个人都不对劲，他们的外形、身份，甚至性别都错位了……"] = "С тех пор как я вошёл, все, кого я встречал, были какими-то неправильными: внешность, личность и даже пол у них перепутаны…",
    ["我选……“倒吊人”。"] = "Я выбираю... «Повешенный».",
    ["我选择了“占卜家”。"] = "Я выбрал «Провидец».",
    ["我选择了“占卜家”，成为了一个非凡者。"] = "Я выбрал «Провидца» и стал Потусторонним.",
    ["我选择，“占卜家”！"] = "Я выбираю «Провидец»!",
    ["我通过占卜找到中央广场，没看到叫珍妮的纺织女工。"] = "Я нашел Центральную площадь посредством гадания, но не увидел текстильщицу по имени Дженни.",
    ["我遇到一位海盗打扮的女士，是她告诉我的……"] = "Я встретил женщину, одетую пираткой; она была той, кто сказал мне...",
    ["我都了解了"] = "я все понимаю",
    ["我都记下了，有什么异常情况，及时向警方报告。"] = "Я все это записал, если будут какие-то необычные обстоятельства, вовремя сообщите о них в полицию.",
    ["我需要你们的帮忙。有个代罚者小队的成员在附近失控了。"] = "Мне нужна ваша помощь. Рядом не справился с управлением член отряда «Каратели».",
    ["我需要在安静的环境里占卜，安娜小姐，请你在外面稍候。"] = "Мне нужна тишина для гадания. Госпожа Анна, подождите, пожалуйста, снаружи.",
    ["我需要小艾略特贴身的某个东西。"] = "Мне нужно что-то личное, принадлежащее Маленькому Эллиоту.",
    ["我需要找回笔记、也需要足够的自保能力，所以我接受邀请加入了黑荆棘安保公司，然后成为了一位非凡者。"] = "Мне нужно найти блокнот, а также мне нужны достаточные способности самозащиты, поэтому я принял приглашение присоединиться к охранной компании Чёрный Чертополох, а затем стал Потусторонним.",
    ["我马上走，马上走。您行行好，再宽限几分钟，我还没讨够饭钱——"] = "Ухожу, сейчас же ухожу. Смилуйтесь, дайте ещё пару минут, я ещё не насобирал на еду…",
    ["我魔药的能力与占卜有关，必须为大量的人占卜，才能加速掌握。所以我打算加入俱乐部，做一个真正的占卜家。"] = "Способности моего зелья связаны с прорицанием, и мне нужно прорицать большое количество людей, чтобы ускорить свое мастерство. Поэтому я планирую вступить в клуб и стать настоящим Провидцем.",
    ["我！我来这里是为了调查邮差，怎么在包间里打牌？！"] = "Я! Я пришёл сюда расследовать дело почтальона, как же я оказался в отдельной комнате за игрой в карты?!",
    ["我，克莱恩·莫雷蒂，已经是一位正式的值夜者了。但还有太多的事情要去了解、去学习。"] = "Я, Клейн Моретти, теперь официальный Ночной Ястреб. Но нам еще многое предстоит понять и изучить.",
    ["我，克莱恩·莫雷蒂，已经是一位正式的值夜者了。我有太多的事情要去了解、去学习。"] = "Я, Клейн Моретти, теперь официальный Ночной Ястреб. Мне нужно слишком многое понять и изучить.",
    ["我？"] = "Мне?",
    ["我？你？"] = "Мне? Ты?",
    ["我？抱歉……我已经有正式工作了。"] = "Мне? Извините... У меня уже есть официальная работа.",
    ["我？！"] = "Мне?!",
    ["或者直接成为非凡者，毕竟我们不是你的保姆，不能整日整夜地看着你。"] = "Или сразу стать Потусторонним. В конце концов, мы тебе не няньки, чтобы присматривать круглыми сутками.",
    ["或许……"] = "Возможно...",
    ["或许他的出生灵数符合要求，也或许他是安提哥努斯家族仅存的后裔，这有太多的可能……"] = "Возможно, духовность его рождения соответствовала требованиям, или, возможно, он последний потомок семьи Антигон. Слишком много возможностей...",
    ["或许做出特别申请，光明正大地成为“小丑”是更好的选择。"] = "Возможно, лучшим выбором будет подать специальное заявление и открыто стать «Клоуном».",
    ["或许可以通过镜子占卜出它曾经映照过的人或事情？"] = "Быть может, через зеркало удастся узнать о людях или событиях, которые в нем когда-то отражались?",
    ["或许因为你身上有被封印的污染，熟悉的气息让知识皇冠把你当成“自己人”。"] = "Возможно, из-за того, что вы наложили на себя порчу, знакомая аура заставила Корону Знаний относиться к вам как к «своему».",
    ["或许是那群绑匪太不幸运，他们只是普通人，却要同时面对两个非凡者。"] = "Возможно, этой группе похитителей просто не повезло. Они были обычными людьми, но им пришлось столкнуться сразу с двумя Потусторонними.",
    ["或许，我是有什么吸引非凡存在的体质吧……"] = "Может быть, у меня какое-то телосложение, привлекающее необыкновенных существ...",
    ["战士途径导师"] = "Преподаватель пути воина",
    ["战斗尾声，你被大量信徒包围，绝望无力地反击。\n危急时刻，伦纳德用赫密斯语吟诵诗歌，阻止仪式。"] = "Под занавес боя вы оказываетесь в окружении толпы культистов, отчаянно и бессильно отбиваясь.\nВ критический миг Леонард декламирует стихи на герметическом языке, срывая ритуал.",
    ["戴莉女士也是值夜者？看得出来你很信任她。"] = "Мисс Дейли тоже из «Ночных Ястребов»? Заметно, что ты очень ей доверяешь.",
    ["戴莉女士也选了这条途径，看起来又神秘又酷炫……但我有些害怕尸体……"] = "Мисс Дейли тоже выбрала этот путь, он выглядит загадочно и круто... но я немного боюсь трупов...",
    ["戴莉用“通灵者”的手段无法发现，不表示它们就绝对不存在，或许在熟悉的、关键的地方，你会出现似乎见过、做过什么的感觉。"] = "Тот факт, что Дэйли не смог ничего открыть, используя методы «Духовной среды», не означает, что их абсолютно не существует. Возможно, в знакомых, важных местах у вас возникнет ощущение, что вы что-то видели или делали раньше.",
    ["戴莉缓缓走近蜡烛，向烛焰中滴了几滴纯露，香味迅速在房间里弥散。戴莉向克莱恩笑着说——"] = "Дейли медленно приближается к свече и капает в пламя несколько капель цветочной воды; аромат быстро распространяется по комнате. Дейли улыбается Клейн и говорит:",
    ["戴莉说你身上没有诅咒或恶灵的痕迹，应该很安全，放心吧。"] = "Дейли сказал, что на тебе нет следов проклятий или злых духов, так что это должно быть безопасно. Не волнуйся.",
    ["戴莉通灵，克莱恩下坠画面"] = "Дейли исполняет медиумизм с духами, сцена падения Клейн.",
    ["戴莉，你已经调去了贝克兰德教区，不用再称呼我队长了。"] = "Дейли, тебя уже перевели в Баклундскую епархию; тебе больше не нужно называть меня Капитаном.",
    ["戴莉，有什么发现吗？"] = "Дейли, есть открытия?",
    ["戴里克突然低下了头：不可直视神。"] = "Деррик внезапно опустил голову: нельзя смотреть прямо на Бога.",
    ["戴里克，动手吧。"] = "Деррик, сделай это.",
    ["所以她会在……"] = "Значит, она может быть в...",
    ["所以她会选择西南区。"] = "Поэтому она выберет Юго-Западный округ.",
    ["所以她派我来交给你。毕竟，我只是一条狗。"] = "Поэтому она послала меня передать это вам. В конце концов, я всего лишь собака.",
    ["所以我们至少拯救了四十多个人的生命？"] = "Значит, мы спасли как минимум сорок жизней?",
    ["所以我努力演好每一个角色，就算……就算观众看了二十场戏剧，也认不出我……"] = "Поэтому я стараюсь хорошо играть каждую роль, пусть даже... пусть даже Зритель посмотрит двадцать спектаклей, он всё равно меня не узнает...",
    ["所以消化魔药的关键是——"] = "Значит, ключ к перевариванию зелья — это...",
    ["所以，你在咖啡里放了什么？"] = "Итак, что ты добавил в кофе?",
    ["所以，我们应该再翻阅资料，筛选出死亡事件的数量在最开始阶段处于正常水平，这几天则快速攀升的区域。"] = "Значит, нужно ещё раз просмотреть данные и отобрать районы, где число случаев смерти в начале было в норме, а за последние дни стремительно выросло.",
    ["所以，是我把安提哥努斯家族的笔记送到了这里？"] = "Значит, это я доставил сюда дневник семьи Антигонуса?",
    ["所以，这么看来……"] = "Итак, если посмотреть на это с такой стороны...",
    ["所有人都为此惊叹，并表示这是他们听过最神奇的占卜。"] = "Все поражены этим и говорят, что это самое волшебное гадание, о котором они когда-либо слышали.",
    ["所有人，靠近我！"] = "Все ко мне!",
    ["手杖在摇晃之后，并没有倒下给出指引的方向，而是稳在了原地。"] = "После того как трость покачивается, она не падает, указывая направление, а остается устойчиво на месте.",
    ["手枪"] = "Пистолет",
    ["才9便士？前两天还要11便士，面包降价了？"] = "Всего 9 пенсов? Два дня назад стоил 11 пенсов... Хлеб подешевел?",
    ["打听折扣"] = "Спросите о скидках",
    ["打听皮特"] = "Спросить о Пите",
    ["打听皮特（心情未接入）"] = "Спросить о Пите (настроение не связано)",
    ["打扰，我叫丹尼，廷根技术学校机械系大二学生。"] = "Извините, меня зовут Дэнни, я учусь на втором курсе машиностроительного факультета Тингенской технической школы.",
    ["打招呼"] = "Поприветствовать",
    ["打断教学"] = "Прервать обучение",
    ["打牌！打牌！忘了正事！就会打牌！"] = "Карты! Опять карты! Забыл о деле! Только в карты и умеешь играть!",
    ["打赏10苏勒"] = "Дать на чай 10 соли",
    ["打赏1苏勒"] = "Совет 1 Соул",
    ["打赏5苏勒"] = "Совет 5 соулей",
    ["托尼，我是廷根最慷慨的房东，允许你们6人合租一间。"] = "Тони, я самый щедрый домовладелец в Тингене, я разрешаю вам шестерым вместе снять одну комнату.",
    ["执掌好运的黄黑之王。"] = "Король желтого и черного, приносящий удачу.",
    ["扮演"] = "Играть",
    ["扮演……所以我应该<P_Yellow>扮演</>一名“占卜家”，来帮助魔药消化？"] = "Действую... значит, я должен <P_Yellow>act</> как «Провидец», чтобы помочь зелью перевариться?",
