    ["是乌龟"] = "Это черепаха",
    ["是人偶"] = "Это кукла",
    ["是什么？"] = "Что это такое?",
    ["是他？！梦里那个小女孩的哥哥？"] = "Это он?! Старший брат маленькой девочки из сна?",
    ["是你在说话？一只说话的……狗？！"] = "Это ты говоришь? Говорящая... собака?!",
    ["是你？"] = "Это ты?",
    ["是信息洪流造成的攻击，看来月亮仆从发现我们的行动了，正在阻止我们！"] = "Это атака, вызванная потоком информации. Кажется, слуги Луны обнаружили наши действия и останавливают нас!",
    ["是否直接前往终点？"] = "Отправиться сразу к финишу?",
    ["是呀，最近人人都在谈论罗塞尔，我的东西也很好卖。"] = "Да, в последнее время все говорят о Розелле, и мои вещи очень хорошо продаются.",
    ["是呀，查理还非常谨慎，他从来不亲自接触那些危险的东西。"] = "Да, Чарли тоже очень осторожен; он никогда лично не прикасается к этим опасным вещам.",
    ["是呀，说明我们都在罗塞尔的画像上签了名。"] = "Да, это значит, что мы оба подписались на портрете Розеллы.",
    ["是啊"] = "Да уж",
    ["是啊，人的身份出生时就注定了。我们生来就是穷人，是随处可见，说踩就踩的蚂蚁。"] = "Да, положение человека определено с рождения. Мы родились бедняками, мы муравьи, которых везде полно и которых давят, когда вздумается.",
    ["是啊，本以为家里能出一个大学教授呢！"] = "Да, я думал, что в нашей семье может быть профессор университета!",
    ["是啊，真是一家很漂亮的店。"] = "Да, это действительно очень красивый магазин.",
    ["是啊，还好有你。"] = "Да, хорошо, что ты у меня есть.",
    ["是噩梦，但这只是邪神的污染在廷根造成的危险之一。"] = "Это кошмар, но это лишь одна из опасностей, связанных с заражением злого бога в Тингене.",
    ["是奥利安娜太太吗？我是新来的克莱恩·莫雷蒂，邓恩队长让我来预支4周的薪水。"] = "Это миссис Орианна? Я новый парень, Клейн Моретти. Капитан Данн попросил меня прийти и получить аванс в размере четырехнедельной зарплаты.",
    ["是安提哥努斯笔记！它就在绑匪对面的房间内！"] = "Это записная книжка семьи Антигон! Она в комнате прямо напротив похитителей!",
    ["是很奇怪……难道背后有什么力量在推动这一切？"] = "Это очень странно... Может ли быть какая-то закулисная сила, которая все это толкает?",
    ["是我。欢迎你，克莱恩。你真幸运，今天有足够的现金。"] = "Это я. Добро пожаловать, Клейн. Вам очень повезло; сегодня денег достаточно.",
    ["是我激活了邪恶仪式？我以为找齐三件物品，就能逃出去。"] = "Неужели это я активировал злой ритуал? Я думал, что если найду все три предмета, то смогу сбежать.",
    ["是我的同事，是会保护你的人。"] = "Он мой коллега, тот, кто защитит тебя.",
    ["是有人在戏弄我们，拿我们的命运开玩笑。是那个邮差，我会找到他的！"] = "Кто-то издевается над нами, шутит с нашей судьбой. Это тот почтальон, я найду его!",
    ["是父亲曾经的伟大构想，存在于知识皇冠中，如今也被母神污染了。"] = "Это было великое видение моего отца, существующее в Короне Знаний, а теперь оно также было испорчено Богиней-Матерью.",
    ["是的"] = "Да",
    ["是的。"] = "Да.",
    ["是的。关于这个世界的真相……以及即将到来的<P_Yellow>末日</>。"] = "Да. Об истине этого мира... и надвигающемся <P_Yellow>Апокалипсисе</>.",
    ["是的，{{先生|女士}}！我叫迪伦，《夜色金玫瑰》即将在贝克兰德上演，欢迎您去剧院观看！"] = "Да, {{господин|госпожа}}! Меня зовут Дилан, «Золотая роза ночи» скоро пройдёт в Бэкланде, приходите в театр посмотреть!",
    ["是的，他之前杀的人还有很多，那次他在准备一个邪异的仪式，所以才会被值夜者抓到。"] = "Да, до этого он убил много людей. В тот раз он готовил злой ритуал, из-за чего его поймали Ночные Ястребы.",
    ["是的，但不用太担心，只要使用和封印得当，它们在特定情况下能发挥极大的作用。"] = "Да, но не волнуйтесь слишком сильно. При правильном использовании и герметизации они могут сыграть огромную роль в конкретных ситуациях.",
    ["是的，但这只是我的解读，占卜往往都是模糊的。"] = "Да, но это только моя интерпретация; гадание часто бывает расплывчатым.",
    ["是的，她是一个天才，而且值夜者必须无条件相信队友。在非凡事件中，信任是一件非常重要的事。"] = "Да, она гений, а Ночные Ястребы обязаны безоговорочно верить товарищам. В делах Потусторонних доверие — это самое важное.",
    ["是的，拿出那枚金币、向我祈祷吧。"] = "Да, вынь эту золотую монету и помолись мне.",
    ["是的，是索尔斯。幸好及时发现，否则济贫院里的人都要死于这场火灾了。"] = "Да, это был Солс. К счастью, это было вовремя обнаружено, иначе в огне погибли бы все находившиеся в богадельне.",
    ["是的，水晶逆时针转动为坏，顺时针为好，不动就是不好也不坏。"] = "Да, кристалл, вращающийся против часовой стрелки – это плохо, по часовой стрелке – хорошо, а не двигающийся – это не хорошо и не плохо.",
    ["是罗塞尔大帝在指引我们！"] = "Это император Роселл направляет нас!",
    ["是这样吗……为什么？"] = "Это так... Почему?",
    ["是那场碎尸案，女神庇佑……克莱恩，你快点去找邓恩队长吧，我担心他等急了。"] = "Это дело о расчленении, да защитит нас Богиня... Клейн, поскорее иди к капитану Дэну, боюсь, он уже заждался.",
    ["是金玫瑰的氛围路人，按固定路线走的，要是能送水果就更真实了。"] = "Это фоновый прохожий «Золотой розы», ходит по заданному маршруту. Было бы реалистичнее, если бы ему можно было дарить фрукты.",
    ["是骗子吧？这出戏我看过二十次，是有这句话，但从没见过你。"] = "Ты обманщик? Я видел эту пьесу двадцать раз, такая реплика есть, но тебя я ни разу не видел.",
    ["是，直接前往终点"] = "Да, сразу к финишу",
    ["晚上好，我刚刚下班。"] = "Добрый вечер, я только что с работы.",
    ["晚上见。"] = "Увидимся сегодня вечером.",
    ["晚安，克莱恩。"] = "Спокойной ночи, Клейн.",
    ["普通人类通过服用魔药成为<P_Yellow>非凡者</>，其中最低的品阶是序列9。序列数字越<P_Yellow>小</>，魔药品阶就越<P_Yellow>高</>。"] = "Обычные люди становятся <P_Yellow>Потусторонние</>, потребляя зелья, при этом самым низким рангом является Последовательность 9. <P_Yellow>smaller</> - порядковый номер, <P_Yellow>higher</> - ранг зелья.",
    ["暂时没事了"] = "Пока ничего",
    ["更具体的细节我不能详述，因为涉及到一些位格很高的存在，涉及到星空。"] = "Я не могу вдаваться в подробности, потому что это связано с существованием очень высокого статуса и звездным небом.",
    ["更准确地描述是，他们应该拥有的生命被超凡因素人为地缩短了，被窃取走了。"] = "Точнее говоря, жизнь, которая им полагалась, была искусственно сокращена сверхъестественными факторами и украдена.",
    ["更危险？为什么？"] = "Более опасно? Почему?",
    ["更大的考验？"] = "Большие испытания?",
    ["曾有人这样呼唤过我，你们可以称我为——"] = "Некоторые называли меня так раньше. Ты можешь позвонить мне—",
    ["曾经是，现在也还是。"] = "Я был раньше и остаюсь им.",
    ["最快的票要三天后，甲板票3苏勒，客舱票6苏勒。"] = "Самый быстрый билет — за три дня; билеты на палубу стоят 3 суле, билеты в каюту — 6 соло.",
    ["最近发生了不少事情，终于有机会好好想下后续的晋升了。"] = "За последнее время многое произошло, и у меня наконец-то появилась возможность как следует подумать о своем дальнейшем продвижении.",
    ["最近失踪和献祭案件频发，郊外五月庄园也有异常迹象。"] = "В последнее время участились случаи исчезновений и жертвоприношений, а также есть признаки аномалий в Мэй-Мэноре в пригороде.",
    ["最近总有这种人混进来。布兰登先生，让您见笑了。"] = "В последнее время сюда постоянно проникают такие люди. Господин Брэндон, прошу прощения за это зрелище.",
    ["最近我应该经常来，对这里还有些模糊的印象。"] = "Должно быть, в последнее время я часто приходил сюда; У меня до сих пор остались смутные впечатления об этом месте.",
    ["最近比较特殊的是……"] = "Что особенного в последнее время...",
    ["最近炼钢厂设备升级，我和十几个工友都被解雇了。"] = "Сталелитейный завод недавно модернизировал свое оборудование, и меня и дюжину моих коллег уволили.",
    ["最近班森要回家了……记得之前答应他要去接他回家，然后一起吃顿好的！"] = "Бенсон недавно собирается домой... Помню, я обещал ему, что заеду за ним и вместе вкусно пообедаем!",
    ["最近的事情"] = "Недавние события",
    ["最近黑荆棘人手紧张，这位新员工……"] = "В Чёрный Чертополох в последнее время не хватает рабочих рук, этот новый сотрудник...",
    ["最近？"] = "В последнее время?",
    ["月亮仆从……我去了趟五月庄园，那里很诡异，有些工人已经失踪。"] = "Лунный Слуга... Я отправился в Мэй-Мэнор, там было очень жутковато, и некоторые работники уже пропали.",
    ["月亮仆从最近才在廷根活跃起来，我们掌握的线索很有限。"] = "Лунный Слуга лишь недавно начал активную деятельность в Тингене, и имеющиеся у нас сведения очень ограничены.",
    ["月亮木偶"] = "Лунная Марионетка",
    ["月亮木偶站起来，蹦蹦跳跳，做出祈祷月亮动作。\n木偶：月亮，月亮，发光，发光。\n木偶：万物，生长，生长——\n同时，周围藤蔓蔓延，将伊妮德缠绕……"] = "Лунная марионетка поднялась, начала подпрыгивать и молитвенно воздела руки к луне.\nМарионетка: Луна, луна, сияй, сияй...\nМарионетка: Всё сущее, расти, расти...\nВ то же мгновение вокруг разрослись лозы, оплетая Энид...",
    ["有2处符合的地点。"] = "Есть 2 подходящих места.",
    ["有一些惊讶，原来这个世界不仅有众神和非凡……"] = "Я немного удивлен; оказывается, что в этом мире есть не только боги и Потусторонние...",
    ["有一天，你的队友变成了对手……而你不得不杀死他。"] = "Однажды ваш товарищ по команде станет вашим противником... и вам придется его убить.",
    ["有了钱就可以让汤姆上学，我去夜校学写字，汤姆去教会学校学算术……上学……更好的生活……更好的时代！"] = "Имея деньги, я могу отпустить Тома в школу, я могу пойти в вечернюю школу, чтобы научиться писать, а Том может пойти в церковную школу, чтобы выучить арифметику... Школа... лучшая жизнь... лучшая эпоха!",
    ["有些兴奋，但也有些害怕……"] = "Немного волнительно, но в то же время страшновато...",
    ["有人在值班室睡觉，她刚值完夜，需要休息。这里安静。"] = "В дежурной комнате кто-то спит: она только с ночной смены и ей нужен отдых. Здесь тихо.",
    ["有人杀害了他们？"] = "Их кто-то убил?",
    ["有人用棍子打我，我疼，我不要待在这里！"] = "Кто-то бил меня палкой, мне больно, я не хочу здесь оставаться!",
    ["有什么不对劲！镇定、镇定……"] = "Что-то не так! Сохраняйте спокойствие, сохраняйте спокойствие...",
    ["有什么收获吗？"] = "Есть ли выгоды?",
    ["有什么需要帮忙吗？这是队长给的药剂。"] = "Могу ли я чем-нибудь помочь? Это зелье, которое дал мне капитан.",
    ["有什么需要帮忙的吗？我是说，他们看起来不像是单纯来讨保护费的混混。"] = "Как я могу помочь? Я имею в виду, они не выглядят так, будто просто ищут денег на защиту.",
    ["有位神明想让我学习和理解所谓人性，他们都是很好的实验对象。"] = "Один бог хочет, чтобы я изучил и понял так называемую человечность, а они все — отличные подопытные.",
    ["有关“月亮仆从”的成员，现在的情况是……"] = "Что касается членов «Лунной Слуги», то нынешняя ситуация такова...",
    ["有关“月亮仆从”的献祭计划，除了廷根，还有……"] = "Что касается жертвенного плана «Лунного Слуги», то, кроме Тингена, есть еще…",
    ["有关时代"] = "Об эпохе",
    ["有关那对兄妹"] = "Об этой паре братьев и сестер",
    ["有关黑荆棘"] = "О Блэкторне",
    ["有力量在干扰占卜……"] = "Есть сила, мешающая гаданию...",
    ["有危险，危险很大！"] = "Есть опасность, большая опасность!",
    ["有可能……也许这就是他们，不，她们序列魔药的特点，在某个序列会从男性变为女性。"] = "Это возможно... возможно, это особенность их, нет, ее зелья Последовательности, где в определенной Последовательности человек превращается из мужчины в женщину.",
    ["有可能，他们以知识洪流的形式，进入隐藏空间，这在非凡领域并不罕见。"] = "Вполне возможно, что они проникли в скрытое пространство в форме потока знаний. В потустороннем мире такое не редкость.",
    ["有可能，现在你来到现实，加上邪神污染的影响，嫁接的力量很可能受到干扰。"] = "Это возможно. Теперь, когда вы пришли в реальность, в сочетании с влиянием порчи злого бога, сила Прививки, скорее всего, будет нарушена.",
    ["有意思，你在同情他们？那你自己又在为什么而挣扎呢？"] = "Интересно, ты сочувствуешь им? А за что тогда борешься ты сам?",
    ["有新客人光顾。看来我们的魔镜占卜课程要先搁置下。"] = "У нас новый гость. Кажется, наш урок Зеркального гадания придется отложить.",
    ["有时候，人性中的意志比封印更坚固。"] = "Иногда воля человечества крепче любой печати.",
    ["有时候，适当的“心理放松”比战斗技巧更重要。"] = "Иногда правильное «психическое расслабление» важнее боевых приемов.",
    ["有时间多回来看看，大家都很牵挂你。"] = "Будет время — навещай нас, все очень скучают по тебе.",
    ["有没有人告诉过你，你很不擅长撒谎。"] = "Кто-нибудь когда-нибудь говорил тебе, что ты очень плохо лжешь?",
    ["有点……最近发生了太多事，也不知道未来会怎样。"] = "Немного... слишком много всего произошло за последнее время, и я не знаю, каким будет будущее.",
    ["有的，但和几年前相比，已经安全多了。"] = "Есть, но по сравнению с тем, что было несколько лет назад, это намного безопаснее.",
    ["有种看见孩子长大的感觉，今晚我们得好好庆祝一下！让我来露一手，这次出差我学了一些新菜式……"] = "Такое чувство, словно на моих глазах вырос ребенок. Сегодня непременно нужно это отпраздновать! Позвольте мне блеснуть кулинарными талантами — в этой командировке я научился нескольким новым блюдам...",
    ["有趣的技巧？"] = "Любопытный трюк?",
    ["有趣的逻辑。但在梦里你为什么要逃？你在害怕什么？"] = "Интересная логика. Но почему ты убежал во сне? Чего ты боишься?",
    ["有隐秘组织在廷根制造危机？"] = "Существует ли секретная организация, создающая кризис в Тингене?",
    ["服从您的吩咐。"] = "Я буду подчиняться вашим указаниям.",
    ["木偶愤怒不已：“破坏仪式的人，破坏仪式的人！”\n喊叫声中，水中的红花突然孕育长大，变成了一只诡异的怪物。"] = "Марионетка была в ярости: «Тот, кто сорвал ритуал! Тот, кто сорвал ритуал!»\nПод эти вопли алый цветок в воде внезапно разросся и превратился в жуткое чудовище.",
    ["木偶：拥抱“伟大母亲”！获得“新生与拯救”！"] = "Марионетка: Прильните к «Великой Матери»! Обретите «перерождение и спасение»!",
    ["未完待续"] = "Продолжение следует",
    ["未来"] = "Будущее",
    ["未来的旅途中，“愚者”先生会继续降下庇佑。赞美愚者！"] = "В будущем путешествии Мистер продолжит даровать благословения. Слава Шуту!",
