    ["没有，罗斯先生。宴会即将开始，请您跟我来。"] = "Нет, господин Росс. Скоро начнётся банкет, прошу следовать за мной.",
    ["没礼貌还要教坏小朋友的臭小子！"] = "Невоспитанный мальчишка, ещё и малышей дурному учит!",
    ["没错"] = "Именно так",
    ["没错。其他人都有任务，丽贝卡还在查另一件封印物，只好我们三个分工了。"] = "Это верно. У всех остальных есть задания, а Ребекка все еще исследует еще один Запечатанный Артефакт, поэтому нам придется разделить работу между нами троими.",
    ["没错。每天上午十点半和下午三点，老维尔餐厅会派服务生到黑荆棘去。"] = "Это верно. Каждый день в 10:30 и 15:00 ресторан Old Will's будет отправлять в Чёрный Чертополох официанта.",
    ["没错。而操纵这场恶作剧的序列3阿蒙分身，来源于一个交易。"] = "Верно. А аватар Амона Последовательности 3, устроивший этот розыгрыш, появился в результате сделки.",
    ["没错。这是一个可怕的诅咒仪式，幸运的是， 它已经被破坏了。"] = "Именно так. Это был чудовищный ритуал проклятия, но, к счастью, его удалось сорвать.",
    ["没错！我就是弑父那段戏里，爱德华脚边的第二具尸体！"] = "Верно! Это я второй труп у ног Эдварда в сцене убийства отца!",
    ["没错，但只是两个小提示。雨停了，准备好就出门试试吧。"] = "Верно, но это лишь пара подсказок. Дождь закончился: когда будешь готов, выходи и попробуй сам.",
    ["没错，你不是。记住你现在的想法，永远不要动摇。"] = "Правильно, это не так. Помните о своих текущих мыслях и никогда не колебайтесь.",
    ["没错，你不是迪伦，我才是你。"] = "Верно, ты не Дилан. Это я — ты.",
    ["没错，出去走走，找个咖啡厅，喝杯咖啡放松一下。"] = "Правильно, выйдем на прогулку, найдем кафе и выпьем чашечку кофе, чтобы расслабиться.",
    ["没错，加上“灰雾之上的神秘主宰”，就能把灰雾空间和我绑定在一起了。"] = "Правильно, добавив «таинственного правителя над серым туманом», я могу привязать к себе пространство серого тумана.",
    ["没错，守护不是一时的热血，而是无数次的奋战与坚持。"] = "Правильно, охрана – это не сиюминутный порыв страсти, а бесчисленные сражения и упорство.",
    ["没错，我的同伴也都以塔罗牌为代号，我们的组织叫塔罗会。"] = "Правильно, мои спутники тоже используют карты Таро в качестве кодовых имен, а наша организация называется Клуб Таро.",
    ["没错，末日终于有了新的希望。"] = "Правильно, наконец-то появилась новая надежда на апокалипсис.",
    ["没错，这正是非凡世界的非凡之处。"] = "Правильно, в этом необыкновенность Необыкновенного Мира.",
    ["没错，送给你，它会带来好运的。"] = "Верно, это тебе в подарок. Он принесёт удачу.",
    ["没错，那和之前一样，我骑车带你去。"] = "Правильно, тогда, как и прежде, я отвезу тебя туда.",
    ["没错，邪神子嗣并没有停止孕育。"] = "Правильно, вынашивание потомства злого бога не прекратилось.",
    ["没错，金玫瑰——贝克兰德最高档的寻欢场所。"] = "Верно, «Золотая роза» — самое роскошное место для развлечений в Бэкланде.",
    ["没问题"] = "Без проблем",
    ["没问题。心理治疗还需要些时间，唤醒{{他|她}}之前，我会通知大家的。"] = "Без проблем. Психотерапия займет некоторое время. Я уведомлю всех, прежде чем разбудить {{him|her}}.",
    ["没问题。那可以允许我看看您的脚踏车吗？"] = "Без проблем. Разрешите взглянуть на ваш велосипед?",
    ["没问题，弗莱队长，我也许能发现一些新线索。"] = "Нет проблем, капитан Фрай. Возможно, мне удастся найти новые подсказки.",
    ["治疗顺利，快醒来吧。"] = "Лечение идет успешно, очнись же поскорее.",
    ["沿着楼梯下去，<P_Yellow>直走</>到尽头就是查尼斯门。中间十字路口<P_Yellow>左拐</>通向圣赛琳娜教堂和炼金室，<P_Yellow>往右</>是武器、材料和文献库，别走错了。"] = "Спуститесь по лестнице, <P_Yellow>, идите прямо</> до конца, и вы доберетесь до Врат Чаниса. Пересечение посередине <P_Yellow>поверните налево</> ведет к собору Святой Селены и Алхимической комнате, <P_Yellow> направо </> — это комната с оружием, материалами и архивами, не идите неверным путем.",
    ["沿这条路<P_Yellow>直走</>就是查尼斯门，中间十字路口<P_Yellow>左拐</>通向圣赛琳娜教堂和炼金室，<P_Yellow>往右</>是武器、材料和文献库，别走错了。"] = "Идите <P_Yellow>straight</> по этой дороге, чтобы добраться до Врат Чаниса. На перекрестке посередине <P_Yellow> поверните налево, </>, чтобы добраться до собора Святой Селены и Алхимической комнаты, а <P_Yellow> направо, </> — это библиотека оружия, материалов и архивов. Не идите неверным путем.",
    ["洛络塔有三大爱好，咖啡，甜点和女仆，她说必须有这三样事物，才能加速痊愈。"] = "У Лороты три главных хобби: кофе, десерты и горничные. Она говорит, что ей необходимы эти три вещи, чтобы ускорить выздоровление.",
    ["洛耀在里面睡觉，她刚值完夜，需要休息。"] = "Ло Яо спит внутри; она только что закончила ночную смену и ей нужно отдохнуть.",
    ["洪亮钟声在城市上空响起。玩家停步，抬头聆听：\n“好洪亮的钟声，不愧是号称万都之都的大都市。”\n愚者教堂上，巫师帽阿蒙敲完钟，化为乌鸦飞走。\n“演员就位，好戏开场。”"] = "Над городом разносится гулкий звон колокола. Игрок останавливается и, подняв голову, прислушивается:\n«Какой гулкий звон. Недаром это называют столицей всех столиц».\nНа церкви Шута Амон в шляпе чародея отзвонил, обратился вороном и улетел.\n«Актёры на местах, представление начинается».",
    ["洪亮钟声在贝克兰德上空响起。玩家停步，抬头聆听。\n愚者教堂上，巫师帽阿蒙敲完钟，化为乌鸦飞走。\n“踏入命运的乱流吧，这次更有趣。”"] = "Над Бэклэндом разносится гулкий звон колокола. Игрок останавливается и, подняв голову, прислушивается.\nНа церкви Шута Амон в шляпе чародея отзвонил, обратился вороном и улетел.\n«Шагните в бурный поток судьбы. На этот раз будет ещё интереснее».",
    ["活下去"] = "Выживать",
    ["活化出逃？如果没有封印，它的力量足以毁灭一个国家，甚至整个世界。"] = "Активировался и сбежал? Без печати ее силы достаточно, чтобы уничтожить страну или даже весь мир.",
    ["海纳斯·凡森特死了……死因是什么？"] = "Хейнс Винсент мертв... какова причина смерти?",
    ["海纳斯·凡森特？！"] = "Ханас Винсент?!",
    ["消失的伤口"] = "Исчезающая рана",
    ["清理血迹"] = "Очистите пятна крови",
    ["清醒的人总是满口谎话，真实往往隐藏在梦境之中。比起清醒的你，我更相信梦中的你。"] = "Бодрствующие люди постоянно лгут, тогда как истина сокрыта в сновидениях. Чем тебе наяву, я больше верю тебе во сне.",
    ["湖畔异变"] = "Аномалия на берегу озера",
    ["演出结束，再次伴随喷泉、喝彩、烟花彩带等——\n小丑们在芬奇带领下站成一排，向观众席谢幕。"] = "Представление окончено, и снова звучат фонтаны, овации, взрываются фейерверки и взлетают ленты...\nКлоуны во главе с Финчем выстраиваются в ряд и кланяются Зрителям.",
    ["漫游星空的旅行者，黄黑之王的眷属，记录世界的法师。"] = "Путешественник, бродящий среди звезд, слуга Короля Желтого и Черного, маг, записывающий мир.",
    ["灰白的雾气又一次在眼前涌现，无数记载着历史的碎片从身边穿梭而过。"] = "Перед вашими глазами снова встает серо-белый туман, и мимо вас проходят бесчисленные фрагменты, записывающие историю.",
    ["灰雾之上的神秘主宰。"] = "Таинственный правитель над серым туманом.",
    ["灰雾之上，两道染着深红的虚幻身影骤然出现在光芒之中。"] = "Над серым туманом внезапно появились на свету две иллюзорные фигуры, окрашенные в насыщенный красный цвет.",
    ["灰雾重重中，虚影阿尔杰和奥黛丽仰视的画面"] = "Среди густого серого тумана призраки Алджера и Одри смотрят вверх.",
    ["灵性在疯狂预警，这里混乱又危险，必须先离开再说了。"] = "Духовность предупреждает о безумии. Здесь хаос и опасность, нужно сначала уйти.",
    ["灵摆占卜"] = "Гадание на маятнике",
    ["灵摆呈顺时针转动……房间内存在<P_Yellow>超凡因素导致的危险</>！"] = "Маятник вращается по часовой стрелке... в комнате <P_Yellow> существует опасность, вызванная чрезвычайными факторами </>!",
    ["灵视会让你看到一些隐藏的，甚至有些奇怪的东西。"] = "Духовное зрение позволит вам увидеть некоторые скрытые и даже несколько странные вещи.",
    ["灵视？可以看见隐藏的东西？我试试看……"] = "Духовное видение? Можете ли вы видеть скрытые вещи? Дай мне попробовать...",
    ["炸弹！我赢了！"] = "Бомба! Я выиграл!",
    ["点头"] = "Кивнуть",
    ["点头回应"] = "Кивнуть в ответ",
    ["然后再次向我祈祷，祈求进入历史迷雾的许可。"] = "Тогда помолитесь мне еще раз, попросив разрешения войти в туман истории.",
    ["然后呢？"] = "А потом?",
    ["然后哼一段悠扬的旋律，跳一支轻快的宫廷舞——你喜欢踢踏舞也可以。最后，再来局昆特牌……"] = "Затем напевайте мелодичную мелодию и станцуйте легкий придворный танец — если хотите, можете танцевать чечетку. Наконец-то сыграйте в Гвинт...",
    ["然后我昨晚做了一个梦，在梦中得到了线索！"] = "А прошлой ночью мне приснился сон, и во сне я получил подсказку!",
    ["然而，我并没有亲妹妹……抱歉，梅丽莎，我真的想<P_Yellow>回家</>。"] = "Однако у меня нет настоящей младшей сестры... Прости, Мелисса, я очень хочу <P_Yellow> пойти домой</>.",
    ["照做"] = "Сделать так",
    ["照片右上角被烧毁，那位先生的上半身也被烧掉了。"] = "Правый верхний угол фотографии сожжен, и верхняя часть тела этого господина тоже сожжена.",
    ["爱丽丝你还不明白吗？我们都被那混蛋骗了！"] = "Алиса, ты еще не понимаешь? Нас всех обманул этот ублюдок!",
    ["爸爸……莉娅以后会很乖，会多多干活，少少吃饭……"] = "Папа... Лия будет очень послушной, будет больше работать и меньше есть...",
    ["爸爸！不要走，不要丢掉莉娅！"] = "Папа! Не уходи, не бросай Лию!",
    ["特莉丝就是特里斯，这也可以完美解释特里斯突然失踪的谜题。"] = "Трисси — это Трис. Это идеально объясняет загадку внезапного исчезновения Триса.",
    ["特莉丝，想要活下去，总要付出点代价，不是吗？"] = "Трисси, если ты хочешь выжить, тебе придется заплатить определенную цену, не так ли?",
    ["特里斯，特里斯，你一路都在提这个名字。"] = "Трисс, Трисс, ты все время упоминала это имя.",
    ["状态怎么样了？你的记忆被污染，可能精神和身体有时会不稳定。"] = "Как твое самочувствие? Твои воспоминания осквернены, поэтому душевное и физическое состояние временами может быть нестабильным.",
    ["犹豫"] = "Сомневаться",
    ["猎龙帮？"] = "Банда охотников на драконов?",
    ["猜对了！"] = "Угадал правильно!",
    ["玩家和邮差并行，各推着自己的脚踏车，新旧对比。\n邮差：这趟旅途真是令人难忘，对吧？\n邮差：恶作剧就要开始了，一会儿见。\n邮差骑车离开，玩家困惑走到岸上停下。"] = "Игрок и почтальон идут рядом, каждый ведёт свой велосипед: новое и старое в контрасте.\nПочтальон: Это путешествие было незабываемым, правда?\nПочтальон: Розыгрыш вот-вот начнётся, скоро увидимся.\nПочтальон уезжает на велосипеде, а игрок в растерянности доходит до берега и останавливается.",
    ["玩游戏是为了开心，谁要听路人诉苦啊！工贼，要不把马贼叫来打牌？"] = "В игры играют ради удовольствия, кому охота слушать жалобы прохожего! Штрейкбрехер, может, позвать конокрадов сыграть в карты?",
    ["环境异变加重，市民不断瓦解……恐怕献祭已经开始了。"] = "Экологические аномалии ухудшаются, а граждане постоянно деградируют... Боюсь, Ритуал Жертвоприношения уже начался.",
    ["现在"] = "Подарок",
    ["现在不是哭的时候，要振作啊爱丽丝！"] = "Сейчас не время плакать, возьми себя в руки, Алиса!",
    ["现在他委托我，遵循命运的指引，把金币转交给你。"] = "Теперь он поручил мне следовать указаниям судьбы и передать вам золотую монету.",
    ["现在去直接调查还是有危险，不过放心，他们的行动一直在监视中。"] = "Сейчас по-прежнему опасно идти и проводить расследование, но не волнуйтесь, их действия находятся под постоянным наблюдением.",
    ["现在又出现了献祭案，背后还有魔女教派的影子……谁能操控这么多事件和势力？ "] = "Теперь ещё и дело о жертвоприношении, а за ним маячит тень секты Демониц... Кто способен управлять столькими событиями и силами?",
    ["现在呢？洗火车头的清洁工？也许早死在了下水道里。"] = "А сейчас? Уборщик моет локомотивы? Возможно, он давно умер в канализации.",
    ["现在应该做的是……"] = "Что нам следует сделать сейчас, так это...",
    ["现在想来，那真是一段美好的时光……虽然工厂老板很吝啬、工作也很繁重……"] = "Вспоминая сейчас, это и вправду было чудесное время... Хоть хозяин фабрики и был прижимист, а работа — каторжной...",
    ["现在最应该关注的是……"] = "Больше всего сейчас следует волноваться...",
    ["现在蒸汽列车只要四小时——但我强烈推荐你坐船去，可以欣赏塔索克河的沿途风光，绝对是难忘的体验，你也需要放松一下了！"] = "Паровой поезд сейчас идет всего четыре часа, но я настоятельно рекомендую вам отправиться на корабле. Вы можете насладиться пейзажами вдоль реки Тассок; это определенно незабываемые впечатления, и вам тоже нужно расслабиться!",
    ["现在这个时代，具备自嘲精神的绅士越来越少了，幸运的是，我们今天又遇到一位。"] = "В эту эпоху все меньше и меньше господ с духом самоуничижения. К счастью, сегодня мы встретили еще одного.",
    ["现在这样就很好，我可以一直留在廷根，一直守护这里。"] = "Все в порядке, как сейчас. Я могу остаться в Тингене навсегда и продолжать охранять это место.",
    ["现在，你可以思考自己欠我多少冰淇淋了。"] = "Теперь можешь подумать, сколько порций мороженого ты мне должен.",
    ["现场没有那本第四纪遗留的笔记，整栋房屋里都没有，而其他相关人员都死了。"] = "Записной книжки, оставшейся от Четвертой эпохи, на месте происшествия нет; это не во всем доме, и все остальные участники мертвы.",
    ["珍妮，这是你的图纸吗？我在斯林太太的面包房找到的。"] = "Дженни, это твой рисунок? Я нашел его в пекарне миссис Слин.",
    ["班森来信说他最近会回廷根，我们需要提前准备些吃的。"] = "Бенсон написал, что скоро вернется в Тинген. Нам нужно заранее приготовить еду.",
    ["班森，你也很适合这么穿。"] = "Бенсон, ты в этом тоже очень хорошо выглядишь.",
    ["班森，你真是一个有良心，做事诚实的年轻人！"] = "Бенсон, вы действительно добросовестный и честный молодой человек!",
    ["班森，你错了。"] = "Бенсон, ты ошибаешься.",
    ["班森，欢迎回家。怎么不提前说一声，我们可以去车站接你。"] = "Бенсон, добро пожаловать домой. Почему бы вам не сказать нам заранее, что мы можем забрать вас на вокзале.",
    ["班森：“哈，姜汁啤酒！我可太想念这个味道了。”"] = "Бенсон: «Ха, имбирное пиво! Я так соскучился по этому вкусу».",
    ["理论上是这样，但是……"] = "Теоретически да, но...",
    ["琳达小姐，您点的迷雾香槟。"] = "Госпожа Линда, ваше туманное шампанское.",
    ["瑞尔·比伯"] = "Рэй Бибер",
    ["瑞尔·比伯只是个普通人，但在非凡力量的诱惑之下，他的理智完全被吞噬了。那不是一般人类可以抵抗的诱惑。"] = "Рэй Бибер был обычным человеком, но под искушением необычайной силы его рассудок был полностью поглощён. Это искушение, которому не может противостоять ни один обычный человек.",
    ["瑞尔·比伯被非凡事件牵扯，死于诡异和混乱。韦尔奇和娜娅也是这样死的……"] = "Рэй Бибер оказался втянут в потусторонний инцидент и погиб в паутине странностей и хаоса. Так же погибли Уэлч и Ная...",
    ["瑞尔不是坏人，如果你能见到他的话……"] = "Рэй не плохой человек, если ты его видишь...",
    ["瑞尔继承了他父亲的珠宝匠人手艺，我对经营店铺也有兴趣。我们想要摆脱吝啬的工厂主，也给自己谋点别的生计。"] = "Рэй унаследовал ювелирное мастерство своего отца, и я также заинтересован в открытии магазина. Мы хотели избавиться от скупого фабриканта и найти другой способ зарабатывать себе на жизнь.",
    ["瑞尔说“猎龙”意味着勇气和团结，于是我们就一直这么称呼自己。"] = "Риэль сказала, что «Охотник на драконов» означает храбрость и единство, поэтому мы всегда так себя называли.",
    ["瑞尔？"] = "Риэль?",
    ["瓶中突然爆发出红色的光芒，将他吞没。"] = "Красный свет внезапно вырвался из бутылки, поглотив его.",
    ["生日……怎么这么熟悉……"] = "День рождения... почему он кажется таким знакомым...",
    ["生日快乐！"] = "С днем ​​рождения!",
    ["生日快乐，赛琳娜。这两位是我的哥哥，班森和克莱恩。"] = "С днем ​​рождения, Селина. Эти двое — мои братья, Бенсон и Клейн.",
    ["生日？"] = "День рождения?",
    ["生活慢慢好起来了，真好。 "] = "Жизнь потихоньку налаживается, это здорово.",
    ["用不了多久，这里的一切都会化为虚无，包括我们在内。"] = "Пройдет немного времени, прежде чем все здесь превратится в ничто, включая нас.",
    ["用冰淇淋观察他们的命运，或许能看到命运异常的情况！"] = "Понаблюдайте за их судьбой с помощью мороженого, возможно, удастся увидеть аномалии судьбы!",
    ["用家里的食材做点什么好呢……是时候让她见识一下真正的厨艺了！"] = "Что мне приготовить из ингредиентов дома... Пришло время показать ей настоящее кулинарное мастерство!",
    ["甲板票"] = "Палубный билет",
    ["画画。"] = "Рисовать.",
    ["画画？这是你的工作？在这么暗的地方？"] = "Рисунок? Это твоя работа? В таком темном месте?",
    ["痛！"] = "Боль!",
    ["的确，这样之后再参与案件调查，也更熟悉和安全些。"] = "Действительно, так будет привычнее и безопаснее участвовать в расследовании дел в дальнейшем.",
    ["皮特"] = "Пит",
    ["皮特从地里挖出了一个木偶。\n片刻后，一动不动的木偶突然活了过来！"] = "Пит откопал из земли деревянную марионетку.\nСпустя мгновение неподвижная кукла внезапно ожила!",
    ["皮特摸摸祭台旁边的月亮木偶，点亮第三根蜡烛。\n伊妮德突兀地出现，从林间跑出来。\n伊妮德：哥哥，原来你在这。\n皮特：伊妮德，快过来，到哥哥身边来。\n伊妮德刚踏入法阵区域，法阵完全亮起。"] = "Пит погладил деревянную лунную фигурку у алтаря и зажёг третью свечу.\nИз леса неожиданно выбежала Энид.\nЭнид: Братик, так ты здесь!\nПит: Энид, скорее иди сюда, подойди к брату.\nСтоило Энид ступить в пределы магического круга, как круг ярко вспыхнул.",
    ["皮特点燃了木桩（原来它是一个祭台）上的所有蜡烛，并呼唤伊妮德过去。"] = "Пит зажег все свечи на деревянном столбе (который оказался алтарем) и позвал Энид.",
    ["目前有两种选择，一是效仿戴莉女士向值夜者组织提出晋升“小丑”的特别申请，但可能要面对晋升过快带来的调查。"] = "На данный момент есть два варианта: один — последовать примеру г-жи Дейли и подать в «Ночные ястребы» специальную заявку на повышение до «Клоуна», но из-за быстрого продвижения мне, возможно, придется столкнуться с расследованием.",
    ["目前根据线索来看，五月庄园似乎在准备一场指向“堕落母神”的献祭仪式。"] = "Судя по подсказкам, в настоящее время Мэй-Мэнор, похоже, готовит ритуал жертвоприношения, направленный на «Богиню-Матерь Разврата».",
    ["目前的情况"] = "Текущая ситуация",
    ["目标逃走了……"] = "Цель ускользнула...",
    ["直接去阻止皮特"] = "Идите прямо, чтобы остановить Пита.",
    ["直接离开"] = "Уйти прямо",
    ["直接询问价格"] = "Спросите цену напрямую",
    ["直通康斯顿城的蒸汽列车“飞翔号”今日开通……"] = "Паровой поезд «Летящий» в Конистон-Сити откроется сегодня...",
    ["相信我们，我们会成功的。"] = "Поверьте в нас, у нас все получится.",
    ["看你迷茫的眼神，这么快就不记得我了？"] = "Глядя в твои растерянные глаза, ты не так скоро обо мне вспоминаешь?",
    ["看向“倒吊人”"] = "Взглянуть на «Висельника»",
    ["看向“正义”"] = "Посмотрите «Справедливость».",
    ["看完了，学到很多知识。嗯……买一张邮票吧。"] = "Досмотрел, узнал много знаний. Хм... Я куплю марку.",
    ["看情况……但成为值夜者，你会失去很多，比如自由。"] = "Смотря как посмотреть... Но став Ночным Ястребом, ты многого лишишься — например, свободы.",
    ["看报纸"] = "Читать газету",
    ["看来不行……"] = "Кажется, это не сработает...",
    ["看来你准备了不少啊！"] = "Похоже, ты хорошо подготовился!",
    ["看来噩梦的确是某种预兆。我得抓紧时间找到他，阻止他。"] = "Кажется, кошмар действительно является своего рода предзнаменованием. Я должен поторопиться, чтобы найти его и остановить.",
    ["看来我昨天错过了一个非常大的功劳。"] = "Кажется, вчера я упустил огромный кредит.",
    ["看来短时间内是不能回家了……从现在开始，我就是克莱恩了。"] = "Кажется, я некоторое время не смогу вернуться домой... Отныне я Клейн.",
    ["看来要对海纳斯展开更深入的调查，才能找出他背后组织的阴谋。"] = "Похоже, что необходимо более глубокое расследование деятельности Хейнса, чтобы раскрыть заговор стоящей за ним организации.",
    ["看来还需要些心理治疗，我会告诉“正义”女士的。"] = "Похоже, психотерапия все же необходима, скажу я Мисс Джастис.",
    ["看看徽章"] = "Посмотрите на значок",
    ["看看脚踏车？当然可以，很公平的交换。"] = "Посмотрите на велосипед? Конечно, это честная сделка.",
    ["看看黛拉的腰，我练了三年都没练出来。她到底是怎么保养的？"] = "Посмотри на талию Деллы, я тренируюсь три года и так и не добилась такой. Как она за собой ухаживает?",
    ["看起来像一层屏障，试试看能不能摧毁它。"] = "Похоже на барьер. Попробуем его разрушить.",
    ["看起来太成熟了，成熟到我想喊你一声哥哥。"] = "Это выглядит слишком зрелым, настолько зрелым, что мне хочется называть тебя братом.",
    ["看起来很不错！"] = "Выглядит замечательно!",
    ["看起来是珍妮画的机械图纸，对了——"] = "Кстати, это похоже на механические чертежи, нарисованные Дженни…",
    ["看起来，你即将踏上一次新的旅途呢，呵呵。"] = "Кажется, ты собираешься отправиться в новое путешествие, хе-хе.",
    ["真不错，不过你回家这么晚……刚工作就要加班？那些可恶的老板！"] = "Это здорово, но ты так поздно дома... Работаешь сверхурочно сразу после начала работы? Эти ненавистные боссы!",
    ["真不错，看起来是个靠谱又帅气的好家伙。"] = "Действительно приятный, он кажется надежным и красивым парнем.",
    ["真不错，福利待遇都很丰厚，同事们看起来也很友善。"] = "Это довольно хорошо; льготы щедры, а коллеги кажутся очень дружелюбными.",
    ["真令人感叹。这样一位杀过不少怪物的“守卫”，最后自己失控变成了怪物……"] = "Это действительно прискорбно. Такой «охранник», убивший множество монстров, наконец-то потерял контроль и сам стал монстром...",
    ["真好啊，如果我儿子也能像你这样，有一份正经的、体面的工作，那我做梦都能笑醒……"] = "Замечательно. Если бы мой сын мог быть таким, как вы, и иметь нормальную, достойную работу, я бы просыпался с улыбкой во сне...",
    ["真好，我也想躺着挣钱，可惜我崭新的脚踏车都快踩出火星了。"] = "Хорошо бы и мне зарабатывать лёжа, а мой новенький велосипед от педалирования уже искрит.",
    ["真希望珍妮能实现愿望，考上廷根技术学校。"] = "Я очень надеюсь, что Дженни сможет реализовать свое желание и поступить в Тингенскую техническую школу.",
    ["真抱歉，我光顾着悲伤了，忘了招待您。"] = "Простите, я так погрузился в печаль, что забыл вас принять.",
    ["真是一场厄难，所幸你们获得了平安。"] = "Какая катастрофа, к счастью, вы все оказались в безопасности.",
    ["真是不巧。看来只能期待下次见面再聊了。"] = "Как жаль. Кажется, нам придется подождать до следующего раза, чтобы поговорить.",
    ["真是个不错的朋友，不是吗？"] = "Довольно хороший друг, не так ли?",
    ["真是年轻人啊，我也曾以为自己是最特殊的人。但很多人研究一辈子，也只能看懂上面几个单词。"] = "Какой молодой человек. Я тоже когда-то думал, что я самый особенный человек. Но многие люди учатся всю жизнь и могут понять по ним лишь несколько слов.",
    ["真是有趣的旅途，就是有点麻烦。他的东西都湿透了。"] = "Занятное путешествие, только немного хлопотное. Все его вещи промокли насквозь.",
    ["真是的，什么时候才能直达迪西海湾？我可不想再坐船去了，太难受了！"] = "Действительно, когда появится прямой путь в Дези Бэй? Я больше не хочу брать лодку, это слишком неудобно!",
    ["真是长大了啊……"] = "Ты действительно повзрослел...",
    ["真的吗？我得救了？"] = "Действительно? Я спасен?",
    ["真的吗？这是我们的荣幸，我为您登记会员情况。"] = "Правда? Для нас это большая честь. Сейчас я оформлю ваше членство.",
    ["真的没什么！我要去上学了！"] = "Правда, ничего такого! Я иду в школу!",
    ["真的？是哪两份？"] = "Действительно? Какие два?",
    ["真的？看在脚踏车的份上，为您效劳，{{先生|女士}}。"] = "Действительно? Ради велосипеда я буду к твоим услугам, {{sir|madam}}.",
    ["睡吧睡吧，明天要上班了……"] = "Спи, спи, завтра на работу...",
    ["睡醒又饿了……转运仪式用的面包，刚好可以吃掉。"] = "Проснулся снова голодным... хлебом, использованным для ритуала изменения судьбы. просто правильно есть.",
    ["瞧瞧，你现在简直像刚从水沟里爬出来，并且被马车来回碾过三四遍。"] = "Полюбуйся на себя: выглядишь так, словно только что вылез из канавы, а сверху по тебе пару-тройку раз проехал экипаж.",
    ["瞧瞧，多漂亮的人偶！"] = "Взгляните, какая красивая кукла!",
    ["知识皇冠因污染而活化出逃……幕后的力量或许是堕落母神？"] = "Корона Знаний активировалась и исчезла из-за порчи... Может ли закулисная сила быть Богиней-Матерью Разврата?",
    ["知道了。"] = "Понял.",
    ["短时间内你就遇到了多次危险，但我们不可能时刻保护你，你需要有自保的能力。"] = "Вы сталкивались с опасностью несколько раз за короткий период времени, но мы не можем защитить вас всегда. Вам нужна способность защитить себя.",
    ["短长长长"] = "Короткий-Длинный-Длинный-Длинный",
    ["确实"] = "Действительно",
    ["确实很可惜。"] = "Действительно жаль.",
    ["确实有种成熟、值得信赖的感觉了。"] = "И правда появилось ощущение зрелости и надежности.",
    ["确实，他经常和卷毛狒狒一样，只在乎摆在眼前的几根香蕉。"] = "И правда: он частенько ведет себя как курчавошерстный павиан, которого волнуют только бананы прямо перед носом.",
    ["确实，这么花哨的衣服，可不适合穿去公司工作，毕竟雇主们往往更喜欢稳重一些的员工。"] = "Действительно, для работы в компании такая яркая одежда не подойдет. Ведь работодатели часто отдают предпочтение более стабильным сотрудникам.",
    ["祂两臂张开，双脚在上，头部如同吊坠般垂下。\n邓恩：不可直视神！"] = "Его руки раскинуты, ноги вверху, а голова свисает вниз, словно кулон.\nДанн: Не смотри прямо на Бога!",
    ["祂擅长窃取，窃取物品、念头、能力，甚至时间、天气、身份和命运。"] = "Он искусен в краже: крадёт предметы, мысли, способности, и даже время, погоду, личность и судьбу.",
    ["祂试图用无限的死亡摧残和污染你的意志，迫使你承认是祂的子嗣。"] = "Она пытается использовать бесконечную смерть, чтобы разрушить и развратить вашу волю, заставляя вас признать, что вы — Ее потомство.",
    ["祈求这面镜子获得短暂的还原，祈求它呈现出过去一个月映照过的所有人。"] = "Я молюсь, чтобы это зеркало было ненадолго восстановлено, и я молюсь, чтобы оно показало всех, кого оно отражало за последний месяц.",
    ["祝你们好运，相信你们能摧毁魔镜，拯救大家。"] = "Удачи. Я верю, что ты сможешь уничтожить Зеркало Отчаяния и спасти всех.",
    ["神仆和神仆的差别，比人和卷毛狒狒还要大。"] = "Разница между рабом Божьим и другим больше, чем между человеком и кудрявым павианом.",
    ["神明把我们当做交易的棋子和代价，让我们背负污染，背负作为邪神子嗣的命运……"] = "Боги сделали из нас разменные фигуры и плату в своих сделках, заставили нести скверну и судьбу отпрысков злых богов...",
    ["神神秘秘，鬼鬼祟祟，一定有鬼。"] = "Скрытный и коварный, должно быть, происходит что-то подозрительное.",
    ["神秘男子朝绯红意志扔出一枚金币，而金币逐渐蔓延出灰雾。\n这些灰雾包裹住绯红意志，成功地封印了它。"] = "Загадочный мужчина бросил золотую монету в сторону Багровой Воли, и от монеты заклубился серый туман.\nСерый туман окутал Багровую Волю и запечатал её.",
    ["神秘男子：“离开噩梦，回到现实。”"] = "Таинственный мужчина: «Оставь кошмар и вернись в реальность».",
    ["祭台的位置。"] = "Расположение алтаря.",
    ["福利待遇还不错，同事们看起来也很友善，希望之后能一切顺利……"] = "Условия вполне приличные, да и коллеги кажутся очень дружелюбными. Надеюсь, дальше всё пойдёт как по маслу...",
    ["福生玄黄上帝"] = "Бог Фу Шэн Сюань Хуан",
    ["福生玄黄仙尊"] = "Фу Шэн Сюань Хуан Бессмертный Почтенный",
    ["福生玄黄天君"] = "Фу Шэн Сюань Хуан Тянь Цзюнь",
    ["福生玄黄天尊"] = "Небесные, достойные Неба и Земли для благословений",
    ["离开"] = "Оставлять",
    ["科尔顿伯爵！"] = "Граф Колтон!",
    ["科恩黎，队长说让我跟你换一下晚上的值班，麻烦你了。"] = "Кенли, капитан сказал, что мне следует поменяться с тобой ночной сменой. Извините за беспокойство.",
    ["称赞名气"] = "Похвалить известность",
    ["称赞年轻"] = "Комплимент молодости",
    ["称赞珠宝店"] = "Сделайте комплимент ювелирному магазину",
    ["移动后转身"] = "Переместиться и повернуться",
    ["稍等一会"] = "Подождите немного",
    ["空镜"] = "Пустое зеркало",
    ["空闲的时候还能画几笔，比如队长找烟斗、戴莉逗罗珊、老尼尔教克莱恩填报销单、西迦洛耀和科恩黎打牌……"] = "Когда я свободен, я все еще могу нарисовать несколько набросков, например, Капитана, ищущего свою трубку, Дейли, дразнящего Розанну, Старины Нила, обучающего Клейн заполнять формы возмещения, Сига, Ло Яо и Кенли, играющих в карты...",
    ["穿越"] = "Трансмиграция",
    ["穿越者？"] = "Переселенец?",
    ["突发心脏病，没发现其他异常。"] = "Внезапный инфаркт, других отклонений не обнаружено.",
    ["突然，塔罗牌飞旋出现，切断你和伊妮德身上的藤蔓。\n烛火熄灭，皮特怒：什么人？\n一团灰雾包裹着莹莹亮光，从空中落下。\n灰雾逐渐消散，雾后的男子脱下礼帽，微微躬身。"] = "Внезапно с шелестом метнулись карты Таро, рассекая оплётшие вас с Энид лозы.\nСвеча погасла, и Пит в ярости воскликнул: «Кто здесь?!»\nКлубы серого тумана, окутанные мерцающим сиянием, опустились с высоты.\nСерый туман постепенно рассеялся, и стоящий за ним мужчина снял цилиндр и слегка поклонился.",
    ["突然，塔罗牌飞旋出现，解救了你和伊妮德，也熄灭了仪式的烛火。它的主人是——\n“一个路过的，值夜者”。"] = "Внезапно взметнувшиеся карты Таро спасли вас с Энид и погасили свечи ритуала. А их хозяин —\n«проходящий мимо Ночной Ястреб».",
    ["突然，浓雾四起，飞速将街道和视野遮掩。克莱恩在雾里有点慌张，开始四处观察：“这，也是非凡能力吗？”"] = "Внезапно поднимается густой туман, быстро закрывая улицу и его поле зрения. Клейн немного паникует в тумане и начинает наблюдать за происходящим вокруг: «Это тоже способность Потустороннего?»",
    ["窗外的阳光很好，照在身上暖洋洋的……"] = "За окном чудесное солнце, его лучи приятно согревают тело...",
    ["窗外红月西斜，逐渐下沉，\n直至东方有微光亮起，地平线染上金色……"] = "За окном алая луна клонится к западу, медленно опускаясь,\nпока на востоке не забрезжит слабый свет и горизонт не окрасится в золото...",
