    ["结束询问"] = "Завершить допрос",
    ["结果怎么样？"] = "Как результат?",
    ["给予回应"] = "Ответить",
    ["给他治疗药剂"] = "Дайте ему лечебное зелье",
    ["给劳维斯安葬费"] = "Отдайте Ловису расходы на похороны.",
    ["给我一份吧。"] = "Дайте мне копию.",
