    ["金币可以帮你压制污染，同时提升你的灵性感知。"] = "Золотая монета может помочь вам подавить Искажение и одновременно повысить вашу духовность.",
    ["金毛大狗似乎读懂了主人话里的情绪，跳起来蹭了蹭主人的手，随后扭头向前走去。"] = "Золотоволосая собака, кажется, понимает эмоции в словах своего хозяина, подпрыгивает, чтобы потереться о руку хозяина, а затем поворачивается и идет вперед.",
    ["金钱诱惑"] = "Искушение деньгами",
    ["钟声吓走了那群阿蒙分身，而威尔在危急关头使用了“重启”，让时间回到了你成为阿蒙分身以前。"] = "The bell toll scared away the group of Amon Avatars, and Will used \"Restart\" at the critical moment, turning time back to before you became an Amon Avatar.",
    ["铁十字街\n路人们穿过街道，有的与摊主讨价还价，有的匆匆前行。\n一只猫从小摊的桌面上跑过。\n在角落里皮特带着伊妮德一闪而过。"] = "Улица Железного Креста\nПрохожие спешат по улице: одни торгуются у лотков, другие торопливо шагают мимо.\nКошка быстро пробегает по прилавку лавки.\nВ углу мелькнули Пит и Энид.",
    ["铁十字街，路人穿过街道，有的跟摊主讨价还价，有的匆匆前行。\n一只小猫从小摊的桌面跑过。\n角落里，皮特带伊妮德在人群中一闪而过。"] = "Улица Железного Креста: прохожие снуют туда-сюда, одни торгуются с лавочниками, другие торопливо идут по своим делам.\nШустрый котёнок перебегает по прилавку с товарами.\nВ углу улицы в толпе мелькают силуэты Пита и Инид.",
    ["铜镜上有刺客途径的魔法，会让携带者隐入阴影，还是打开隐藏空间的钥匙。"] = "На медном зеркале есть магия Пути Ассасина, которая позволяет носителю скрываться в тени, а также является ключом к открытию скрытого пространства.",
    ["铜镜的碎片……难道他们就是失踪的市民？"] = "Осколки бронзового зеркала... могли ли они быть пропавшими гражданами?",
    ["错了，我很重视他们。蚂蚁试图搬起比自己重的食物，比任何戏剧都精彩。"] = "Wrong, I value them very much. Ants trying to carry food heavier than themselves is more spectacular than any drama.",
    ["错过的朋友无法再拯救，就像扔掉的海报不会再回来。"] = "Friends who have been missed can no longer be saved, just like a discarded poster will never return.",
    ["镜中世界的献祭仪式开始时，现实的五月庄园也发生了异变。"] = "Когда начался Ритуал Жертвоприношения в зеркальном мире, в реальности в Мэй Мэнор также произошли аномалии.",
    ["镜中廷根开始瓦解了！"] = "Тинген в зеркале начинает распадаться!",
    ["镜中廷根瓦解后，我在集体潜意识里停留了一段时间，尝试安抚他们的亲人，让悲伤变得……温和一些。"] = "После того, как «Тинген в зеркале» распался, я какое-то время оставался в коллективном подсознании, пытаясь усмирить их родственников и сделать печаль... немного мягче.",
    ["镜中廷根的事还没完全结束，我们最近在追查序列3阿蒙分身的踪迹，清理被污染的阿蒙分身。而这件事，和你有关。"] = "The matter of Tingen in the Mirror hasn't fully concluded yet. We have recently been tracking the traces of a Sequence 3 Amon Avatar and cleaning up corrupted Amon Avatars. And this matter concerns you.",
    ["镜子是通向未知、通向灵性世界的大门……"] = "Зеркало – это врата в неизведанное, в мир духовности...",
    ["镜子的碎片……"] = "Фрагменты зеркала...",
    ["长短长长"] = "Длинный-короткий-длинный-длинный",
    ["长长短长"] = "Длинный-длинный-короткий-длинный",
    ["门后是什么？"] = "Что находится за дверью?",
    ["门外的男人"] = "The man outside the Door",
    ["门外的男人，也是你们的家人吗？"] = "Is the man outside the Door also a member of your family?",
    ["闭上眼睛，双手抬起，放在眼前，食指相对，但不要碰到。"] = "Закройте глаза, поднимите руки, расположите их перед глазами указательными пальцами друг к другу, но не соприкасайтесь.",
    ["阁下，尝试结束了吗？可以让我们回去了吗？"] = "Ваше Превосходительство, покушение окончено? Можете ли вы позволить нам вернуться?",
    ["阁下，您能拉我们来到这里，拥有我们无法想象的伟力。您做的见证，不管是我，还是她，都不敢违背。"] = "Ваше Превосходительство, вы можете притащить нас сюда и обладать силой, превосходящей наше воображение. Ни я, ни она не осмелились бы нарушить показания свидетеля, которого вы предоставили.",
    ["阁下，我们该怎么称呼您？"] = "Ваше Превосходительство, как нам следует к Вам обратиться?",
    ["阁下，请问该怎么称呼您？"] = "Ваше Превосходительство, как нам следует к Вам обратиться?",
    ["阅读"] = "Читать",
    ["阅读信件"] = "Прочтите письмо",
    ["阅读完毕"] = "Закончил чтение",
    ["阅读报纸"] = "Читать газету",
    ["阅读第一页罗塞尔日记"] = "Прочтите первую страницу дневника Розеллы.",
    ["阅读第三页罗塞尔日记"] = "Прочтите третью страницу дневника Розеллы.",
    ["阅读第二页罗塞尔日记"] = "Прочтите вторую страницу дневника Розеллы.",
    ["队友……"] = "Товарищи по команде...",
    ["队长……"] = "Капитан...",
    ["队长……哦，是的！他有提到过你，稍等一下。"] = "Капитан... О, да! Он упомянул тебя. Момент.",
    ["队长呢？"] = "Где капитан?",
    ["队长回来了，让你去他<P_Yellow>办公室</>一趟。不过，队长脸色异常苍白，不知道发生了什么事。"] = "Капитан вернулся, он хочет, чтобы вы пошли в его офис <P_Yellow></>. Однако лицо капитана необычайно бледно, я не знаю, что произошло.",
    ["队长在查尼斯门旁的值班室里。"] = "Капитан находится в дежурке рядом с воротами Чанис.",
    ["队长怎么看起来像是……睡着了？"] = "Почему капитан выглядит так, будто он... спит?",
    ["队长怎么说？"] = "Что говорит капитан?",
    ["队长您好，我是刚加入的新员工{{PlayerName}}。"] = "Здравствуйте, капитан. Я {{PlayerName}}, новый сотрудник.",
    ["队长说破格让我成为非凡者，我现在去找尼尔先生。"] = "Капитан сказал, что в порядке исключения позволит мне стать Потусторонним. Пойду разыщу мистера Нила.",
    ["队长说这是条不完整的途径，之后的序列我需要自己再想办法……不过现在想这些还太早了。"] = "Капитан сказал, что это неполный путь, и мне нужно самому найти путь для последующих последовательностей... но об этом еще рано думать.",
    ["队长说，我们是守护者，也是一群时刻对抗着危险和疯狂的可怜虫。"] = "Капитан сказал, что мы стражи, а также группа несчастных, которые постоянно борются с опасностями и безумием.",
    ["队长，你怎么了？"] = "Капитан, что с вами случилось?",
    ["队长，你来了。"] = "Капитан, вы здесь.",
    ["队长，你说得像我是个变态。"] = "Капитан, вы так говорите, будто я извращенец.",
    ["队长，你还好吗？"] = "Капитан, вы в порядке?",
    ["队长，大家都没事。"] = "Капитан, все в порядке.",
    ["队长，带他回去吧，暂时没有理由再怀疑他了。"] = "Капитан, возьмите его обратно. На данный момент нет никаких оснований подозревать его.",
    ["队长，我……"] = "Капитан, я...",
    ["队长，我似乎知道那本笔记在哪里了！"] = "Капитан, кажется, я знаю, где этот блокнот!",
    ["队长，我刚刚遇到了一件超凡事件。"] = "Капитан, я только что столкнулся с необычным событием.",
    ["队长，我有事情汇报。"] = "Капитан, мне нужно кое-что сообщить.",
    ["队长，我来了……你们在干什么？"] = "Капитан, я здесь... Что вы делаете?",
    ["队长，海纳斯·凡森特——<P_Yellow>死了</>。"] = "Капитан Хейнс Винсент — <P_Yellow>dead</>.",
    ["队长，还有别的事吗？"] = "Капитан, есть что-нибудь ещё?",
    ["阻止他"] = "Останови его",
    ["阿兹克走进了办公室。"] = "Азик заходит в офис.",
    ["阿兹克，你怎么还不进来？"] = "Азик, почему ты еще не зашел?",
    ["阿尔杰站在甲板上，手上托着一个古怪的玻璃瓶，自言自语：“还差鬼鲨的血……”"] = "Алджер стоит на палубе, держа странную стеклянную бутылку, и бормочет себе под нос: «Все еще не хватает крови Призрачной Акулы...»",
    ["阿罗德斯触手抬起，把一团光点抛入了源堡上方的深红星辰。"] = "Арродес поднял щупальца и бросил пучок света в малиновую звезду над замком Сефира.",
    ["除了刚刚克莱恩提到的惨案，这里有份调查报告。"] = "Помимо трагедии, о которой только что упомянул Клейн, вот отчет о расследовании.",
    ["除了卡尔和托尼，还有安迪、鲍伯、凯尔、<P_Yellow>迪伦</>。"] = "Besides Carl and Tony, there are also Andy, Bob, Kyle, and <P_Yellow>Dylan</>.",
    ["除了卡尔和托尼，还有安迪、鲍伯、凯尔、迪伦。"] = "Помимо Карла и Тони, есть Энди, Боб, Кайл и Дилан.",
    ["除了报纸，还有罗塞尔大帝的海报、明信片和邮票。"] = "Кроме газет, здесь есть плакаты, открытки и марки с императором Розелем.",
    ["除了有个死人，这里一切正常……"] = "Если не считать трупа, здесь все нормально...",
    ["除此之外，他们也会获得一些身体素质上的提升，能忍耐寒冷、腐烂和死亡气息的侵蚀。"] = "Кроме того, они также улучшат физическую форму, смогут противостоять разрушению холода, гниению и ауре смерти.",
    ["随时乐意为您效劳，这是我的名片。"] = "Всегда рад служить вам. Вот моя визитная карточка.",
    ["随着戴里克的讲述，白银之城的历史仿佛在克莱恩眼前缓缓展开。"] = "По словам Деррика, история Серебряного города, кажется, медленно разворачивается перед глазами Клейн.",
    ["随着邓恩的讲述，克莱恩仿佛也步入了那个梦境。"] = "Как рассказывает Данн, Клейн чувствует себя так, как будто он тоже вошел в этот сон.",
    ["隐瞒并不是一个好选择。"] = "Сокрытие — не лучший выбор.",
    ["隐秘？"] = "Сокрытое?",
    ["难不成是邓恩队长提到过的，非凡者的失控？但是，他又为什么会突然失控？"] = "Может быть, это то, о чем говорил капитан Данн, потеря контроля над Потусторонним? Но почему он вдруг потерял контроль?",
    ["难不成，克莱恩，你面试通过了？"] = "Может быть, Клейн, ты прошел собеседование?",
    ["难不成，就是指这个占卜家？"] = "Может быть, он имеет в виду этого Провидца?",
    ["难怪我突然吃起蛋糕，喝起酒，还把自己当成别人……"] = "No wonder I suddenly started eating cake, drinking wine, and treating myself as someone else...",
    ["难怪要不同的内脏器官……抱歉，让你回忆起不好的事情了。"] = "Недаром ему нужны были другие внутренние органы... Извините, я заставил вас вспомнить плохое.",
    ["难怪迈尔先生提到，苜蓿号上所有人像被恶魔附身一样。"] = "Неудивительно, что г-н Мейер упомянул, что все на «Кловере», похоже, одержимы демонами.",
    ["难道你想在同学十六岁生日晚宴时，还穿旧的裙子？"] = "Только не говори мне, что хочешь надеть старое платье на вечеринку по случаю шестнадцатилетия одноклассника?",
    ["难道就是这辆……这也算是“最新款”？"] = "Может быть, это оно... Это считается «последней моделью»?",
    ["难道是受了太大打击，她精神出问题了？可惜灵视被打断了，看来只能尊重命运的安排。"] = "Может быть, она получила слишком сильный удар и ее психическое состояние нестабильно? Жаль, что видение духа прервалось. Кажется, я могу только уважать обустройство судьбы.",
    ["雕像发出祭祀邪神的呓语，诱使你向前走去"] = "Скульптуры издают шепот о жертвоприношениях злым богам, соблазняя вас идти вперед.",
    ["需要先进行一些心理治疗，稳定{{他|她}}的精神。大家辛苦了，接下来交给我吧。"] = "Сначала нам нужно провести психотерапию, чтобы стабилизировать разум {{ his| her}}. Спасибо всем за вашу тяжелую работу; остальное оставь мне.",
    ["需要反思一下自己"] = "Нужно задуматься о себе",
    ["需要帮忙吗？"] = "Вам нужна помощь?",
    ["非凡也不是一条安全的道路，或者说它更加危险不可控。"] = "Путь Потустороннего небезопасен, точнее, он еще более опасен и неконтролируем.",
    ["非凡事件就是这样，危险和疯狂就隐藏在日常生活的背后。"] = "Вот такие чрезвычайные события; опасность и безумие скрываются за повседневной жизнью.",
    ["非凡事件真的太可怕了……但只有变强，才有能应对事件的能力，不再让更多的人受到伤害。"] = "Инциденты за гранью действительно ужасны... но только став сильнее, я смогу справиться с такими событиями и предотвратить ранения большего числа людей.",
    ["非凡事件？"] = "Потусторонний инцидент?",
    ["非凡力量"] = "Потусторонняя сила",
    ["非凡力量要对普通人保密，警察身份更方便查案。"] = "Потусторонние силы должны храниться в секрете от обычных людей, а полицейское удостоверение делает расследование дел более удобным.",
    ["非凡的领域总是扭曲和违背常理的，它的影响与结束都不是我们能够预见和控制的。"] = "Необыкновенное царство всегда искажено и противоречит здравому смыслу; ни его влияние, ни его конец не могут быть предвидены или проконтролированы нами.",
    ["非凡者"] = "Потусторонний",
    ["非凡者和你想象的并不一样，我们一直在与危险同行，所以你一定要谨慎选择。"] = "Потусторонние — это не то, что вы себе представляете. Мы всегда идем с опасностью, поэтому выбирать нужно осторожно.",
    ["非凡者的敌人不仅仅是邪教徒、黑巫师，还有自己！几乎每年都有人失控和牺牲！你不害怕吗？不考虑家人的感受吗？"] = "Врагами Потусторонние являются не только культисты и темные колдуны, но и они сами! Почти каждый год люди теряют контроль и жертвуют собой! Ты не боишься? Разве вы не учитываете чувства своей семьи?",
    ["非凡能力"] = "Потусторонняя способность",
    ["非常不错。"] = "Очень хороший.",
    ["非常好，我们开始吧，塔罗会第一次集会。"] = "Очень хорошо, начнем, первое собрание Клуба Таро.",
    ["非常差。"] = "Очень плохо.",
    ["非常感谢"] = "Большое спасибо",
    ["非常感谢。对了，请问会计太太在哪里？"] = "Большое спасибо. Кстати, не подскажете, где госпожа бухгалтер?",
    ["非常感谢，斯林太太，您今天真像个年轻又活泼的女士。"] = "Большое спасибо, миссис Стин, вы сегодня выглядите молодой и оживленной леди.",
    ["非常担心"] = "Очень волнуюсь",
    ["非常期待"] = "Очень жду",
    ["非常棒的想法"] = "Это отличная идея",
    ["非常棒！我感觉好多了，谢谢。"] = "Это фантастика! Я чувствую себя намного лучше, спасибо.",
    ["靠近伦纳德"] = "Рядом с Леонардом",
    ["靠近公园入口，传来急促自行车铃声。\n单片眼镜邮差，骑车（豪华版）在面前刹停。\n邮差离开时，你看到一个身影在公园门口一闪而过，他让你回想起廷根湖仪式。"] = "При приближении к воротам парка раздается звонкий велосипедный звонок.\nПочтальон с моноклем в глазу резко тормозит перед вами на своем велосипеде (люксовой модели).\nКогда почтальон уезжает, у входа в парк на миг мелькает чей-то силуэт, напомнив вам о ритуале на озере Тингена.",
    ["鞋底的灰"] = "Пыль на подошвах",
    ["韦尔奇先生用头撞墙，撞了很多下，撞得满墙都是血。"] = "Мистер Уэлч много раз ударялся головой о стену, заливая стену кровью.",
    ["韦尔奇和娜娅的案子已经完结，但那本<P_Yellow>安提哥努斯家族的笔记</>也失踪了。"] = "Дело Уэлча и Найи завершено, но <P_Yellow>Антигон Notebook</> также пропал.",
    ["韦尔奇家丢失了一把<P_Yellow>左轮手枪</>，应该还在你那里吧？"] = "В доме Уэлча пропал <P_Yellow>револьвер</>... Он ведь всё ещё у тебя?",
    ["颂念尊名"] = "Повторяйте почетное имя",
    ["预留好新家房租后，应该还剩下不少钱，足够每人都买一套新衣服。"] = "После того, как вы отложите арендную плату за новый дом, у вас должно остаться достаточно денег, чтобы каждый мог купить новый комплект одежды.",
    ["风景……窗边风景才好，我们一起去看看！"] = "Scenery... The scenery by the window is the best, let's go take a look together!",
    ["首先是对我的<P_Yellow>称呼</>……"] = "Во-первых, что касается моего почетного звания <P_Yellow> </>...",
